import type { AstropressWordPressImportEntityCount } from "../platform-contracts";
import {
	countMatches,
	escapeRegExp,
	filenameFromUrl,
	getAttributeValue,
	getBlocks,
	getTagText,
	inferMimeType,
	normalizeContentStatus,
	normalizePathname,
	normalizeSlug,
	parseCategoryBlocks,
	safeArtifactFilename,
} from "./wordpress-xml-helpers";
import {
	WP_ATTR,
	WP_CATEGORY_DOMAIN,
	WP_COMMENT_APPROVED_VALUE,
	WP_META_KEY_OLD_SLUG,
	WP_POST_TYPE,
	WP_REDIRECT_REASON_OLD_SLUG,
	WP_TAG,
} from "./wordpress-xml-tags-data";

export type ParsedAuthor = {
	id: string;
	login: string;
	email?: string;
	displayName: string;
};

export type ParsedTerm = {
	kind: "category" | "tag";
	slug: string;
	name: string;
};

export type ParsedRedirect = {
	id: string;
	sourcePath: string;
	targetPath: string;
	reason: string;
	recordId: string;
};

export type ParsedComment = {
	id: string;
	legacyId: string;
	recordId: string;
	authorName: string;
	authorEmail?: string;
	body: string;
	status: "approved" | "pending";
	createdAt?: string;
};

export type ParsedContentRecord = {
	id: string;
	legacyId: string;
	kind: "post" | "page";
	slug: string;
	title: string;
	body: string;
	excerpt?: string;
	status: "draft" | "published" | "archived";
	legacyUrl: string;
	publishedAt?: string;
	authorLogins: string[];
	categorySlugs: string[];
	tagSlugs: string[];
	oldSlugs: string[];
};

export type ParsedMediaAsset = {
	id: string;
	legacyId: string;
	slug: string;
	title: string;
	sourceUrl: string;
	legacyUrl: string;
	filename: string;
	mimeType: string;
	parentLegacyId?: string;
};

export type ParsedBundle = {
	authors: ParsedAuthor[];
	terms: ParsedTerm[];
	contentRecords: ParsedContentRecord[];
	mediaAssets: ParsedMediaAsset[];
	comments: ParsedComment[];
	redirects: ParsedRedirect[];
	entityCounts: AstropressWordPressImportEntityCount;
	remediationCandidates: string[];
	unsupportedPatterns: string[];
	warnings: string[];
};

export function detectUnsupportedPatterns(source: string) {
	const shortcodeMatches = countMatches(source, /\[[a-z][^\]]*\]/gi);
	const builderMatches = countMatches(source, /(elementor|vc_row|wp-block-|et_pb_|fusion_)/gi);
	const unsupportedPatterns: string[] = [];
	const warnings: string[] = [];

	if (shortcodeMatches > 0) {
		unsupportedPatterns.push("shortcodes");
		warnings.push("WordPress shortcodes were detected; staged content will need manual review.");
	}
	if (builderMatches > 0) {
		unsupportedPatterns.push("page-builder-markup");
		warnings.push(
			"WordPress page-builder markup was detected; staged content will need manual cleanup.",
		);
	}

	return { shortcodeMatches, builderMatches, unsupportedPatterns, warnings };
}

export function parseWordPressExport(source: string): ParsedBundle {
	const authors: ParsedAuthor[] = getBlocks(source, WP_TAG.AUTHOR).map((block, index) => ({
		id: getTagText(block, WP_TAG.AUTHOR_ID) || `author-${index + 1}`,
		login: normalizeSlug(getTagText(block, WP_TAG.AUTHOR_LOGIN), `author-${index + 1}`),
		email: getTagText(block, WP_TAG.AUTHOR_EMAIL) || undefined,
		displayName:
			getTagText(block, WP_TAG.AUTHOR_DISPLAY_NAME) ||
			getTagText(block, WP_TAG.AUTHOR_LOGIN) ||
			`Author ${index + 1}`,
	}));

	const termsByKey = new Map<string, ParsedTerm>();
	const contentRecords: ParsedContentRecord[] = [];
	const mediaAssets: ParsedMediaAsset[] = [];
	const comments: ParsedComment[] = [];
	const redirects: ParsedRedirect[] = [];
	let skipped = 0;

	for (const [index, item] of getBlocks(source, WP_TAG.ITEM).entries()) {
		const legacyId = getTagText(item, WP_TAG.POST_ID) || `item-${index + 1}`;
		const postType = getTagText(item, WP_TAG.POST_TYPE).toLowerCase();
		const postStatus = normalizeContentStatus(getTagText(item, WP_TAG.STATUS));
		const title = getTagText(item, WP_TAG.TITLE) || `Untitled ${legacyId}`;
		const legacyUrl = normalizePathname(
			getTagText(item, WP_TAG.LINK) || getTagText(item, WP_TAG.GUID),
			normalizeSlug(getTagText(item, WP_TAG.POST_NAME), legacyId),
		);
		const slug = normalizeSlug(
			getTagText(item, WP_TAG.POST_NAME),
			legacyUrl
				.replace(/^\/|\/$/g, "")
				.split("/")
				.at(-1) || legacyId,
		);
		const body = getTagText(item, WP_TAG.CONTENT_ENCODED);
		const excerpt = getTagText(item, WP_TAG.EXCERPT_ENCODED);
		const publishedAt =
			getTagText(item, WP_TAG.POST_DATE_GMT) || getTagText(item, WP_TAG.POST_DATE) || undefined;

		const oldSlugs = getBlocks(item, WP_TAG.POSTMETA)
			.filter((meta) => getTagText(meta, WP_TAG.META_KEY) === WP_META_KEY_OLD_SLUG)
			.map((meta) => normalizeSlug(getTagText(meta, WP_TAG.META_VALUE), "legacy"));

		const categorySlugs: string[] = [];
		const tagSlugs: string[] = [];
		for (const category of parseCategoryBlocks(item)) {
			const domain = getAttributeValue(category.attributes, WP_ATTR.DOMAIN);
			const slugValue = normalizeSlug(
				getAttributeValue(category.attributes, WP_ATTR.NICENAME),
				normalizeSlug(category.value, "term"),
			);
			if (domain === WP_CATEGORY_DOMAIN.CATEGORY) {
				categorySlugs.push(slugValue);
				termsByKey.set(`category:${slugValue}`, {
					kind: "category",
					slug: slugValue,
					name: category.value || slugValue,
				});
			} else if (domain === WP_CATEGORY_DOMAIN.POST_TAG) {
				tagSlugs.push(slugValue);
				termsByKey.set(`tag:${slugValue}`, {
					kind: "tag",
					slug: slugValue,
					name: category.value || slugValue,
				});
			}
		}

		if (postType === WP_POST_TYPE.POST || postType === WP_POST_TYPE.PAGE) {
			const creatorLogin = getTagText(item, WP_TAG.DC_CREATOR);
			const matchedAuthor = creatorLogin
				? authors.find((a) => a.login === creatorLogin)
				: undefined;
			const authorLogins = matchedAuthor
				? [matchedAuthor.login]
				: authors.length > 0
					? [authors[0]?.login]
					: [];

			contentRecords.push({
				id: `${postType}-${legacyId}`,
				legacyId,
				kind: postType,
				slug,
				title,
				body,
				excerpt: excerpt || undefined,
				status: postStatus,
				legacyUrl,
				publishedAt,
				authorLogins,
				categorySlugs,
				tagSlugs,
				oldSlugs,
			});

			for (const oldSlug of oldSlugs) {
				const targetPath = legacyUrl;
				const sourcePath = legacyUrl.replace(new RegExp(`${escapeRegExp(slug)}/?$`), `${oldSlug}/`);
				if (sourcePath !== targetPath) {
					redirects.push({
						id: `redirect-${legacyId}-${oldSlug}`,
						sourcePath,
						targetPath,
						reason: WP_REDIRECT_REASON_OLD_SLUG,
						recordId: `${postType}-${legacyId}`,
					});
				}
			}

			for (const [commentIndex, commentBlock] of getBlocks(item, WP_TAG.COMMENT).entries()) {
				comments.push({
					id: `comment-${legacyId}-${commentIndex + 1}`,
					legacyId:
						getTagText(commentBlock, WP_TAG.COMMENT_ID) || `${legacyId}-${commentIndex + 1}`,
					recordId: `${postType}-${legacyId}`,
					authorName: getTagText(commentBlock, WP_TAG.COMMENT_AUTHOR) || "Anonymous",
					authorEmail: getTagText(commentBlock, WP_TAG.COMMENT_AUTHOR_EMAIL) || undefined,
					body: getTagText(commentBlock, WP_TAG.COMMENT_CONTENT),
					status:
						getTagText(commentBlock, WP_TAG.COMMENT_APPROVED) === WP_COMMENT_APPROVED_VALUE
							? "approved"
							: "pending",
					createdAt:
						getTagText(commentBlock, WP_TAG.COMMENT_DATE_GMT) ||
						getTagText(commentBlock, WP_TAG.COMMENT_DATE) ||
						undefined,
				});
			}
			continue;
		}

		if (postType === WP_POST_TYPE.ATTACHMENT) {
			const sourceUrl = getTagText(item, WP_TAG.ATTACHMENT_URL) || getTagText(item, WP_TAG.GUID);
			const filename = safeArtifactFilename(
				filenameFromUrl(sourceUrl, `${slug || legacyId}.bin`),
				`${slug || legacyId}.bin`,
			);
			mediaAssets.push({
				id: `media-${legacyId}`,
				legacyId,
				slug,
				title,
				sourceUrl,
				legacyUrl,
				filename,
				mimeType: inferMimeType(filename),
				parentLegacyId: getTagText(item, WP_TAG.POST_PARENT) || undefined,
			});
			continue;
		}

		skipped += 1;
	}

	const unsupported = detectUnsupportedPatterns(
		contentRecords.map((r) => `${r.body}\n${r.excerpt ?? ""}`).join("\n"),
	);
	const remediationCandidates = contentRecords
		.filter((r) =>
			/\[[a-z][^\]]*\]|elementor|vc_row|wp-block-|et_pb_|fusion_/i.test(
				`${r.body}\n${r.excerpt ?? ""}`,
			),
		)
		.map((r) => r.id);

	return {
		authors,
		terms: [...termsByKey.values()],
		contentRecords,
		mediaAssets,
		comments,
		redirects,
		entityCounts: {
			posts: contentRecords.filter((r) => r.kind === "post").length,
			pages: contentRecords.filter((r) => r.kind === "page").length,
			attachments: mediaAssets.length,
			redirects: redirects.length,
			comments: comments.length,
			users: authors.length,
			categories: [...termsByKey.values()].filter((t) => t.kind === "category").length,
			tags: [...termsByKey.values()].filter((t) => t.kind === "tag").length,
			skipped,
		},
		remediationCandidates,
		unsupportedPatterns: unsupported.unsupportedPatterns,
		warnings: unsupported.warnings,
	};
}

src/integration-error-sanitizer.ts.source:
/**
 * Single sanitizer for `connected_integrations.last_error` writes and
 * for any error surface the integration UX returns to the browser.
 *
 * Provider verify() callbacks can throw with arbitrary upstream-API
 * payload data (status text, response bodies). Storing or returning
 * those raw bodies risks leaking auth tokens, account names, or
 * internal endpoint URLs through the audit trail / Playwright traces.
 *
 * Every write to last_error or error path must route through
 * `sanitizeIntegrationError` so the column only contains a typed code
 * the UI can localise. The audit at
 * tooling/scripts/audit-integration-secrets.ts enforces this.
 */

import {
	type IntegrationErrorCode,
	KNOWN_INTEGRATION_ERROR_CODES,
} from "./integration-error-sanitizer-data";

export type { IntegrationErrorCode };

export function isIntegrationErrorCode(value: unknown): value is IntegrationErrorCode {
	if (typeof value !== "string") return false;
	return KNOWN_INTEGRATION_ERROR_CODES.has(value as IntegrationErrorCode);
}

/**
 * Reduce an arbitrary error to one of the known codes. The original
 * error message is intentionally discarded — only typed codes are
 * permitted to reach the database or HTTP response body.
 */
export function sanitizeIntegrationError(
	err: unknown,
	hint?: IntegrationErrorCode,
): IntegrationErrorCode {
	if (hint && KNOWN_INTEGRATION_ERROR_CODES.has(hint)) return hint;
	if (err && typeof err === "object" && "code" in err) {
		if (isIntegrationErrorCode(err.code)) return err.code;
	}
	if (err instanceof Error) {
		// Map common network/timeout shapes without relaying message text.
		const name = err.name;
		if (name === "AbortError" || name === "TimeoutError") {
			return "INTEGRATION_TIMEOUT";
		}
		if (name === "TypeError") {
			return "INTEGRATION_NETWORK_ERROR";
		}
	}
	return "INTEGRATION_UNKNOWN_ERROR";
}

src/integrations/oauth/registry.ts.source:
/**
 * In-memory registry of OAuth provider definitions. Phase 6 of
 * integration-honesty.
 *
 * Each registered provider declares the static endpoints + scope set
 * needed to start an authorization-code flow. Client credentials are
 * NOT held in the registry — they live in the running process's env
 * (per-deploy, never sealed) so the registry stays cheap to enumerate
 * and is safe to serialise into the admin UI's "available providers"
 * picker.
 *
 * The actual access/refresh tokens that come back from the IdP are
 * sealed via the Phase 2 envelope into `integration_secrets`, just
 * like Phase 4's bearer-token providers.
 *
 * Domain-pairing: every OAuth provider belongs to a single
 * `IntegrationDomain` (e.g. `"deploy-hooks"` for the GitHub deploy
 * provider) so the same `connected_integrations` row can describe
 * either a bearer-token or an OAuth-token connection. Callers route
 * by `(domain, providerId)` exactly as they do for non-OAuth
 * providers.
 */

import type { IntegrationDomain } from "../registry.js";

export interface OAuthProviderDefinition {
	readonly id: string;
	readonly domain: IntegrationDomain;
	readonly label: string;
	readonly authorizationUrl: string;
	readonly tokenUrl: string;
	readonly scopes: readonly string[];
	readonly clientIdEnv: string;
	readonly clientSecretEnv: string;
	/** Path the IdP should redirect to. Combined with the request origin at start time. */
	readonly redirectPath: string;
}

export class OAuthRegistryError extends Error {
	constructor(
		public readonly code: "DUPLICATE_PROVIDER" | "UNKNOWN_PROVIDER",
		message: string,
	) {
		super(message);
		this.name = "OAuthRegistryError";
	}
}

const registry = new Map<string, OAuthProviderDefinition>();

function key(domain: IntegrationDomain, providerId: string): string {
	return `${domain}|${providerId}`;
}

export function registerOAuthProvider(def: OAuthProviderDefinition): OAuthProviderDefinition {
	const k = key(def.domain, def.id);
	if (registry.has(k)) {
		throw new OAuthRegistryError(
			"DUPLICATE_PROVIDER",
			`OAuth provider ${def.id} already registered for domain ${def.domain}`,
		);
	}
	registry.set(k, def);
	return def;
}

export function getOAuthProvider(
	domain: IntegrationDomain,
	providerId: string,
): OAuthProviderDefinition | undefined {
	return registry.get(key(domain, providerId));
}

export function listOAuthProviders(domain: IntegrationDomain): readonly OAuthProviderDefinition[] {
	const out: OAuthProviderDefinition[] = [];
	for (const [k, v] of registry) {
		if (k.startsWith(`${domain}|`)) out.push(v);
	}
	return out;
}

export function _resetOAuthRegistryForTests(): void {
	registry.clear();
}

src/integrations/oauth/state.ts.source:
/**
 * OAuth state-token issuance and verification.
 *
 * The browser hands the IdP a `state` parameter at the start of an
 * authorization-code flow; the IdP returns it verbatim on callback.
 * The state must therefore:
 *
 *   1. be unforgeable by the IdP (so a malicious IdP can't replay
 *      a captured state to land in a different account's context);
 *   2. carry enough server-side context to resume the flow without
 *      cookies (needed for Cloudflare Workers, where setting a
 *      cookie on the redirect-out is awkward);
 *   3. expire so a captured state can't be replayed indefinitely;
 *   4. be single-use so an attacker can't replay a leaked state
 *      across multiple browser sessions.
 *
 * Wire format: hex(JSON envelope `{n, c, e, s}` UTF-8) where:
 *   - `n` is a 16-byte random nonce (hex);
 *   - `c` is the resume-context payload `{domain, providerId, returnTo}`;
 *   - `e` is the expiry as ms-since-epoch;
 *   - `s` is HMAC-SHA-256(rootSecret, JSON.stringify({n,c,e})) as hex.
 *
 * Hex (rather than base64url) keeps the encode/decode path symmetric,
 * trivially URL-safe with no padding, and easy to mutation-test —
 * the trade-off is roughly 1.6× the wire length of base64url, which
 * is well within typical URL-length budgets for an OAuth state.
 *
 * Defensive parsing is intentionally minimal: we hex-decode, JSON-parse,
 * canonical-serialize the inner under the schema we expect, and check
 * the signature. Any structural difference between the attacker's
 * forgery and a real envelope produces a different signature, so a
 * shape mismatch is automatically caught as INVALID_SIGNATURE rather
 * than via a separate per-field type guard. If `JSON.parse` itself
 * throws, or any property access in the canonicalisation throws, we
 * report INVALID_FORMAT.
 *
 * Replay protection requires a nonce store; this module returns the
 * nonce so the caller can register it with the rate-limit /
 * idempotency table and reject re-uses on callback.
 */

import { bytesToHex, constantTimeEqual } from "../../crypto-primitives.js";

export interface OAuthStateContext {
	readonly domain: string;
	readonly providerId: string;
	readonly returnTo: string;
}

export interface IssuedOAuthState {
	readonly token: string;
	readonly nonce: string;
	readonly expiresAt: number;
}

export interface VerifyOAuthStateOk {
	readonly ok: true;
	readonly nonce: string;
	readonly context: OAuthStateContext;
	readonly expiresAt: number;
}

export type VerifyOAuthStateErrorCode =
	| "INVALID_FORMAT"
	| "INVALID_SIGNATURE"
	| "EXPIRED"
	| "CONTEXT_MISMATCH";

export interface VerifyOAuthStateErr {
	readonly ok: false;
	readonly code: VerifyOAuthStateErrorCode;
}

export type VerifyOAuthStateResult = VerifyOAuthStateOk | VerifyOAuthStateErr;

export interface IssueOAuthStateArgs {
	readonly context: OAuthStateContext;
	readonly rootSecret: string;
	readonly nowMs: number;
	readonly ttlMs?: number;
}

export interface VerifyOAuthStateArgs {
	readonly token: string;
	readonly rootSecret: string;
	readonly nowMs: number;
	readonly expectedContext?: Partial<OAuthStateContext>;
}

export const DEFAULT_OAUTH_STATE_TTL_MS = 600_000;
const NONCE_BYTES = 16;
const textEncoder = new TextEncoder();

export function parseHexBytes(hex: string): Uint8Array | null {
	if (!/^[0-9a-fA-F]+$/.test(hex)) return null;
	if (hex.length % 2 !== 0) return null;
	const out = new Uint8Array(hex.length / 2);
	// Stryker disable next-line EqualityOperator: i <= hex.length is observably equivalent — Uint8Array silently drops out-of-bounds writes, returned bytes are identical.
	for (let i = 0; i < hex.length; i += 2) {
		out[i / 2] = Number.parseInt(hex.slice(i, i + 2), 16);
	}
	return out;
}

interface InnerEnvelope {
	readonly n: string;
	readonly c: OAuthStateContext;
	readonly e: number;
}

export function serializeInnerEnvelope(inner: InnerEnvelope): string {
	return JSON.stringify({ n: inner.n, c: inner.c, e: inner.e });
}

async function hmacSha256Hex(secret: string, message: string): Promise<string> {
	const keyBytes = textEncoder.encode(secret);
	const keyBuf = new ArrayBuffer(keyBytes.byteLength);
	new Uint8Array(keyBuf).set(keyBytes);
	const key = await crypto.subtle.importKey(
		"raw",
		keyBuf,
		{ name: "HMAC", hash: "SHA-256" },
		// Stryker disable next-line BooleanLiteral: extractable does not affect the sign output we test.
		false,
		// Stryker disable next-line StringLiteral: any non-empty usage that includes "sign" works; the operation is what we test.
		["sign"],
	);
	const msgBytes = textEncoder.encode(message);
	const msgBuf = new ArrayBuffer(msgBytes.byteLength);
	new Uint8Array(msgBuf).set(msgBytes);
	const sig = new Uint8Array(
		await crypto.subtle.sign({ name: "HMAC", hash: "SHA-256" }, key, msgBuf),
	);
	return bytesToHex(sig);
}

export async function issueOAuthState(args: IssueOAuthStateArgs): Promise<IssuedOAuthState> {
	const nonce = bytesToHex(crypto.getRandomValues(new Uint8Array(NONCE_BYTES)));
	const ttl = args.ttlMs ?? DEFAULT_OAUTH_STATE_TTL_MS;
	const expiresAt = args.nowMs + ttl;
	const inner: InnerEnvelope = { n: nonce, c: args.context, e: expiresAt };
	const sig = await hmacSha256Hex(args.rootSecret, serializeInnerEnvelope(inner));
	const envelope = JSON.stringify({ ...inner, s: sig });
	const token = bytesToHex(textEncoder.encode(envelope));
	return { token, nonce, expiresAt };
}

interface ParsedEnvelope {
	readonly inner: InnerEnvelope;
	readonly signatureHex: string;
}

/**
 * Decode a token to its inner envelope + signature, or `null` if the
 * token is not a hex-encoded envelope our issuer would have produced.
 *
 * The structural type-coercion below is "trusting": if a forger
 * supplied unexpected types, the canonical re-serialisation under
 * {@link serializeInnerEnvelope} will not round-trip, the recomputed
 * signature won't match, and {@link verifyOAuthState} returns
 * `INVALID_SIGNATURE`. So we only need to guard against shapes that
 * would *throw* during canonicalisation (null, missing nested
 * `.c`, etc.) — every other shape difference is caught by the HMAC
 * check downstream.
 */
export function parseStateEnvelope(token: string): ParsedEnvelope | null {
	const decoded = parseHexBytes(token);
	// Stryker disable next-line ConditionalExpression: equivalent — TextDecoder.decode(null) below throws and the catch returns null with the same outcome.
	if (decoded === null) return null;
	try {
		const parsed = JSON.parse(new TextDecoder().decode(decoded)) as {
			n?: unknown;
			c?: { domain?: unknown; providerId?: unknown; returnTo?: unknown };
			e?: unknown;
			s?: unknown;
		};
		const ctx = parsed.c ?? {};
		const inner: InnerEnvelope = {
			n: String(parsed.n ?? ""),
			c: {
				domain: String(ctx.domain ?? ""),
				providerId: String(ctx.providerId ?? ""),
				returnTo: String(ctx.returnTo ?? ""),
			},
			e: typeof parsed.e === "number" ? parsed.e : 0,
		};
		const signatureHex =
			typeof parsed.s === "string" && /^[0-9a-fA-F]+$/.test(parsed.s) ? parsed.s : "";
		return { inner, signatureHex };
	} catch {
		return null;
	}
}

export async function verifyOAuthState(
	args: VerifyOAuthStateArgs,
): Promise<VerifyOAuthStateResult> {
	const parsed = parseStateEnvelope(args.token);
	if (parsed === null) return { ok: false, code: "INVALID_FORMAT" };
	const lhs = parseHexBytes(parsed.signatureHex);
	if (lhs === null) return { ok: false, code: "INVALID_SIGNATURE" };
	const expectedSig = await hmacSha256Hex(args.rootSecret, serializeInnerEnvelope(parsed.inner));
	const rhs = parseHexBytes(expectedSig);
	if (rhs === null) return { ok: false, code: "INVALID_SIGNATURE" };
	if (!constantTimeEqual(lhs, rhs)) {
		return { ok: false, code: "INVALID_SIGNATURE" };
	}
	if (args.nowMs > parsed.inner.e) {
		return { ok: false, code: "EXPIRED" };
	}
	const exp = args.expectedContext;
	if (exp !== undefined) {
		if (exp.domain !== undefined && exp.domain !== parsed.inner.c.domain) {
			return { ok: false, code: "CONTEXT_MISMATCH" };
		}
		if (exp.providerId !== undefined && exp.providerId !== parsed.inner.c.providerId) {
			return { ok: false, code: "CONTEXT_MISMATCH" };
		}
		if (exp.returnTo !== undefined && exp.returnTo !== parsed.inner.c.returnTo) {
			return { ok: false, code: "CONTEXT_MISMATCH" };
		}
	}
	return {
		ok: true,
		nonce: parsed.inner.n,
		context: parsed.inner.c,
		expiresAt: parsed.inner.e,
	};
}

