import { createAstropressAdminStoreAdapter } from "./admin-store-adapter-factory";
import { peekCmsConfig } from "./config";
import type { AdminStoreAdapter } from "./persistence-types";
import {
	resolveAstropressSqliteAdminRuntimeOptions,
	resolveIntegrationsRepositoryOptions,
} from "./sqlite-admin-runtime-options";
import { buildSqliteAdminStoreModules } from "./sqlite-admin-runtime-wiring";
import { createApiTokenStore } from "./sqlite-runtime/api-tokens";
import { createSqliteAssetsStore } from "./sqlite-runtime/assets";
import { createSqliteAuthStore } from "./sqlite-runtime/auth";
import { createSqliteCatalogStore } from "./sqlite-runtime/catalog";
import { createSqliteContentStore } from "./sqlite-runtime/content";
import { createFlashStore } from "./sqlite-runtime/flash";
import { createIntegrationsRepository } from "./sqlite-runtime/integrations";
import { createSqliteLocksOps } from "./sqlite-runtime/locks";
import { createSqlitePurgeOps } from "./sqlite-runtime/purge";
import { createSqliteRoutesStore } from "./sqlite-runtime/routes";
import { searchContentOverrides } from "./sqlite-runtime/search";
import { createSqliteSettingsStore } from "./sqlite-runtime/settings";
import type { AstropressSqliteDatabaseLike } from "./sqlite-runtime/utils";
import { createWebhookStore } from "./sqlite-runtime/webhooks";
import { ensureFts5SearchIndex } from "./sqlite-schema-compat";

export type { AstropressSqliteDatabaseLike };

export interface AstropressSqliteAdminRuntimeOptions {
	getDatabase(): AstropressSqliteDatabaseLike;
	sessionTtlMs?: number;
	now?: () => number;
	randomId?: () => string;
	rootSecret?: string;
}

export function createAstropressSqliteAdminRuntime(options: AstropressSqliteAdminRuntimeOptions) {
	const { getDb, sessionTtlMs, now, randomId, rootSecret } =
		resolveAstropressSqliteAdminRuntimeOptions(options);

	const { sqliteUserRepository, sqliteAuthRepository, getPersistedAuditEvents } =
		createSqliteAuthStore(getDb, { sessionTtlMs, now, randomId, rootSecret });
	const {
		sqliteRedirectRepository,
		sqliteCommentRepository,
		sqliteTranslationRepository,
		sqliteSettingsRepository,
	} = createSqliteSettingsStore(getDb);

	const { sqliteContentRepository, sqliteSubmissionRepository, sqliteSchedulingRepository } =
		createSqliteContentStore(getDb, randomId);

	const { sqliteCmsRegistryModule } = createSqliteRoutesStore(getDb, randomId);

	const { sqliteAuthorRepository, sqliteTaxonomyRepository } = createSqliteCatalogStore(getDb);
	const { sqliteRateLimitRepository, sqliteMediaRepository } = createSqliteAssetsStore(getDb, now);
	const sqliteApiTokenStore = createApiTokenStore(getDb());
	const sqliteWebhookStore = createWebhookStore(getDb());
	const sqliteFlashStore = createFlashStore(getDb());
	const sqliteLocksOps = createSqliteLocksOps(getDb);
	const sqlitePurgeOps = createSqlitePurgeOps(getDb);
	const sqliteIntegrationsRepository = createIntegrationsRepository(
		resolveIntegrationsRepositoryOptions({ getDb, now }),
	);

	const sqliteAdminStore: AdminStoreAdapter = createAstropressAdminStoreAdapter(
		"sqlite",
		buildSqliteAdminStoreModules({
			getDb,
			sqliteAuthRepository,
			getPersistedAuditEvents,
			sqliteUserRepository,
			sqliteAuthorRepository,
			sqliteTaxonomyRepository,
			sqliteRedirectRepository,
			sqliteCommentRepository,
			sqliteContentRepository,
			sqliteSchedulingRepository,
			sqliteSubmissionRepository,
			sqliteTranslationRepository,
			sqliteSettingsRepository,
			sqliteRateLimitRepository,
			sqliteMediaRepository,
			sqliteApiTokenStore,
			sqliteWebhookStore,
			sqliteFlashStore,
			sqliteIntegrationsRepository,
		}),
	);

	if (peekCmsConfig()?.search?.enabled) {
		ensureFts5SearchIndex(getDb());
	}

	return {
		sqliteAdminStore,
		sqliteCmsRegistryModule,
		authenticatePersistedAdminUser: sqliteAuthRepository.authenticatePersistedAdminUser,
		sqliteLocksOps,
		sqlitePurgeOps,
		searchContentStates: (query: string) => searchContentOverrides(getDb(), query),
	};
}

src/sqlite-runtime/api-tokens-d1.ts.source:
/**
 * D1 sibling of `api-tokens.ts`. Implements the same {@link ApiTokenStore}
 * contract, but every method awaits D1's promise-returning SDK calls. The raw
 * SQL bodies and column lists are byte-for-byte the same as the sqlite store so
 * the two backends produce identical token rows; the only difference is the
 * async driver shape (`.bind().run()` / `.bind().first()` / `.bind().all()`).
 *
 * Why a separate file rather than parameterising `api-tokens.ts`: the sqlite
 * store's `db` is the synchronous `node:sqlite` / `better-sqlite3` surface,
 * while D1 exposes only promise-returning calls. The dispatch seam
 * (`admin-store-dispatch.ts` `resolveApiRuntime`) is the single place that
 * picks the backend, so REST handlers never depend on the local runtime alias
 * on a D1-backed host. See issue #137.
 */

import { randomBytes } from "node:crypto";
import type { D1DatabaseLike } from "../d1-database";
import type { ApiScope, ApiTokenRecord, ApiTokenStore } from "../platform-contracts";
import { hashOpaqueToken } from "./utils";

interface ApiTokenRow {
	id: string;
	label: string;
	scopes: string;
	created_at: string;
	expires_at: string | null;
	last_used_at: string | null;
	revoked_at: string | null;
}

const SELECT_COLUMNS = "id, label, scopes, created_at, expires_at, last_used_at, revoked_at";

function rowToRecord(row: ApiTokenRow): ApiTokenRecord {
	return {
		id: row.id,
		label: row.label,
		scopes: JSON.parse(row.scopes) as ApiScope[],
		createdAt: row.created_at,
		expiresAt: row.expires_at ?? null,
		lastUsedAt: row.last_used_at ?? null,
		revokedAt: row.revoked_at ?? null,
	};
}

export function createD1ApiTokenStore(db: D1DatabaseLike): ApiTokenStore {
	return {
		async create({ label, scopes, expiresAt }) {
			const id = `tok_${randomBytes(12).toString("hex")}`;
			const rawToken = randomBytes(32).toString("hex");
			const tokenHash = hashOpaqueToken(rawToken);
			const now = new Date().toISOString();

			await db
				.prepare(
					"INSERT INTO api_tokens (id, label, token_hash, scopes, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?)",
				)
				.bind(id, label, tokenHash, JSON.stringify(scopes), now, expiresAt ?? null)
				.run();

			const record: ApiTokenRecord = {
				id,
				label,
				scopes,
				createdAt: now,
				expiresAt: expiresAt ?? null,
				lastUsedAt: null,
				revokedAt: null,
			};

			return { record, rawToken };
		},

		async list() {
			const { results } = await db
				.prepare(`SELECT ${SELECT_COLUMNS} FROM api_tokens ORDER BY created_at DESC`)
				.all<ApiTokenRow>();
			return results.map(rowToRecord);
		},

		async verify(rawToken) {
			const tokenHash = hashOpaqueToken(rawToken);
			const row = await db
				.prepare(`SELECT ${SELECT_COLUMNS} FROM api_tokens WHERE token_hash = ?`)
				.bind(tokenHash)
				.first<ApiTokenRow>();

			if (!row) {
				return { valid: false, reason: "Token not found." };
			}

			if (row.revoked_at) {
				return { valid: false, reason: "Token has been revoked." };
			}

			if (row.expires_at && new Date(row.expires_at) < new Date()) {
				return { valid: false, reason: "Token has expired." };
			}

			const now = new Date().toISOString();
			await db
				.prepare("UPDATE api_tokens SET last_used_at = ? WHERE id = ?")
				.bind(now, row.id)
				.run();
			row.last_used_at = now;

			return { valid: true, record: rowToRecord(row) };
		},

		async revoke(id) {
			const now = new Date().toISOString();
			await db.prepare("UPDATE api_tokens SET revoked_at = ? WHERE id = ?").bind(now, id).run();
		},
	};
}

src/sqlite-runtime/audit-log.ts.source:
import { peekCmsConfig } from "../config";
import { buildAuditEntry } from "../persistence-commons";
import type { AstropressSqliteDatabaseLike } from "./utils";

// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
type AuditDetails = Record<string, unknown>;

function parseDetailsJson(value: string | null): AuditDetails | null {
	if (!value) return null;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	return JSON.parse(value) as Record<string, unknown>;
}

export interface AuditEventRecord {
	id: number;
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	details: Record<string, unknown> | null;
	createdAt: string;
}

export interface RecordAuditEventInput {
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId?: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	details?: Record<string, unknown> | null;
}

export function recordAudit(
	db: AstropressSqliteDatabaseLike,
	actor: { email: string },
	action: string,
	summary: string,
	resourceType: string,
	resourceId: string,
): void {
	recordAuditEvent(db, {
		userEmail: actor.email,
		action,
		resourceType,
		resourceId,
		summary,
	});
}

export function recordAuditEvent(
	db: AstropressSqliteDatabaseLike,
	input: RecordAuditEventInput,
): void {
	const entry = buildAuditEntry({
		actor: { email: input.userEmail },
		action: input.action,
		resourceType: input.resourceType,
		resourceId: input.resourceId,
		summary: input.summary,
		details: input.details,
	});
	db.prepare(
		`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, details)
     VALUES (?, ?, ?, ?, ?, ?)`,
	).run(
		entry.userEmail,
		entry.action,
		entry.resourceType,
		entry.resourceId,
		entry.summary,
		entry.details,
	);

	const retentionDays = peekCmsConfig()?.auditRetentionDays ?? 90;
	if (retentionDays > 0) {
		db.prepare(
			`DELETE FROM audit_events WHERE created_at < datetime('now', '-' || ? || ' days')`,
		).run(retentionDays);
	}
}

export function listAuditEvents(
	db: AstropressSqliteDatabaseLike,
	options: { limit?: number; offset?: number; resourceId?: string } = {},
): AuditEventRecord[] {
	const limit = options.limit ?? 50;
	const offset = options.offset ?? 0;

	// audit-boundary: opaque-passthrough -- raw rows from driver; mapped below at row-shape boundary
	let rows: unknown[];
	if (options.resourceId) {
		rows = db
			.prepare(
				`SELECT id, user_email, action, resource_type, resource_id, summary, details, created_at
         FROM audit_events
         WHERE resource_id = ?
         ORDER BY created_at DESC
         LIMIT ? OFFSET ?`,
			)
			.all(options.resourceId, limit, offset);
	} else {
		rows = db
			.prepare(
				`SELECT id, user_email, action, resource_type, resource_id, summary, details, created_at
         FROM audit_events
         ORDER BY created_at DESC
         LIMIT ? OFFSET ?`,
			)
			.all(limit, offset);
	}

	return (
		rows as Array<{
			id: number;
			user_email: string;
			action: string;
			resource_type: string;
			resource_id: string | null;
			summary: string;
			details: string | null;
			created_at: string;
		}>
	).map((row) => ({
		id: row.id,
		userEmail: row.user_email,
		action: row.action,
		resourceType: row.resource_type,
		resourceId: row.resource_id,
		summary: row.summary,
		details: parseDetailsJson(row.details),
		createdAt: row.created_at,
	}));
}

