					sourceHtmlPath: "runtime://content/about",
					updatedAt: "2025-01-01T00:00:00Z",
				},
			],
			archives: [],
			translationStatus: [
				{
					route: "/es/about",
					translationState: "not_started",
					englishSourceUrl: "/about",
					locale: "es",
				},
				{
					route: "/es/orphan",
					translationState: "not_started",
					englishSourceUrl: "/no-match",
					locale: "es",
				},
			],
		});
