		const row = result.data.rows[0] as {
			route: string;
			effectiveState: string;
			localizedEditHref?: string;
		};
		expect(row.route).toBe("/es/about");
		expect(row.effectiveState).toBe("not_started");
		expect(row.localizedEditHref).toBeUndefined();
	});
});

