				"<wp:postmeta><wp:meta_key>_wp_old_slug</wp:meta_key><wp:meta_value>old-slug</wp:meta_value></wp:postmeta></item>",
		]);
		const bundle = parseWordPressExport(xml);
		expect(bundle.redirects).toHaveLength(1);
