	test("addRolePolicy / listRolePolicies persists condition JSON", () => {
		const repo = createAccessRepository(store);
		const role = repo.createRole({ name: "OwnerEditor" });
		repo.addRolePolicy({
			roleId: role.id,
			effect: "allow",
			action: "posts:edit",
