import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { runMailchimpImport } from "../src/admin-action-mailchimp-import";

const ENV_KEYS = [
	"NEWSLETTER_DELIVERY_MODE",
	"LISTMONK_API_URL",
	"LISTMONK_API_USERNAME",
	"LISTMONK_API_PASSWORD",
	"LISTMONK_LIST_ID",
] as const;

function setEnv(values: Partial<Record<(typeof ENV_KEYS)[number], string>>) {
	for (const k of ENV_KEYS) {
		if (values[k] === undefined) delete process.env[k];
		else process.env[k] = values[k];
	}
}

const FULL_LISTMONK_ENV: Partial<Record<(typeof ENV_KEYS)[number], string>> = {
	NEWSLETTER_DELIVERY_MODE: "listmonk",
	LISTMONK_API_URL: "https://listmonk.example/api",
	LISTMONK_API_USERNAME: "u",
	LISTMONK_API_PASSWORD: "p",
	LISTMONK_LIST_ID: "7",
};

const okFetch = vi.fn(async () => new Response("ok", { status: 200 }) as never);

beforeEach(() => {
	setEnv(FULL_LISTMONK_ENV);
	(globalThis as { fetch?: unknown }).fetch = okFetch;
	okFetch.mockClear();
});
afterEach(() => {
	setEnv({});
	vi.restoreAllMocks();
});

describe("runMailchimpImport — config validation", () => {
	it("returns ok:false with config error when mode is not listmonk", async () => {
		setEnv({ ...FULL_LISTMONK_ENV, NEWSLETTER_DELIVERY_MODE: "mock" });
		const r = await runMailchimpImport("Email Address\nx@y.com\n", null);
		expect(r.ok).toBe(false);
		expect(r.imported).toBe(0);
		expect(r.error).toContain("Listmonk is not configured");
	});

	it("returns ok:false when listmonkApiUrl is missing", async () => {
		setEnv({ ...FULL_LISTMONK_ENV, LISTMONK_API_URL: undefined });
		const r = await runMailchimpImport("Email Address\nx@y.com\n", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("Listmonk is not configured");
	});

	it("returns ok:false when listmonkApiUsername is missing", async () => {
		setEnv({ ...FULL_LISTMONK_ENV, LISTMONK_API_USERNAME: undefined });
		const r = await runMailchimpImport("Email Address\nx@y.com\n", null);
		expect(r.ok).toBe(false);
	});

	it("returns ok:false when listmonkApiPassword is missing", async () => {
		setEnv({ ...FULL_LISTMONK_ENV, LISTMONK_API_PASSWORD: undefined });
		const r = await runMailchimpImport("Email Address\nx@y.com\n", null);
		expect(r.ok).toBe(false);
	});

	it("returns ok:false when listmonkListId is missing", async () => {
		setEnv({ ...FULL_LISTMONK_ENV, LISTMONK_API_LIST_ID: undefined });
		setEnv({ ...FULL_LISTMONK_ENV, LISTMONK_LIST_ID: undefined });
		const r = await runMailchimpImport("Email Address\nx@y.com\n", null);
		expect(r.ok).toBe(false);
	});
});

describe("runMailchimpImport — CSV parsing", () => {
	it("returns ok:false when CSV has fewer than 2 lines", async () => {
		const r = await runMailchimpImport("Email Address", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("No valid subscriber rows");
		expect(okFetch).not.toHaveBeenCalled();
	});

	it("returns ok:false when CSV has no Email Address column", async () => {
		const r = await runMailchimpImport("Name,City\nA,B\n", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("No valid subscriber rows");
	});

	it("skips rows without an @ in the email", async () => {
		const r = await runMailchimpImport("Email Address\nnot-an-email\nfoo@bar.com\n", null);
		expect(r.ok).toBe(true);
		expect(r.imported).toBe(1);
	});

	it("skips empty email rows", async () => {
		const r = await runMailchimpImport("Email Address\n\nfoo@bar.com\n", null);
		expect(r.ok).toBe(true);
		expect(r.imported).toBe(1);
	});

	it("strips quotes around header and field values", async () => {
		const r = await runMailchimpImport(
			'"Email Address","First Name","Last Name"\n"a@b.com","Ada","Lovelace"\n',
			null,
		);
		expect(r.ok).toBe(true);
		expect(r.imported).toBe(1);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("a@b.com,Ada Lovelace");
	});

	it("falls back to email when First/Last columns are missing entirely", async () => {
		const r = await runMailchimpImport("Email Address\na@b.com\n", null);
		expect(r.ok).toBe(true);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("a@b.com,a@b.com");
	});

	it("falls back to email when First/Last cells are empty", async () => {
		const r = await runMailchimpImport("Email Address,First Name,Last Name\na@b.com,,\n", null);
		expect(r.ok).toBe(true);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("a@b.com,a@b.com");
	});

	it("joins First+Last with a space when both present", async () => {
		const r = await runMailchimpImport(
			"Email Address,First Name,Last Name\na@b.com,Ada,Lovelace\n",
			null,
		);
		expect(r.ok).toBe(true);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("Ada Lovelace");
	});

	it("matches header columns case-insensitively", async () => {
		const r = await runMailchimpImport(
			"EMAIL ADDRESS,first name,LAST name\na@b.com,Ada,Lovelace\n",
			null,
		);
		expect(r.ok).toBe(true);
		expect(r.imported).toBe(1);
	});
});

describe("runMailchimpImport — Listmonk dispatch", () => {
	it("POSTs to /api/subscribers/import with Basic auth and JSON body", async () => {
		await runMailchimpImport("Email Address\na@b.com\n", null);
		expect(okFetch).toHaveBeenCalledTimes(1);
		const [url, init] = okFetch.mock.calls[0] ?? [];
		expect(String(url)).toBe("https://listmonk.example/api/api/subscribers/import");
		const initRec = init as {
			method?: string;
			headers?: Record<string, string>;
			body?: string;
		};
		expect(initRec.method).toBe("POST");
		expect(initRec.headers?.["Content-Type"]).toBe("application/json");
		expect(initRec.headers?.Authorization).toBe(`Basic ${btoa("u:p")}`);
		const body = JSON.parse(String(initRec.body));
		expect(body.mode).toBe("subscribe");
		expect(body.subscription_status).toBe("confirmed");
		expect(body.delims).toBe(",");
		expect(body.lists).toEqual([7]);
		expect(String(body.records)).toContain("email,name");
		expect(String(body.records)).toContain("a@b.com,a@b.com");
	});

	it("returns ok:true with imported count when Listmonk responds 200", async () => {
		const r = await runMailchimpImport("Email Address\na@b.com\nc@d.com\n", null);
		expect(r).toEqual({ ok: true, imported: 2, skipped: 0 });
	});

	it("returns ok:false with status-bearing error when Listmonk responds non-2xx", async () => {
		(globalThis as { fetch?: unknown }).fetch = vi.fn(
			async () => new Response("nope", { status: 401 }) as never,
		);
		const r = await runMailchimpImport("Email Address\na@b.com\n", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("401");
		expect(r.error).toContain("credentials");
	});

	it("returns ok:false with network-error message when fetch throws", async () => {
		(globalThis as { fetch?: unknown }).fetch = vi.fn(async () => {
			throw new Error("ECONNREFUSED");
		});
		const r = await runMailchimpImport("Email Address\na@b.com\n", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("Network error");
	});
});

describe("runMailchimpImport — survivor pins", () => {
	it("absent First/Last cells (cells undefined, not empty) still fall back to email-as-name (pins L36/L37 ?? '' fallbacks)", async () => {
		// CSV declares 3 header columns but each data row supplies only 1 cell.
		// cols[firstIdx] / cols[lastIdx] are `undefined` (not "") — the `?? ""`
		// fallback fires and the filter(Boolean).join chain yields `email`.
		const r = await runMailchimpImport(
			"Email Address,First Name,Last Name\na@b.com\nb@c.com\n",
			null,
		);
		expect(r.ok).toBe(true);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("a@b.com,a@b.com");
		expect(String(body.records)).toContain("b@c.com,b@c.com");
	});

	it("logs 'Mailchimp import completed' with the imported count (pins L109 logger.info)", async () => {
		const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
		await runMailchimpImport("Email Address\na@b.com\nc@d.com\n", null);
		const matched = logSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Mailchimp import completed"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.count).toBe(2);
		logSpy.mockRestore();
	});

	it("logs 'Listmonk bulk import error' when Listmonk returns non-ok (pins L100 logger.error)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		(globalThis as { fetch?: unknown }).fetch = vi.fn(
			async () => new Response("server error body", { status: 500 }) as never,
		);
		await runMailchimpImport("Email Address\na@b.com\n", null);
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Listmonk bulk import error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.status).toBe(500);
		expect(meta?.body).toBe("server error body");
		errorSpy.mockRestore();
	});

	it("logs 'Mailchimp import network error' when fetch throws (pins L112 logger.error)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		(globalThis as { fetch?: unknown }).fetch = vi.fn(async () => {
			throw new Error("ECONNREFUSED");
		});
		await runMailchimpImport("Email Address\na@b.com\n", null);
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Mailchimp import network error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(String(meta?.err)).toContain("ECONNREFUSED");
		errorSpy.mockRestore();
	});

	it("trims leading whitespace before splitting into lines (pins L21 csv.trim() MethodExpression)", async () => {
		// Leading newlines: csv.trim() removes them so headers = "Email Address".
		// Without the trim, headers would be "" → emailIdx === -1 → no rows.
		const r = await runMailchimpImport("\n\nEmail Address\nfoo@bar.com\n", null);
		expect(r.ok).toBe(true);
		expect(r.imported).toBe(1);
	});

	it("finds Email Address when it is not the first column (pins L25 findIndex callback + L29 emailIdx===-1 UnaryOperator)", async () => {
		// emailIdx is 1, not 0. Mutating the findIndex callback to always-true
		// makes emailIdx fall to 0 (treating "Name" column as email → skipped
		// for missing @). Mutating `=== -1` to `=== +1` makes the guard fire
		// for emailIdx===1 and return []. Either mutation drops imports to 0.
		const r = await runMailchimpImport("Name,Email Address\nAda,a@b.com\n", null);
		expect(r.ok).toBe(true);
		expect(r.imported).toBe(1);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("a@b.com");
	});

	it("does not strip an internal quote inside a header value (pins L24 regex ^/$ anchors)", async () => {
		// Header literal `Em"ail Address` has no leading/trailing quote. The
		// anchored regex /^"|"$/g leaves the internal quote in place, so
		// lowercase comparison against "email address" fails and emailIdx === -1.
		// Mutating away `^` or `$` (non-anchored `"`) would strip the internal
		// quote, the comparison would match, and the row would be imported.
		const r = await runMailchimpImport('Em"ail Address\na@b.com\n', null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("No valid subscriber rows");
		expect(okFetch).not.toHaveBeenCalled();
	});

	it("preserves an internal quote inside a field value (pins L33 regex ^/$ anchors)", async () => {
		// `Ad"a` has no leading or trailing quote — replace(/^"|"$/g, "") leaves it
		// intact. Mutating away `^` or `$` would turn the regex into a non-anchored
		// `"` match and strip the internal quote, yielding `Ada` instead.
		const r = await runMailchimpImport('Email Address,First Name\na@b.com,Ad"a\n', null);
		expect(r.ok).toBe(true);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain('a@b.com,Ad"a');
	});

	it("returns the Last-Name cell when lastIdx === 1 (pins L37 `lastIdx !== -1` UnaryOperator -1→+1)", async () => {
		// With Last Name as the second column, lastIdx === 1. Original `!== -1`
		// stays true so the cell is read; mutant `!== +1` would be false and fall
		// back to "", yielding email-as-name instead of "Smith".
		const r = await runMailchimpImport("Email Address,Last Name\nfoo@bar.com,Smith\n", null);
		expect(r.ok).toBe(true);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		expect(String(body.records)).toContain("foo@bar.com,Smith");
	});

	it('joins the Listmonk records body with newlines (pins L80 StringLiteral `\\n`→`""`)', async () => {
		await runMailchimpImport("Email Address\na@b.com\nc@d.com\n", null);
		const body = JSON.parse(String(okFetch.mock.calls[0]?.[1]?.body ?? "{}"));
		const records = String(body.records);
		// header + 2 rows joined by "\n" → exactly 2 newlines. Mutant "" join
		// concatenates everything into a single line.
		expect(records.split("\n")).toHaveLength(3);
		expect(records).toMatch(/^email,name\na@b\.com,a@b\.com\nc@d\.com,c@d\.com$/);
	});

	it("CSV with no header row (empty first line) returns no records (pins L22 ConditionalExpression false)", async () => {
		// lines.length < 2: empty input -> [] -> returns ok:false
		const r = await runMailchimpImport("", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("No valid subscriber rows found");
	});

	it("header row gets parsed when emailIdx is found (pins L29 emailIdx === -1 conditional)", async () => {
		// emailIdx is a valid index (0) → bypass the early-return. With invalid
		// rows that lack @, records ends up empty and we get the no-rows error.
		const r = await runMailchimpImport("Email Address\nnotanemail\n", null);
		expect(r.ok).toBe(false);
		expect(r.error).toContain("No valid subscriber rows found");
	});
});

tests/local-media-storage.test.ts.source:
import { existsSync, mkdirSync, readdirSync, rmSync, statSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// ---------------------------------------------------------------------------
// vi.mock is hoisted above all let/const initializers, so any variable used
// inside the factory must be defined via vi.hoisted(). The module also captures
// getLocalUploadsDir() once at init time, so we use a fixed path and clean the
// directory between tests rather than creating a new path per run.
// ---------------------------------------------------------------------------

const { testUploadsDir } = vi.hoisted(() => {
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { mkdtempSync } = require("node:fs") as typeof import("node:fs");
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { join } = require("node:path") as typeof import("node:path");
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { tmpdir } = require("node:os") as typeof import("node:os");
	return { testUploadsDir: mkdtempSync(join(tmpdir(), "astropress-media-")) };
});

vi.mock("../src/local-image-storage", () => ({
	ensureLocalUploadsDir: vi.fn(),
	getLocalUploadsDir: vi.fn(() => testUploadsDir),
	guessImageMimeType: vi.fn((path: string) => {
		if (path.endsWith(".png")) return "image/png";
		if (path.endsWith(".jpg") || path.endsWith(".jpeg")) return "image/jpeg";
		if (path.endsWith(".webp")) return "image/webp";
		if (path.endsWith(".gif")) return "image/gif";
		if (path.endsWith(".avif")) return "image/avif";
		if (path.endsWith(".svg")) return "image/svg+xml";
		return "application/octet-stream";
	}),
}));

import {
	buildLocalMediaDescriptor,
	createLocalMediaUpload,
	deleteLocalMediaUpload,
	guessMediaMimeType,
} from "../src/local-media-storage";

const validPng = new Uint8Array(1024); // 1 KB image bytes (fake PNG)
const oversizedFile = new Uint8Array(11 * 1024 * 1024); // 11 MB — exceeds limit

beforeEach(() => {
	rmSync(testUploadsDir, { recursive: true, force: true });
	mkdirSync(testUploadsDir, { recursive: true });
});

afterEach(() => {
	rmSync(testUploadsDir, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// guessMediaMimeType
// ---------------------------------------------------------------------------

describe("guessMediaMimeType", () => {
	it("delegates to guessImageMimeType from local-image-storage", () => {
		expect(guessMediaMimeType("photo.png")).toBe("image/png");
		expect(guessMediaMimeType("photo.jpg")).toBe("image/jpeg");
		expect(guessMediaMimeType("photo.webp")).toBe("image/webp");
	});
});

// ---------------------------------------------------------------------------
// buildLocalMediaDescriptor
// ---------------------------------------------------------------------------

describe("buildLocalMediaDescriptor", () => {
	it("returns a valid descriptor for a PNG upload", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.mimeType).toBe("image/png");
		expect(result.asset.fileSize).toBe(1024);
		expect(result.asset.publicPath).toMatch(/^\/images\/uploads\//);
		expect(result.asset.r2Key).toMatch(/^uploads\//);
		expect(result.asset.storedFilename).toMatch(/^media-[0-9a-f-]{36}$/);
	});

	it("uses provided title and altText", () => {
		const result = buildLocalMediaDescriptor({
			filename: "banner.png",
			bytes: validPng,
			title: "My Banner",
			altText: "A colourful banner",
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("My Banner");
		expect(result.asset.altText).toBe("A colourful banner");
	});

	it("falls back to sanitised basename as title", () => {
		const result = buildLocalMediaDescriptor({
			filename: "my awesome photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("my-awesome-photo");
	});

	it("rejects empty filename", () => {
		const result = buildLocalMediaDescriptor({ filename: "", bytes: validPng });
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("Select a file");
	});

	it("rejects zero-byte file", () => {
		const result = buildLocalMediaDescriptor({
			filename: "empty.png",
			bytes: new Uint8Array(0),
		});
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects file exceeding 10 MB", () => {
		const result = buildLocalMediaDescriptor({
			filename: "huge.png",
			bytes: oversizedFile,
		});
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("10 MB");
	});

	it("rejects disallowed extension (.php)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "malicious.php",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("not allowed");
	});

	it("rejects disallowed extension (.exe)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "evil.exe",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
	});

	it("accepts all allowed extensions", () => {
		const allowed = [
			"photo.jpg",
			"photo.jpeg",
			"photo.png",
			"photo.webp",
			"photo.gif",
			"photo.avif",
			"photo.svg",
		];
		for (const filename of allowed) {
			const result = buildLocalMediaDescriptor({ filename, bytes: validPng });
			expect(result.ok, `Expected ok for ${filename}`).toBe(true);
		}
	});

	it("rejects file exactly equal to maxUploadBytes is also accepted (kills L56 EqualityOperator >= mutant on the size guard)", () => {
		// boundary: byteLength === maxUploadBytes is allowed (the guard uses >).
		// Mutated `>= maxUploadBytes`: rejects exactly-at-limit uploads.
		const exactlyMax = new Uint8Array(10 * 1024 * 1024);
		const result = buildLocalMediaDescriptor({
			filename: "limit.png",
			bytes: exactlyMax,
		});
		expect(result.ok).toBe(true);
	});

	it("treats a no-extension filename as disallowed via the '.bin' fallback (kills L60 StringLiteral '.bin' → '')", () => {
		// path.extname("noext") === "" → || ".bin" → ".bin" (not in allowedExtensions).
		// Mutant: || "" → still "" → not in allowedExtensions, still rejected. Both yield the
		// same rejection, but the ERROR phrasing path is identical too. To observe the
		// difference, use a filename whose lowercased extname is "" but whose basename ends in
		// something that would change the .extname trip-point. The simplest observable check:
		// after the mutant, allowedExtensions.has("") would let "" through; ensure it stays
		// rejected.
		const result = buildLocalMediaDescriptor({ filename: "noextension", bytes: validPng });
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("not allowed");
	});

	it("collapses runs of non-alphanumerics into single dashes (kills L81 Regex '+' quantifier)", () => {
		// Original /[^a-z0-9]+/gi: runs collapse to a single "-".
		// Mutant /[^a-z0-9]/gi: each non-alphanumeric becomes "-".
		const result = buildLocalMediaDescriptor({
			filename: "my   awesome---photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Three spaces and three dashes collapse together → exactly one "-" each gap.
		expect(result.asset.title).toBe("my-awesome-photo");
	});

	it("strips leading/trailing dashes from the sanitised basename (kills L82 StringLiteral 'Stryker was here!')", () => {
		// "-foo-.png" → replace strips runs to "-foo-" → strip leading/trailing → "foo".
		// Mutant replaces "" with "Stryker was here!" → "Stryker was here!fooStryker was here!".
		const result = buildLocalMediaDescriptor({
			filename: "-foo-.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("foo");
	});

	it("defaults the basename to 'upload' when sanitisation leaves nothing (kills L83 StringLiteral '' fallback)", () => {
		// "---.png" → "-" after run-collapse → "" after edge-trim → falls back via || "upload".
		// Mutant: fallback is "" → title becomes "" (or input.title trimmed).
		const result = buildLocalMediaDescriptor({
			filename: "---.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("upload");
	});

	it("trims whitespace from title and altText (kills L99/L100 MethodExpression dropping .trim)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
			title: "  spaced title  ",
			altText: "  alt with edges  ",
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Mutant L99: drops .trim() → title retains leading/trailing spaces.
		// Mutant L100: same for altText.
		expect(result.asset.title).toBe("spaced title");
		expect(result.asset.altText).toBe("alt with edges");
	});

	it("defaults altText to '' when not provided (kills L100 StringLiteral '' → 'Stryker was here!')", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Mutated fallback ?? "Stryker was here!" would produce a non-empty altText.
		expect(result.asset.altText).toBe("");
	});

	it("generates a unique id on each call", () => {
		const r1 = buildLocalMediaDescriptor({
			filename: "a.png",
			bytes: validPng,
		});
		const r2 = buildLocalMediaDescriptor({
			filename: "b.png",
			bytes: validPng,
		});
		expect(r1.ok && r2.ok).toBe(true);
		if (!r1.ok || !r2.ok) return;
		expect(r1.asset.id).not.toBe(r2.asset.id);
	});
});

// ---------------------------------------------------------------------------
// createLocalMediaUpload
// ---------------------------------------------------------------------------

describe("createLocalMediaUpload", () => {
	it("writes the file to disk and returns descriptor", () => {
		const result = createLocalMediaUpload({
			filename: "test.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(existsSync(result.asset.diskPath)).toBe(true);
	});

	it("writes file with owner-only permissions (mode 0o600)", () => {
		const result = createLocalMediaUpload({
			filename: "perm.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		const stat = statSync(result.asset.diskPath);
		// Mode includes file type bits; mask to permission bits only
		expect(stat.mode & 0o777).toBe(0o600);
	});

	it("propagates validation errors without writing to disk (kills L104 ConditionalExpression:false & BlockStatement)", () => {
		// Mutant L104 ConditionalExpression:false / BlockStatement {}: the early
		// `return descriptor` is skipped, so writeFileSync runs even for a rejected
		// upload — leaving a stray file in the uploads dir.
		const before = readdirSync(testUploadsDir);
		const result = createLocalMediaUpload({
			filename: "bad.exe",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
		expect(readdirSync(testUploadsDir)).toEqual(before);
	});
});

// ---------------------------------------------------------------------------
// deleteLocalMediaUpload
// ---------------------------------------------------------------------------

describe("deleteLocalMediaUpload", () => {
	it("deletes a file written to the uploads dir", () => {
		const result = createLocalMediaUpload({
			filename: "del.png",
			bytes: validPng,
		});
		if (!result.ok) return;
		expect(existsSync(result.asset.diskPath)).toBe(true);
		deleteLocalMediaUpload(result.asset.publicPath);
		expect(existsSync(result.asset.diskPath)).toBe(false);
	});

	it("only deletes paths under /images/uploads/ (kills L126 ConditionalExpression:false, StringLiteral '' on the prefix check, and L126 BlockStatement {} on the body)", () => {
		// Write a file outside the uploads dir into the testUploadsDir tree but reference it
		// via a non-/images/uploads path. The guard must return without unlinking.
		const result = createLocalMediaUpload({
			filename: "stay.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		// Try to delete via a path that doesn't start with the prefix.
		deleteLocalMediaUpload("/other/area/stay.png");
		expect(existsSync(result.asset.diskPath)).toBe(true);
		// Now delete via the legitimate path — file should be removed.
		deleteLocalMediaUpload(result.asset.publicPath);
		expect(existsSync(result.asset.diskPath)).toBe(false);
	});

	it("is a no-op for paths outside the uploads dir", () => {
		// Should not throw
		expect(() => deleteLocalMediaUpload("/etc/passwd")).not.toThrow();
		expect(() => deleteLocalMediaUpload("relative/path/file.png")).not.toThrow();
	});

	it("is a no-op for non-existent files (no throw)", () => {
		expect(() => deleteLocalMediaUpload("/images/uploads/does-not-exist-12345.png")).not.toThrow();
	});

	it("does not unlink a file when the path's basename collides but the prefix is wrong (kills L115 ConditionalExpression:false, StringLiteral '', BlockStatement)", () => {
		// The guard rejects any path not under /images/uploads/. Mutants that disable
		// the early return (ConditionalExpression:false, BlockStatement {}) or that
		// make startsWith("") always-true would fall through to unlinkSync on the
		// real stored file, since basename here equals the actual stored filename.
		const result = createLocalMediaUpload({
			filename: "keep.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		deleteLocalMediaUpload(`/elsewhere/${result.asset.storedFilename}`);
		expect(existsSync(result.asset.diskPath)).toBe(true);
	});
});

