import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { downloadMedia, validateMediaSourceUrl } from "../src/import/download-media.js";
import * as sharpTranscode from "../src/import/sharp-transcode.js";

// ---------------------------------------------------------------------------
// Use vi.spyOn() rather than vi.mock() so the patch works regardless of test
// file ordering under isolate:false. vi.mock() cannot replace a module that
// was already loaded by a prior test file in the shared registry; vi.spyOn()
// patches the live export on the already-loaded module object, which works
// no matter when the module was first imported.
// ---------------------------------------------------------------------------

let transcodeViaSharpSpy: ReturnType<typeof vi.spyOn<typeof sharpTranscode, "transcodeViaSharp">>;

beforeEach(() => {
	transcodeViaSharpSpy = vi
		.spyOn(sharpTranscode, "transcodeViaSharp")
		.mockResolvedValue(Buffer.from([0xaa, 0xbb]));
});

afterEach(() => {
	transcodeViaSharpSpy.mockRestore();
});

describe("validateMediaSourceUrl", () => {
	it("accepts http URLs", () => {
		expect(() => validateMediaSourceUrl("http://example.com/image.jpg")).not.toThrow();
	});

	it("accepts https URLs", () => {
		expect(() => validateMediaSourceUrl("https://example.com/image.png")).not.toThrow();
	});

	it("blocks data: URLs", () => {
		expect(() => validateMediaSourceUrl("data:image/png;base64,abc")).toThrow(
			"Blocked non-HTTP URL scheme: data:",
		);
	});

	it("blocks file: URLs", () => {
		expect(() => validateMediaSourceUrl("file:///etc/passwd")).toThrow(
			"Blocked non-HTTP URL scheme: file:",
		);
	});

	it("blocks javascript: URLs", () => {
		expect(() => validateMediaSourceUrl("javascript:alert(1)")).toThrow(
			"Blocked non-HTTP URL scheme: javascript:",
		);
	});

	it("blocks localhost", () => {
		expect(() => validateMediaSourceUrl("http://localhost/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 127.0.0.1", () => {
		expect(() => validateMediaSourceUrl("http://127.0.0.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 10.x private range", () => {
		expect(() => validateMediaSourceUrl("http://10.0.0.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 192.168.x private range", () => {
		expect(() => validateMediaSourceUrl("http://192.168.1.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 172.16-31.x private range", () => {
		expect(() => validateMediaSourceUrl("http://172.16.0.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 169.254.x link-local range", () => {
		expect(() => validateMediaSourceUrl("http://169.254.169.254/latest/meta-data")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("rejects invalid URLs", () => {
		expect(() => validateMediaSourceUrl("not a url")).toThrow("Invalid URL");
	});

	it("returns parsed URL for valid input", () => {
		const url = validateMediaSourceUrl("https://cdn.example.com/img.jpg");
		expect(url.hostname).toBe("cdn.example.com");
	});
});

describe("downloadMedia", () => {
	it("rejects non-media content-type", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response("<html></html>", {
						status: 200,
						headers: { "content-type": "text/html" },
					}),
			),
		);
		await expect(downloadMedia("https://example.com/page")).rejects.toThrow(
			'Blocked: unexpected media content-type "text/html"',
		);
		vi.unstubAllGlobals();
	});

	it("rejects responses exceeding size limit via content-length", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(10), {
						status: 200,
						headers: {
							"content-type": "image/jpeg",
							"content-length": String(60 * 1024 * 1024),
						},
					}),
			),
		);
		await expect(downloadMedia("https://example.com/huge.jpg")).rejects.toThrow("exceeds");
		vi.unstubAllGlobals();
	});

	it("rejects non-OK HTTP responses", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(async () => new Response(null, { status: 404 })),
		);
		await expect(downloadMedia("https://example.com/missing.jpg")).rejects.toThrow("HTTP 404");
		vi.unstubAllGlobals();
	});

	it("transcodes image/jpeg through sharp and returns its output", async () => {
		const rawJpeg = new Uint8Array([0xff, 0xd8, 0xff, 0xe0]);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(rawJpeg, {
						status: 200,
						headers: { "content-type": "image/jpeg" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/photo.jpg");
		expect(transcodeViaSharpSpy).toHaveBeenCalledOnce();
		expect(bytes).toBeInstanceOf(Uint8Array);
		// Returns sharp's re-encoded output, not the raw HTTP bytes
		expect(Array.from(bytes)).toEqual([0xaa, 0xbb]);
		vi.unstubAllGlobals();
	});

	it("transcodes image/png through sharp", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array([0x89, 0x50, 0x4e, 0x47]), {
						status: 200,
						headers: { "content-type": "image/png" },
					}),
			),
		);
		await downloadMedia("https://example.com/photo.png");
		expect(transcodeViaSharpSpy).toHaveBeenCalledOnce();
		vi.unstubAllGlobals();
	});

	it("sanitizes image/svg+xml without calling sharp", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response('<svg xmlns="http://www.w3.org/2000/svg"><circle r="5"/></svg>', {
						status: 200,
						headers: { "content-type": "image/svg+xml" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/icon.svg");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		const text = new TextDecoder().decode(bytes);
		expect(text).toContain("circle");
		vi.unstubAllGlobals();
	});

	it("strips script tags from SVG", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script><circle r="5"/></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/malicious.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("<script");
		expect(text).not.toContain("alert(1)");
		expect(text).toContain("circle");
		vi.unstubAllGlobals();
	});

	it("strips on* event handlers from SVG", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><circle r="5" onload="alert(1)"/></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/handler.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("onload");
		expect(text).not.toContain("alert(1)");
		vi.unstubAllGlobals();
	});

	it("preserves an http:// href on an SVG <a> (exercises allowedSchemes ['http','https'])", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><a href="http://example.com/page"><circle r="5"/></a></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/with-link.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).toContain("http://example.com/page");
		vi.unstubAllGlobals();
	});

	it("strips javascript: href values from SVG <a>", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><a href="javascript:alert(1)"><circle r="5"/></a></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/bad-href.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("javascript:");
		vi.unstubAllGlobals();
	});

	it("preserves the fill attribute on an SVG circle (exercises allowedAttributes['*'] passthrough)", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response('<svg xmlns="http://www.w3.org/2000/svg"><circle r="5" fill="red"/></svg>', {
						status: 200,
						headers: { "content-type": "image/svg+xml" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/colored.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).toContain('fill="red"');
		vi.unstubAllGlobals();
	});

	it("strips foreignObject from SVG", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><foreignObject><div>hi</div></foreignObject></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/foreign.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("foreignObject");
		expect(text).not.toContain("<div>");
		vi.unstubAllGlobals();
	});

	it("passes video/mp4 through without transcoding", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(8), {
						status: 200,
						headers: { "content-type": "video/mp4" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/clip.mp4");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		expect(bytes.length).toBe(8);
		vi.unstubAllGlobals();
	});

	it("passes application/pdf through without transcoding", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(16), {
						status: 200,
						headers: { "content-type": "application/pdf" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/doc.pdf");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		expect(bytes.length).toBe(16);
		vi.unstubAllGlobals();
	});

	it("propagates sharp decode errors for corrupt image data", async () => {
		transcodeViaSharpSpy.mockRejectedValueOnce(
			new Error("Input buffer contains unsupported image format"),
		);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array([0x00, 0x00]), {
						status: 200,
						headers: { "content-type": "image/jpeg" },
					}),
			),
		);
		await expect(downloadMedia("https://example.com/corrupt.jpg")).rejects.toThrow(
			"Input buffer contains unsupported image format",
		);
		vi.unstubAllGlobals();
	});

	it("rejects private IP before making any network call", async () => {
		const fetchSpy = vi.fn();
		vi.stubGlobal("fetch", fetchSpy);
		await expect(downloadMedia("http://192.168.0.1/secret")).rejects.toThrow(
			"Blocked request to private/loopback host",
		);
		expect(fetchSpy).not.toHaveBeenCalled();
		vi.unstubAllGlobals();
	});

	it("parses the content-type by splitting on ';' (charset suffix and surrounding whitespace are ignored)", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array([0xff, 0xd8]), {
						status: 200,
						headers: { "content-type": "  IMAGE/JPEG ; charset=binary" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/p.jpg");
		expect(transcodeViaSharpSpy).toHaveBeenCalledOnce();
		expect(bytes).toBeInstanceOf(Uint8Array);
		vi.unstubAllGlobals();
	});

	it("accepts an image/* content-type that is NOT in the explicit allowlist (image/x-icon)", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(4), {
						status: 200,
						headers: { "content-type": "image/x-icon" },
					}),
			),
		);
		// image/x-icon is not in ALLOWED_CONTENT_TYPES but matches the startsWith("image/") branch.
		// It is not TRANSCODABLE → returns the raw bytes through.
		const bytes = await downloadMedia("https://example.com/favicon.ico");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		expect(bytes.length).toBe(4);
		vi.unstubAllGlobals();
	});

	it("accepts content-length equal to the limit (boundary: > not >=)", async () => {
		const exact = new Uint8Array(8);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(exact, {
						status: 200,
						headers: {
							"content-type": "image/jpeg",
							"content-length": String(50 * 1024 * 1024),
						},
					}),
			),
		);
		// content-length == MAX should NOT throw; only > MAX throws.
		await downloadMedia("https://example.com/borderline.jpg");
		expect(transcodeViaSharpSpy).toHaveBeenCalledOnce();
		vi.unstubAllGlobals();
	});

	it("rejects when arrayBuffer payload exceeds the limit (overrides a small content-length header)", async () => {
		// content-length under-reports the actual payload; the post-arrayBuffer check should still catch it.
		const oversized = new Uint8Array(50 * 1024 * 1024 + 1);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(oversized, {
						status: 200,
						headers: {
							"content-type": "image/jpeg",
							"content-length": "10",
						},
					}),
			),
		);
		await expect(downloadMedia("https://example.com/lying.jpg")).rejects.toThrow(
			/download size .* exceeds/,
		);
		vi.unstubAllGlobals();
	});
});

tests/hosted-api-adapter.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { createAstropressHostedApiAdapter } from "../src/hosted-api-adapter.js";

describe("hosted api adapter", () => {
	it("uses a remote JSON API surface for hosted providers", async () => {
		const requests: Array<{
			url: string;
			method: string;
			body?: string | null;
			auth?: string | null;
		}> = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test/astropress",
			accessToken: "secret-token",
			previewBaseUrl: "https://preview.example.test",
			fetchImpl: async (input, init) => {
				const url = String(input);
				requests.push({
					url,
					method: init?.method ?? "GET",
					body: typeof init?.body === "string" ? init.body : null,
					auth:
						init?.headers && typeof init.headers === "object" && "authorization" in init.headers
							? String((init.headers as Record<string, string>).authorization)
							: null,
				});

				if (url.endsWith("/content?kind=post")) {
					return new Response(
						JSON.stringify([
							{
								id: "1",
								kind: "post",
								slug: "hello",
								status: "published",
								title: "Hello",
							},
						]),
						{ status: 200 },
					);
				}
				if (url.endsWith("/content/1")) {
					return new Response(
						JSON.stringify({
							id: "1",
							kind: "post",
							slug: "hello",
							status: "published",
							title: "Hello",
						}),
						{ status: 200 },
					);
				}
				if (url.endsWith("/content") && init?.method === "POST") {
					return new Response(String(init?.body), { status: 200 });
				}
				if (url.includes("/revisions?recordId=1")) {
					return new Response(
						JSON.stringify([{ id: "r1", recordId: "1", createdAt: "now", snapshot: {} }]),
						{
							status: 200,
						},
					);
				}
				if (url.endsWith("/auth/sign-in")) {
					return new Response(
						JSON.stringify({
							id: "session-1",
							email: "admin@example.com",
							role: "admin",
						}),
						{
							status: 200,
						},
					);
				}
				if (url.endsWith("/auth/session/session-1")) {
					return new Response(
						JSON.stringify({
							id: "session-1",
							email: "admin@example.com",
							role: "admin",
						}),
						{
							status: 200,
						},
					);
				}
				if (url.endsWith("/auth/sign-out")) {
					return new Response(JSON.stringify({ ok: true }), { status: 200 });
				}
				if (url.endsWith("/media") && init?.method === "POST") {
					return new Response(String(init?.body), { status: 200 });
				}
				if (url.endsWith("/media/logo")) {
					return new Response(
						JSON.stringify({
							id: "logo",
							filename: "logo.png",
							mimeType: "image/png",
						}),
						{
							status: 200,
						},
					);
				}
				if (url.endsWith("/revisions") && init?.method === "POST") {
					return new Response(String(init?.body), { status: 200 });
				}
				if (init?.method === "DELETE") {
					return new Response(JSON.stringify({ ok: true }), { status: 200 });
				}
				return new Response(JSON.stringify([]), { status: 200 });
			},
		});

		expect((await adapter.content.list("post")).length).toBe(1);
		expect((await adapter.content.get("1"))?.slug).toBe("hello");
		expect(
			(
				await adapter.content.save({
					id: "1",
					kind: "post",
					slug: "hello",
					status: "published",
					title: "Hello",
				})
			).title,
		).toBe("Hello");
		expect(
			(
				await adapter.media.put({
					id: "logo",
					filename: "logo.png",
					mimeType: "image/png",
				})
			).filename,
		).toBe("logo.png");
		expect((await adapter.revisions.list("1")).length).toBe(1);
		expect((await adapter.auth.signIn("admin@example.com", "password"))?.role).toBe("admin");
		expect((await adapter.auth.getSession("session-1"))?.email).toBe("admin@example.com");
		await adapter.auth.signOut("session-1");
		expect((await adapter.preview?.create({ recordId: "1" }))?.url).toContain("/preview/1");
		expect((await adapter.media.get("logo"))?.filename).toBe("logo.png");
		await adapter.media.delete("logo");
		const revision = {
			id: "r2",
			recordId: "1",
			createdAt: "now",
			snapshot: {},
		};
		await adapter.revisions.append(revision as Parameters<typeof adapter.revisions.append>[0]);
		await adapter.content.delete("1");

		expect(requests.every((request) => request.auth === "Bearer secret-token")).toBe(true);
	});

	it("throws when the API returns a non-OK HTTP response", async () => {
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test/astropress",
			fetchImpl: async () => new Response(JSON.stringify({ error: "Not found" }), { status: 404 }),
		});
		await expect(adapter.content.list()).rejects.toThrow(
			"Astropress hosted API request failed with 404",
		);
	});

	it("constructs URLs by trim-joining baseUrl with the path (no double slashes, no missing slashes)", async () => {
		const seen: string[] = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			// Trailing slash on the base intentionally exercises stripTrailingSlashes
			apiBaseUrl: "https://api.example.test/astropress/",
			fetchImpl: async (input) => {
				seen.push(String(input));
				return new Response(JSON.stringify([]), { status: 200 });
			},
		});
		await adapter.content.list();
		await adapter.content.list("post");
		await adapter.content.get("hello world");
		expect(seen[0]).toBe("https://api.example.test/astropress/content");
		expect(seen[1]).toBe("https://api.example.test/astropress/content?kind=post");
		// URL-encodes the id segment
		expect(seen[2]).toBe("https://api.example.test/astropress/content/hello%20world");
	});

	it("omits the authorization header when no accessToken is configured", async () => {
		const captured: Array<{ url: string; auth: string | null }> = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async (input, init) => {
				const headers = init?.headers as Record<string, string> | undefined;
				captured.push({ url: String(input), auth: headers?.authorization ?? null });
				return new Response(JSON.stringify([]), { status: 200 });
			},
		});
		await adapter.content.list();
		expect(captured[0].auth).toBeNull();
	});

	it("sets content-type: application/json on every outgoing request", async () => {
		const captured: Record<string, string>[] = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async (_url, init) => {
				captured.push(init?.headers as Record<string, string>);
				return new Response(JSON.stringify([]), { status: 200 });
			},
		});
		await adapter.content.list();
		expect(captured[0]["content-type"]).toBe("application/json");
	});

	it("uses POST for content.save / media.put / revisions.append, DELETE for *.delete", async () => {
		const captured: Array<{ url: string; method: string }> = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async (input, init) => {
				captured.push({ url: String(input), method: init?.method ?? "GET" });
				return new Response("{}", { status: 200 });
			},
		});
		await adapter.content.save({
			id: "1",
			kind: "post",
			slug: "h",
			status: "published",
			title: "T",
		});
		await adapter.media.put({ id: "m", filename: "f.png", mimeType: "image/png" });
		await adapter.revisions.append({
			id: "r",
			recordId: "1",
			createdAt: "now",
			snapshot: {},
		} as Parameters<typeof adapter.revisions.append>[0]);
		await adapter.content.delete("1");
		await adapter.media.delete("m");
		await adapter.auth.signOut("s");
		expect(captured[0].method).toBe("POST");
		expect(captured[0].url).toBe("https://api.example.test/content");
		expect(captured[1].method).toBe("POST");
		expect(captured[1].url).toBe("https://api.example.test/media");
		expect(captured[2].method).toBe("POST");
		expect(captured[2].url).toBe("https://api.example.test/revisions");
		expect(captured[3].method).toBe("DELETE");
		expect(captured[3].url).toBe("https://api.example.test/content/1");
		expect(captured[4].method).toBe("DELETE");
		expect(captured[4].url).toBe("https://api.example.test/media/m");
		expect(captured[5].method).toBe("POST");
		expect(captured[5].url).toBe("https://api.example.test/auth/sign-out");
	});

	it("auth.signIn sends {email, password} JSON body and auth.getSession URL-encodes the session id", async () => {
		const captured: Array<{ url: string; body: string | null }> = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async (input, init) => {
				captured.push({
					url: String(input),
					body: typeof init?.body === "string" ? init.body : null,
				});
				return new Response("null", { status: 200 });
			},
		});
		await adapter.auth.signIn("u@x.com", "pw");
		expect(captured[0].url).toBe("https://api.example.test/auth/sign-in");
		expect(JSON.parse(captured[0].body ?? "")).toEqual({ email: "u@x.com", password: "pw" });

		await adapter.auth.getSession("sess id 1");
		expect(captured[1].url).toBe("https://api.example.test/auth/session/sess%20id%201");
	});

	it("preview.create joins the preview base URL (not the api base) and URL-encodes recordId", async () => {
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			previewBaseUrl: "https://preview.example.test/p",
			fetchImpl: async () => new Response("[]", { status: 200 }),
		});
		const preview = await adapter.preview?.create({ recordId: "post id 1", expiresAt: "later" });
		expect(preview?.url).toBe("https://preview.example.test/p/preview/post%20id%201");
		expect(preview?.expiresAt).toBe("later");
	});

	it("omits the preview store entirely when previewBaseUrl is not configured", () => {
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async () => new Response("[]", { status: 200 }),
		});
		expect(adapter.preview).toBeUndefined();
	});

	it("propagates the provider name through capabilities", () => {
		const adapter = createAstropressHostedApiAdapter({
			providerName: "appwrite",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async () => new Response("[]", { status: 200 }),
		});
		expect(adapter.capabilities.name).toBe("appwrite");
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	// Pin every default-true capability boolean literal so the
	// BooleanLiteral → false mutants at L53-58 of hosted-api-adapter.ts get
	// killed (one mutant per `true` in the normalizeProviderCapabilities
	// argument literal).
	it("defaults every hosted-runtime capability to true when no override is provided", () => {
		const adapter = createAstropressHostedApiAdapter({
			providerName: "appwrite",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async () => new Response("[]", { status: 200 }),
		});
		expect(adapter.capabilities.hostedAdmin).toBe(true);
		expect(adapter.capabilities.previewEnvironments).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.gitSync).toBe(true);
	});

	// Pin the joinApiUrl path-segment separator (L29 StringLiteral mutant).
	// A mutated `/` between baseUrl and path would emit a URL like
	// "...example.testStryker was here!content" which would fail every
	// upstream request — but tests stub fetch, so only an assertion on
	// the URL passed to fetch can detect the mutant.
	it("constructs API URLs by joining baseUrl + path with a literal '/' separator", async () => {
		const captured: string[] = [];
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			fetchImpl: async (url) => {
				captured.push(String(url));
				return new Response("[]", { status: 200 });
			},
		});
		await adapter.content.list();
		expect(captured[0]).toBe("https://api.example.test/content");
	});

	it("allows defaultCapabilities overrides to flip a default true to false", () => {
		const adapter = createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: "https://api.example.test",
			defaultCapabilities: { gitSync: false },
			fetchImpl: async () => new Response("[]", { status: 200 }),
		});
		expect(adapter.capabilities.gitSync).toBe(false);
		// Other defaults remain true
		expect(adapter.capabilities.hostedAdmin).toBe(true);
		expect(adapter.capabilities.database).toBe(true);
	});

	it("uses the global fetch when no fetchImpl override is supplied", async () => {
		const realFetch = globalThis.fetch;
		const stub = vi.fn(async () => new Response("[]", { status: 200 }));
		globalThis.fetch = stub as unknown as typeof fetch;
		try {
			const adapter = createAstropressHostedApiAdapter({
				providerName: "supabase",
				apiBaseUrl: "https://api.example.test",
			});
			await adapter.content.list();
			expect(stub).toHaveBeenCalledOnce();
		} finally {
			globalThis.fetch = realFetch;
		}
	});
});

