import { describe, expect, it } from "vitest";
import { bytesToHex } from "../../../src/crypto-primitives";

import {
	DEFAULT_OAUTH_STATE_TTL_MS,
	issueOAuthState,
	parseHexBytes,
	parseStateEnvelope,
	serializeInnerEnvelope,
	verifyOAuthState,
} from "../../../src/integrations/oauth/state";

const ROOT = "root-secret-abc";
const CONTEXT = {
	domain: "deploy-hooks",
	providerId: "github",
	returnTo: "/ap-admin/deploy-hooks",
};
const NOW = 1_700_000_000_000;

function hexEncodeJson(value: unknown): string {
	return bytesToHex(new TextEncoder().encode(JSON.stringify(value)));
}

describe("DEFAULT_OAUTH_STATE_TTL_MS", () => {
	it("is exactly 600000 ms (10 minutes — pins arithmetic mutants)", () => {
		expect(DEFAULT_OAUTH_STATE_TTL_MS).toBe(600_000);
	});
});

describe("parseHexBytes", () => {
	it("parses a valid hex string", () => {
		const out = parseHexBytes("00ff");
		expect(out).not.toBeNull();
		expect(Array.from(out as Uint8Array)).toEqual([0, 255]);
	});

	it("preserves byte order", () => {
		const out = parseHexBytes("0102");
		expect(Array.from(out as Uint8Array)).toEqual([1, 2]);
	});

	it("accepts uppercase hex", () => {
		const out = parseHexBytes("DEADBEEF");
		expect(Array.from(out as Uint8Array)).toEqual([0xde, 0xad, 0xbe, 0xef]);
	});

	it("returns a Uint8Array of length hex.length / 2 (no extra trailing bytes)", () => {
		const out = parseHexBytes("00ff");
		expect((out as Uint8Array).length).toBe(2);
	});

	it("rejects empty", () => {
		expect(parseHexBytes("")).toBeNull();
	});

	it("rejects odd length", () => {
		expect(parseHexBytes("abc")).toBeNull();
	});

	it("rejects non-hex characters", () => {
		expect(parseHexBytes("zz")).toBeNull();
	});

	it("rejects a hex string with a non-hex prefix (kills regex-anchor mutants)", () => {
		expect(parseHexBytes("zz0011")).toBeNull();
	});

	it("rejects a hex string with a non-hex suffix (kills regex-anchor mutants)", () => {
		expect(parseHexBytes("0011zz")).toBeNull();
	});
});

describe("serializeInnerEnvelope", () => {
	it("emits keys in (n, c, e) order so the signature is deterministic", () => {
		const json = serializeInnerEnvelope({ n: "nn", c: CONTEXT, e: 1 });
		expect(json).toBe(`{"n":"nn","c":${JSON.stringify(CONTEXT)},"e":1}`);
	});

	it("uses the input fields verbatim (does not re-order context fields)", () => {
		const json = serializeInnerEnvelope({
			n: "nn",
			c: { domain: "d", providerId: "p", returnTo: "r" },
			e: 99,
		});
		expect(json).toBe('{"n":"nn","c":{"domain":"d","providerId":"p","returnTo":"r"},"e":99}');
	});
});

describe("issueOAuthState", () => {
	it("returns a non-empty hex token", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(issued.token).toMatch(/^[0-9a-f]+$/);
	});

	it("returns expiresAt = nowMs + DEFAULT_OAUTH_STATE_TTL_MS when ttlMs omitted", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(issued.expiresAt).toBe(NOW + 600_000);
	});

	it("honours an explicit ttlMs", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
			ttlMs: 60_000,
		});
		expect(issued.expiresAt).toBe(NOW + 60_000);
	});

	it("returns a 16-byte nonce as 32 hex chars", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(issued.nonce).toMatch(/^[0-9a-f]{32}$/);
	});

	it("produces a fresh nonce on each call", async () => {
		const a = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const b = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(a.nonce).not.toBe(b.nonce);
	});
});

describe("parseStateEnvelope", () => {
	it("returns null on bad hex", () => {
		expect(parseStateEnvelope("zz")).toBeNull();
	});

	it("returns null on valid hex of non-JSON", () => {
		const garbage = bytesToHex(new TextEncoder().encode("not json"));
		expect(parseStateEnvelope(garbage)).toBeNull();
	});

	it("returns the parsed inner + signatureHex on a well-formed envelope", () => {
		const e = hexEncodeJson({ n: "abc", c: CONTEXT, e: 99, s: "deadbeef" });
		const parsed = parseStateEnvelope(e);
		expect(parsed).not.toBeNull();
		expect(parsed?.inner).toEqual({ n: "abc", c: CONTEXT, e: 99 });
		expect(parsed?.signatureHex).toBe("deadbeef");
	});

	it("coerces missing fields and lets the signature mismatch reject downstream", () => {
		// Shape forgers can't fake — recanonicalisation produces a
		// different inner string than what they signed (or didn't).
		const parsed = parseStateEnvelope(hexEncodeJson({}));
		expect(parsed).not.toBeNull();
		expect(parsed?.inner.n).toBe("");
		expect(parsed?.inner.c.domain).toBe("");
		expect(parsed?.inner.c.providerId).toBe("");
		expect(parsed?.inner.c.returnTo).toBe("");
		expect(parsed?.inner.e).toBe(0);
		expect(parsed?.signatureHex).toBe("");
	});

	it("coerces a non-string nonce to '' (kills StringLiteral mutants on the n default)", () => {
		const e = hexEncodeJson({ n: 99, c: CONTEXT, e: 1, s: "ab" });
		const parsed = parseStateEnvelope(e);
		expect(parsed?.inner.n).toBe("99");
	});

	it("coerces a non-number expiry to 0 (kills mutants on the e default)", () => {
		const e = hexEncodeJson({ n: "x", c: CONTEXT, e: "later", s: "ab" });
		const parsed = parseStateEnvelope(e);
		expect(parsed?.inner.e).toBe(0);
	});

	it("strips an entirely missing context to a default empty-string OAuthStateContext", () => {
		const e = hexEncodeJson({ n: "x", e: 1, s: "ab" });
		const parsed = parseStateEnvelope(e);
		expect(parsed?.inner.c).toEqual({
			domain: "",
			providerId: "",
			returnTo: "",
		});
	});

	it("treats a non-hex signature field as empty (downstream INVALID_SIGNATURE)", () => {
		const e = hexEncodeJson({ n: "x", c: CONTEXT, e: 1, s: "zz-not-hex" });
		const parsed = parseStateEnvelope(e);
		expect(parsed?.signatureHex).toBe("");
	});
});

describe("verifyOAuthState", () => {
	it("accepts a freshly issued token and returns the nonce + context", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(result.ok).toBe(true);
		if (result.ok) {
			expect(result.nonce).toBe(issued.nonce);
			expect(result.context).toEqual(CONTEXT);
			expect(result.expiresAt).toBe(issued.expiresAt);
		}
	});

	it("rejects with INVALID_FORMAT on a non-hex token", async () => {
		const result = await verifyOAuthState({
			token: "zz",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(result).toEqual({ ok: false, code: "INVALID_FORMAT" });
	});

	it("rejects with INVALID_SIGNATURE on a missing-fields envelope (defensive parse coerces, HMAC catches)", async () => {
		const e = hexEncodeJson({});
		const result = await verifyOAuthState({
			token: e,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(result).toEqual({ ok: false, code: "INVALID_SIGNATURE" });
	});

	it("rejects with INVALID_SIGNATURE on an envelope with extra unknown fields", async () => {
		// An attacker that adds an extra `evil` field can't produce a
		// matching HMAC because the canonical re-serialisation drops it.
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const decodedBytes = parseHexBytes(issued.token) as Uint8Array;
		const obj = JSON.parse(new TextDecoder().decode(decodedBytes));
		obj.evil = "tamper";
		const reHex = bytesToHex(new TextEncoder().encode(JSON.stringify(obj)));
		const result = await verifyOAuthState({
			token: reHex,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		// The recanonicalisation drops `evil`, so the signature *does*
		// still match. This pins that behaviour — extra fields are
		// silently ignored (no INVALID_SIGNATURE), because the canonical
		// inner is identical. If you ever want to reject extras, that's
		// a contract change.
		expect(result.ok).toBe(true);
	});

	it("rejects with INVALID_SIGNATURE when the rootSecret differs", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: "other-root",
			nowMs: NOW,
		});
		expect(result).toEqual({ ok: false, code: "INVALID_SIGNATURE" });
	});

	it("rejects with INVALID_SIGNATURE when the envelope was tampered with", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		// Decode hex → JSON, mutate returnTo, re-encode without re-signing.
		const decodedBytes = parseHexBytes(issued.token) as Uint8Array;
		const obj = JSON.parse(new TextDecoder().decode(decodedBytes));
		obj.c.returnTo = "/elsewhere";
		const reHex = bytesToHex(new TextEncoder().encode(JSON.stringify(obj)));
		const result = await verifyOAuthState({
			token: reHex,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(result).toEqual({ ok: false, code: "INVALID_SIGNATURE" });
	});

	it("rejects with INVALID_SIGNATURE when the envelope's signature field is non-hex", async () => {
		// Construct a well-shaped envelope whose `s` field is non-hex —
		// the signature parser must reject before recomputing.
		const e = hexEncodeJson({
			n: "abcd",
			c: CONTEXT,
			e: NOW + 1000,
			s: "zzzz-not-hex",
		});
		const result = await verifyOAuthState({
			token: e,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(result).toEqual({ ok: false, code: "INVALID_SIGNATURE" });
	});

	it("rejects with EXPIRED when nowMs > expiresAt", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
			ttlMs: 1000,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW + 1001,
		});
		expect(result).toEqual({ ok: false, code: "EXPIRED" });
	});

	it("accepts a token at exactly its expiry instant (nowMs == expiresAt)", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
			ttlMs: 1000,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: issued.expiresAt,
		});
		expect(result.ok).toBe(true);
	});

	it("rejects with EXPIRED at the very first ms past expiry (kills > → >= boundary mutants)", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
			ttlMs: 1000,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: issued.expiresAt + 1,
		});
		expect(result).toEqual({ ok: false, code: "EXPIRED" });
	});

	it("rejects with CONTEXT_MISMATCH when expectedContext.domain differs", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
			expectedContext: { domain: "newsletter" },
		});
		expect(result).toEqual({ ok: false, code: "CONTEXT_MISMATCH" });
	});

	it("rejects with CONTEXT_MISMATCH when expectedContext.providerId differs", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
			expectedContext: { providerId: "gitlab" },
		});
		expect(result).toEqual({ ok: false, code: "CONTEXT_MISMATCH" });
	});

	it("rejects with CONTEXT_MISMATCH when expectedContext.returnTo differs", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
			expectedContext: { returnTo: "/somewhere-else" },
		});
		expect(result).toEqual({ ok: false, code: "CONTEXT_MISMATCH" });
	});

	it("accepts when expectedContext matches all fields", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
			expectedContext: { ...CONTEXT },
		});
		expect(result.ok).toBe(true);
	});

	it("accepts when expectedContext is partial (e.g. only domain)", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
			expectedContext: { domain: CONTEXT.domain },
		});
		expect(result.ok).toBe(true);
	});

	it("accepts when expectedContext is undefined (no constraint)", async () => {
		const issued = await issueOAuthState({
			context: CONTEXT,
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const result = await verifyOAuthState({
			token: issued.token,
			rootSecret: ROOT,
			nowMs: NOW,
			expectedContext: undefined,
		});
		expect(result.ok).toBe(true);
	});
});

tests/runtime-actions-users.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { registerCms } from "../src/config";
import {
	consumeRuntimeInviteToken,
	consumeRuntimePasswordResetToken,
	createRuntimePasswordResetToken,
	getRuntimeInviteRequest,
	getRuntimePasswordResetRequest,
	inviteRuntimeAdminUser,
	suspendRuntimeAdminUser,
	unsuspendRuntimeAdminUser,
} from "../src/runtime-actions-users";
import { makeDb, STANDARD_ACTOR, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import { makeLocals } from "./helpers/make-locals.js";

const actor = STANDARD_ACTOR;

let db: DatabaseSync;
let locals: App.Locals;

beforeEach(() => {
	db = makeDb();
	locals = makeLocals(db);
	registerCms(STANDARD_CMS_CONFIG);

	db.prepare(
		"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, ?5, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
	).run("admin@test.local", "hash", "admin", "Test Admin", 1);
	db.prepare(
		"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, ?5, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
	).run("editor@test.local", "hash", "editor", "Test Editor", 1);
});

describe("inviteRuntimeAdminUser", () => {
	it("creates a user and returns an invite URL", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "New User", email: "new@test.local", role: "editor" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: true });
		expect((result as { inviteUrl: string }).inviteUrl).toContain("/accept-invite?token=");
	});

	it("rejects duplicate email", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "Dup", email: "editor@test.local", role: "editor" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects missing name", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "  ", email: "x@test.local", role: "editor" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects invalid role", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "X", email: "x@test.local", role: "superuser" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects invalid email format", async () => {
		const result = await inviteRuntimeAdminUser(
			{ name: "X", email: "not-an-email", role: "editor" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false });
	});
});

describe("getRuntimeInviteRequest / consumeRuntimeInviteToken", () => {
	async function createInvite() {
		const invite = await inviteRuntimeAdminUser(
			{ name: "Invite User", email: "invite@test.local", role: "editor" },
			actor,
			locals,
		);
		const rawToken = (invite as { inviteUrl: string }).inviteUrl.split("token=")[1];
		return decodeURIComponent(rawToken);
	}

	it("returns invite details for a valid token", async () => {
		const token = await createInvite();
		const request = await getRuntimeInviteRequest(token, locals);
		expect(request).toMatchObject({
			email: "invite@test.local",
			role: "editor",
		});
	});

	it("returns null for an unknown token", async () => {
		const request = await getRuntimeInviteRequest("bad-token", locals);
		expect(request).toBeNull();
	});

	it("returns null for a blank token", async () => {
		const request = await getRuntimeInviteRequest("   ", locals);
		expect(request).toBeNull();
	});

	it("consumes an invite token and sets password", async () => {
		const token = await createInvite();
		const result = await consumeRuntimeInviteToken(token, "newpassword123", locals);
		expect(result).toMatchObject({ ok: true });
	});

	it("rejects a short password", async () => {
		const token = await createInvite();
		const result = await consumeRuntimeInviteToken(token, "short", locals);
		expect(result).toMatchObject({ ok: false });
	});
});

describe("createRuntimePasswordResetToken / getRuntimePasswordResetRequest / consumeRuntimePasswordResetToken", () => {
	async function createResetToken(email = "editor@test.local") {
		const r = await createRuntimePasswordResetToken(email, actor, locals);
		const rawToken = (r as { resetUrl: string }).resetUrl.split("token=")[1];
		return decodeURIComponent(rawToken);
	}

	it("creates a reset URL for a known active user", async () => {
		const result = await createRuntimePasswordResetToken("editor@test.local", actor, locals);
		expect(result).toMatchObject({ ok: true });
		expect((result as { resetUrl: string }).resetUrl).toContain("/reset-password?token=");
	});

	it("returns not-ok (with actor) for unknown email", async () => {
		const result = await createRuntimePasswordResetToken("nobody@test.local", actor, locals);
		expect(result).toMatchObject({ ok: false });
	});

	it("returns ok with null resetUrl (without actor) for unknown email", async () => {
		const result = await createRuntimePasswordResetToken("nobody@test.local", null, locals);
		expect(result).toMatchObject({ ok: true });
		expect((result as { resetUrl: null }).resetUrl).toBeNull();
	});

	it("returns reset request details for a valid token", async () => {
		const token = await createResetToken();
		const request = await getRuntimePasswordResetRequest(token, locals);
		expect(request).toMatchObject({ email: "editor@test.local" });
	});

	it("returns null for an unknown token", async () => {
		const request = await getRuntimePasswordResetRequest("bad-token", locals);
		expect(request).toBeNull();
	});

	it("consumes a reset token and updates password", async () => {
		const token = await createResetToken();
		const result = await consumeRuntimePasswordResetToken(token, "newpassword123", locals);
		expect(result).toMatchObject({ ok: true });
	}, 15000);

	it("rejects a short password", async () => {
		const token = await createResetToken();
		const result = await consumeRuntimePasswordResetToken(token, "short", locals);
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects an already-consumed token", async () => {
		const token = await createResetToken();
		await consumeRuntimePasswordResetToken(token, "newpassword123", locals);
		const result = await consumeRuntimePasswordResetToken(token, "anotherpassword", locals);
		expect(result).toMatchObject({ ok: false });
	}, 15000);

	it("rejects an empty email with the required-email error", async () => {
		const result = await createRuntimePasswordResetToken("   ", actor, locals);
		expect(result).toEqual({ ok: false, error: "Email is required." });
	});

	it("returns the exact unknown-email error string for known-actor lookups", async () => {
		const result = await createRuntimePasswordResetToken("nobody@test.local", actor, locals);
		expect(result).toEqual({ ok: false, error: "That admin user could not be found." });
	});

	it("stores requested_by = actor.email and writes the issue audit event", async () => {
		await createRuntimePasswordResetToken("editor@test.local", actor, locals);
		const tokenRow = db
			.prepare(
				"SELECT id, requested_by, expires_at FROM password_reset_tokens ORDER BY id DESC LIMIT 1",
			)
			.get() as { id: string; requested_by: string; expires_at: string };
		expect(tokenRow.id.startsWith("reset-")).toBe(true);
		expect(tokenRow.requested_by).toBe(actor.email);
		const expiresMs = Date.parse(tokenRow.expires_at);
		const expectedMs = Date.now() + 60 * 60 * 1000;
		expect(Math.abs(expiresMs - expectedMs)).toBeLessThan(10_000);
		expect(expiresMs).toBeGreaterThan(Date.now() + 50 * 60 * 1000);

		const auditRow = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(auditRow).toEqual({
			user_email: actor.email,
			action: "auth.password_reset_issue",
			resource_type: "auth",
			resource_id: "editor@test.local",
			summary: "Issued a password reset link for editor@test.local.",
		});
	});

	it("stores requested_by = NULL and writes no audit when actor is omitted", async () => {
		const before = (db.prepare("SELECT COUNT(*) AS c FROM audit_events").get() as { c: number }).c;
		await createRuntimePasswordResetToken("editor@test.local", null, locals);
		const tokenRow = db
			.prepare("SELECT requested_by FROM password_reset_tokens ORDER BY id DESC LIMIT 1")
			.get() as { requested_by: string | null };
		expect(tokenRow.requested_by).toBeNull();
		const after = (db.prepare("SELECT COUNT(*) AS c FROM audit_events").get() as { c: number }).c;
		expect(after).toBe(before);
	});

	it("rejects a reset request for an inactive user", async () => {
		await createRuntimePasswordResetToken("editor@test.local", actor, locals);
		const token = (await createRuntimePasswordResetToken("editor@test.local", actor, locals)) as {
			resetUrl: string;
		};
		const rawToken = decodeURIComponent(token.resetUrl.split("token=")[1]);
		db.prepare("UPDATE admin_users SET active = 0 WHERE email = 'editor@test.local'").run();
		const request = await getRuntimePasswordResetRequest(rawToken, locals);
		expect(request).toBeNull();
	});

	it("rejects a reset request for an expired token", async () => {
		const token = await createResetToken();
		db.prepare(
			"UPDATE password_reset_tokens SET expires_at = '2000-01-01T00:00:00.000Z' WHERE consumed_at IS NULL",
		).run();
		const request = await getRuntimePasswordResetRequest(token, locals);
		expect(request).toBeNull();
	});

	it("returns the exact invalid-or-expired error for an unknown token on consume", async () => {
		const result = await consumeRuntimePasswordResetToken(
			"not-a-real-token",
			"newpassword123",
			locals,
		);
		expect(result).toEqual({
			ok: false,
			error: "That password reset link is invalid or has expired.",
		});
	});

	it("returns the exact short-password error for a password trimmed below 12", async () => {
		const token = await createResetToken();
		// 13-char input but trimmed length is 5 ("short"); without trim it'd pass the length check
		const result = await consumeRuntimePasswordResetToken(token, "    short    ", locals);
		expect(result).toEqual({ ok: false, error: "Password must be at least 12 characters." });
	}, 15000);

	it("accepts a password whose trimmed length is exactly 12", async () => {
		const token = await createResetToken();
		const result = await consumeRuntimePasswordResetToken(token, "a".repeat(12), locals);
		expect(result).toMatchObject({ ok: true });
	}, 15000);

	it("returns the user object and writes the complete audit on consume", async () => {
		const token = await createResetToken();
		const result = (await consumeRuntimePasswordResetToken(token, "newpassword123", locals)) as {
			ok: true;
			user: { email: string; role: string; name: string };
		};
		expect(result.ok).toBe(true);
		expect(result.user).toEqual({
			email: "editor@test.local",
			role: "editor",
			name: "Test Editor",
		});

		const auditRow = db
			.prepare(
				"SELECT user_email, action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
			)
			.get() as Record<string, string>;
		expect(auditRow).toEqual({
			user_email: "editor@test.local",
			action: "auth.password_reset_complete",
			resource_type: "auth",
			resource_id: "editor@test.local",
			summary: "editor@test.local completed a password reset.",
		});
	}, 15000);
});

describe("suspendRuntimeAdminUser / unsuspendRuntimeAdminUser", () => {
	it("suspends an active user", async () => {
		const result = await suspendRuntimeAdminUser("editor@test.local", actor, locals);
		expect(result).toMatchObject({ ok: true });
		const row = db
			.prepare("SELECT active FROM admin_users WHERE email = 'editor@test.local'")
			.get() as { active: number };
		expect(row.active).toBe(0);
	});

	it("cannot suspend own account", async () => {
		const result = await suspendRuntimeAdminUser("admin@test.local", actor, locals);
		expect(result).toMatchObject({ ok: false });
	});

	it("returns not-ok for unknown or already-suspended user", async () => {
		const result = await suspendRuntimeAdminUser("nobody@test.local", actor, locals);
		expect(result).toMatchObject({ ok: false });
	});

	it("returns not-ok for blank email on suspend", async () => {
		const result = await suspendRuntimeAdminUser("   ", actor, locals);
		expect(result).toMatchObject({ ok: false });
	});

	it("restores a suspended user", async () => {
		db.prepare("UPDATE admin_users SET active = 0 WHERE email = 'editor@test.local'").run();
		const result = await unsuspendRuntimeAdminUser("editor@test.local", actor, locals);
		expect(result).toMatchObject({ ok: true });
		const row = db
			.prepare("SELECT active FROM admin_users WHERE email = 'editor@test.local'")
			.get() as { active: number };
		expect(row.active).toBe(1);
	});

	it("returns not-ok for already-active user on unsuspend", async () => {
		const result = await unsuspendRuntimeAdminUser("editor@test.local", actor, locals);
		expect(result).toMatchObject({ ok: false });
	});

	it("returns not-ok for blank email on unsuspend", async () => {
		const result = await unsuspendRuntimeAdminUser("   ", actor, locals);
		expect(result).toMatchObject({ ok: false });
	});
});

