import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";

import {
	bootstrapAstropressContentServices,
	verifyAstropressContentServices,
} from "../src/content-services-ops.js";

describe("content services operations", () => {
	it("bootstraps a manifest for configured hosted content services", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-"));
		const report = await bootstrapAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "supabase",
				SUPABASE_URL: "https://demo.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "service",
				ASTROPRESS_SERVICE_ORIGIN: "https://demo.supabase.co/functions/v1/astropress",
			},
		});

		expect(report.supportLevel).toBe("configured");
		expect(report.manifestFile).toBeTruthy();
		expect(await readFile(join(workspace, ".astropress/services/supabase.json"), "utf8")).toContain(
			'"status": "configured"',
		);

		await rm(workspace, { recursive: true, force: true });
	});

	it("reports missing config when verify runs without required keys", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-missing-"));
		await writeFile(join(workspace, ".env"), "ASTROPRESS_CONTENT_SERVICES=appwrite\n");

		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "appwrite",
			},
		});

		expect(report.supportLevel).toBe("missing-config");
		expect(report.missingEnvKeys).toContain("APPWRITE_ENDPOINT");

		await rm(workspace, { recursive: true, force: true });
	});

	it("accepts scaffolded Neon env keys during verification", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-neon-"));

		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "neon",
				ASTROPRESS_SERVICE_ORIGIN: "https://service.example.com/astropress",
				NEON_DATABASE_URL: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
			},
		});

		expect(report.supportLevel).toBe("configured");
		expect(report.missingEnvKeys).toEqual([]);

		await rm(workspace, { recursive: true, force: true });
	});

	it("reports each Cloudflare required env key and persists the supabase manifest payload", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-cf-"));
		const report = await bootstrapAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "cloudflare",
			},
		});
		expect(report.supportLevel).toBe("missing-config");
		expect(report.contentServices).toBe("cloudflare");
		expect(report.requiredEnvKeys).toEqual([
			"ASTROPRESS_SERVICE_ORIGIN",
			"CLOUDFLARE_ACCOUNT_ID",
			"CLOUDFLARE_API_TOKEN",
		]);
		expect(report.missingEnvKeys).toEqual([
			"ASTROPRESS_SERVICE_ORIGIN",
			"CLOUDFLARE_ACCOUNT_ID",
			"CLOUDFLARE_API_TOKEN",
		]);
		const manifest = JSON.parse(
			await readFile(join(workspace, ".astropress/services/cloudflare.json"), "utf8"),
		);
		expect(manifest.contentServices).toBe("cloudflare");
		expect(manifest.status).toBe("missing-config");
		expect(typeof manifest.generatedAt).toBe("string");
		await rm(workspace, { recursive: true, force: true });
	});

	it("returns supportLevel='static' for contentServices='none'", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-none-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: { ASTROPRESS_CONTENT_SERVICES: "none" },
		});
		expect(report.supportLevel).toBe("static");
		expect(report.requiredEnvKeys).toEqual([]);
		expect(report.missingEnvKeys).toEqual([]);
		await rm(workspace, { recursive: true, force: true });
	});

	it("accepts DATABASE_URL as a Neon fallback when NEON_DATABASE_URL is not set", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-neon-fb-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "neon",
				ASTROPRESS_SERVICE_ORIGIN: "https://demo.example.com",
				DATABASE_URL: "postgres://x@y/z",
			},
		});
		expect(report.missingEnvKeys).toEqual([]);
		expect(report.supportLevel).toBe("configured");
		await rm(workspace, { recursive: true, force: true });
	});

	it("for Neon, treats non-NEON_DATABASE_URL keys as required via the same trim check (not the DATABASE_URL fallback)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-neon-keys-"));
		// Neon requires ASTROPRESS_SERVICE_ORIGIN + (NEON_DATABASE_URL || DATABASE_URL)
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "neon",
				NEON_DATABASE_URL: "postgres://x@y/z",
				// ASTROPRESS_SERVICE_ORIGIN missing — should be flagged
			},
		});
		expect(report.missingEnvKeys).toContain("ASTROPRESS_SERVICE_ORIGIN");
		expect(report.missingEnvKeys).not.toContain("NEON_DATABASE_URL");
		await rm(workspace, { recursive: true, force: true });
	});

	it("reports the exact required-env-keys list for every supported content service", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-keys-"));
		const cases: [string, string[]][] = [
			["supabase", ["ASTROPRESS_SERVICE_ORIGIN", "SUPABASE_URL", "SUPABASE_SERVICE_ROLE_KEY"]],
			[
				"appwrite",
				[
					"ASTROPRESS_SERVICE_ORIGIN",
					"APPWRITE_ENDPOINT",
					"APPWRITE_PROJECT_ID",
					"APPWRITE_API_KEY",
				],
			],
			[
				"nhost",
				["ASTROPRESS_SERVICE_ORIGIN", "NHOST_SUBDOMAIN", "NHOST_REGION", "NHOST_ADMIN_SECRET"],
			],
			["neon", ["ASTROPRESS_SERVICE_ORIGIN", "NEON_DATABASE_URL"]],
			["turso", ["ASTROPRESS_SERVICE_ORIGIN", "TURSO_DATABASE_URL", "TURSO_AUTH_TOKEN"]],
		];
		for (const [service, expected] of cases) {
			const report = await verifyAstropressContentServices({
				workspaceRoot: workspace,
				env: { ASTROPRESS_CONTENT_SERVICES: service },
			});
			expect(report.requiredEnvKeys).toEqual(expected);
		}
		await rm(workspace, { recursive: true, force: true });
	});

	it("treats whitespace-only NEON_DATABASE_URL as missing (kills L69 NEON_DATABASE_URL trim drop)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-neon-ws-primary-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "neon",
				ASTROPRESS_SERVICE_ORIGIN: "https://demo.example.com",
				NEON_DATABASE_URL: "   ",
			},
		});
		expect(report.missingEnvKeys).toContain("NEON_DATABASE_URL");
		await rm(workspace, { recursive: true, force: true });
	});

	it("treats whitespace-only ASTROPRESS_SERVICE_ORIGIN as missing in Neon path (kills L67 non-primary trim drop)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-neon-ws-origin-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "neon",
				ASTROPRESS_SERVICE_ORIGIN: "   ",
				NEON_DATABASE_URL: "postgres://x@y/z",
			},
		});
		expect(report.missingEnvKeys).toContain("ASTROPRESS_SERVICE_ORIGIN");
		await rm(workspace, { recursive: true, force: true });
	});

	it("treats whitespace-only DATABASE_URL as missing in the Neon fallback (kills L69 DATABASE_URL trim drop)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-neon-ws-fb-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "neon",
				ASTROPRESS_SERVICE_ORIGIN: "https://demo.example.com",
				DATABASE_URL: "   ",
			},
		});
		expect(report.missingEnvKeys).toContain("NEON_DATABASE_URL");
		await rm(workspace, { recursive: true, force: true });
	});

	it("persists a 2-space-indented JSON manifest with a trailing newline", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-json-"));
		await bootstrapAstropressContentServices({
			workspaceRoot: workspace,
			env: { ASTROPRESS_CONTENT_SERVICES: "supabase" },
		});
		const raw = await readFile(join(workspace, ".astropress/services/supabase.json"), "utf8");
		expect(raw.endsWith("\n")).toBe(true);
		expect(raw).toContain('\n  "contentServices"');
		await rm(workspace, { recursive: true, force: true });
	});

	it("verify returns the same manifestFile path when the manifest exists on disk", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-verify-path-"));
		await bootstrapAstropressContentServices({
			workspaceRoot: workspace,
			env: { ASTROPRESS_CONTENT_SERVICES: "supabase" },
		});
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: { ASTROPRESS_CONTENT_SERVICES: "supabase" },
		});
		expect(report.manifestFile).toBe(join(workspace, ".astropress/services/supabase.json"));
	});

	it("reports each Pocketbase required env key", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-pb-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: { ASTROPRESS_CONTENT_SERVICES: "pocketbase" },
		});
		expect(report.requiredEnvKeys).toEqual([
			"ASTROPRESS_SERVICE_ORIGIN",
			"POCKETBASE_URL",
			"POCKETBASE_EMAIL",
			"POCKETBASE_PASSWORD",
		]);
		await rm(workspace, { recursive: true, force: true });
	});

	it("returns supportLevel='static' (no requiredEnvKeys) for an unknown contentServices identifier", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-unknown-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: { ASTROPRESS_CONTENT_SERVICES: "fictional" },
		});
		expect(report.requiredEnvKeys).toEqual([]);
		expect(report.missingEnvKeys).toEqual([]);
		// Unknown service is not 'none' but yields configured because no env is missing
		expect(["configured", "static"]).toContain(report.supportLevel);
		await rm(workspace, { recursive: true, force: true });
	});

	it("verify falls through to a no-manifest report when the manifest file does not exist", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-no-manifest-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "supabase",
				ASTROPRESS_SERVICE_ORIGIN: "https://x.supabase.co/functions/v1/astropress",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "k",
			},
		});
		expect(report.manifestFile).toBeUndefined();
		expect(report.supportLevel).toBe("configured");
		await rm(workspace, { recursive: true, force: true });
	});

	it("treats whitespace-only env values as missing", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-trim-"));
		const report = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "supabase",
				ASTROPRESS_SERVICE_ORIGIN: "   ",
				SUPABASE_URL: "  ",
				SUPABASE_SERVICE_ROLE_KEY: "\t",
			},
		});
		expect(report.missingEnvKeys).toEqual([
			"ASTROPRESS_SERVICE_ORIGIN",
			"SUPABASE_URL",
			"SUPABASE_SERVICE_ROLE_KEY",
		]);
		await rm(workspace, { recursive: true, force: true });
	});

	it("reports NHOST and Turso missing keys with the canonical env contract", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-services-more-"));

		const nhostReport = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "nhost",
			},
		});
		const tursoReport = await verifyAstropressContentServices({
			workspaceRoot: workspace,
			env: {
				ASTROPRESS_CONTENT_SERVICES: "turso",
			},
		});

		expect(nhostReport.missingEnvKeys).toContain("NHOST_SUBDOMAIN");
		expect(tursoReport.missingEnvKeys).toContain("TURSO_DATABASE_URL");

		await rm(workspace, { recursive: true, force: true });
	});
});

tests/sqlite-bootstrap.test.ts.source:
import { existsSync, mkdirSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { verifyArgon2idPassword } from "../src/crypto-primitives";
import {
	createAstropressSqliteSeedToolkit,
	createDefaultAstropressSqliteSeedToolkit,
} from "../src/sqlite-bootstrap";
import { makeDb } from "./helpers/make-db.js";

let tmpDir: string;
let tmpDbPath: string;

beforeEach(() => {
	tmpDir = path.join(
		tmpdir(),
		`astropress-bootstrap-test-${Date.now()}-${Math.random().toString(36).slice(2)}`,
	);
	mkdirSync(tmpDir, { recursive: true });
	tmpDbPath = path.join(tmpDir, "admin.sqlite");
});

afterEach(() => {
	rmSync(tmpDir, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// createDefaultAstropressSqliteSeedToolkit — default seed values
// ---------------------------------------------------------------------------

describe("createDefaultAstropressSqliteSeedToolkit — default seed users", () => {
	// Two argon2id verifications run back-to-back here. Under v8 coverage
	// instrumentation the per-verify cost roughly triples, so the default
	// 30s vitest timeout can fire on a loaded prepush worker. 60s gives the
	// crypto path headroom without hiding a regression.
	it("seeds the documented admin@example.com / editor@example.com bootstrap users with roles 'admin' and 'editor' and names 'Admin' / 'Editor', each with a non-empty password hash", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const db = makeDb();
		toolkit.seedDatabase({ db, dbPath: ":memory:" });

		const users = db
			.prepare("SELECT email, name, is_admin, password_hash FROM admin_users ORDER BY email")
			.all() as Array<{
			email: string;
			name: string;
			is_admin: number;
			password_hash: string;
		}>;

		const admin = users.find((u) => u.email === "admin@example.com");
		const editor = users.find((u) => u.email === "editor@example.com");
		expect(admin).toBeDefined();
		expect(admin?.name).toBe("Admin");
		expect(admin?.is_admin).toBe(1);
		expect(verifyArgon2idPassword("password", admin?.password_hash ?? "")).toBe(true);

		expect(editor).toBeDefined();
		expect(editor?.name).toBe("Editor");
		expect(editor?.is_admin).toBe(0);
		expect(verifyArgon2idPassword("password", editor?.password_hash ?? "")).toBe(true);
	}, 60_000);
});

describe("createDefaultAstropressSqliteSeedToolkit — default site settings", () => {
	it("seeds siteTitle='Astropress', siteTagline='Low-carbon publishing', donationUrl='https://example.com/donate', newsletterEnabled=false", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const db = makeDb();
		toolkit.seedDatabase({ db, dbPath: ":memory:" });

		const row = db
			.prepare(
				"SELECT site_title, site_tagline, donation_url, newsletter_enabled FROM site_settings WHERE id = 1",
			)
			.get() as Record<string, unknown> | undefined;
		expect(row).toBeDefined();
		expect(row?.site_title).toBe("Astropress");
		expect(row?.site_tagline).toBe("Low-carbon publishing");
		expect(row?.donation_url).toBe("https://example.com/donate");
		expect(row?.newsletter_enabled).toBe(0);
	});
});

// ---------------------------------------------------------------------------
// seedDatabase — connection ownership semantics (ownsConnection branch)
// ---------------------------------------------------------------------------

describe("seedDatabase — ownsConnection semantics", () => {
	it("does NOT close the provided db (ownsConnection=false): the caller's db remains usable after seedDatabase returns", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const db = makeDb();
		toolkit.seedDatabase({ db, dbPath: ":memory:" });
		// If db were closed, this query would throw.
		const count = db.prepare("SELECT COUNT(*) AS n FROM admin_users").get() as { n: number };
		expect(count.n).toBeGreaterThan(0);
	});

	it("creates the parent directory and the database file when no db is provided (ownsConnection=true)", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const nestedPath = path.join(tmpDir, "deep", "nested", "admin.sqlite");
		expect(existsSync(path.dirname(nestedPath))).toBe(false);
		toolkit.seedDatabase({ dbPath: nestedPath });
		expect(existsSync(path.dirname(nestedPath))).toBe(true);
		expect(existsSync(nestedPath)).toBe(true);
	});
});

// ---------------------------------------------------------------------------
// seedDatabase — reset behaviour (reset=true vs file path)
// ---------------------------------------------------------------------------

describe("seedDatabase — reset", () => {
	it("removes an existing file when reset=true: an extra row written between seedings does not survive the reset", async () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		toolkit.seedDatabase({ dbPath: tmpDbPath });
		expect(existsSync(tmpDbPath)).toBe(true);

		// Write a marker row to the existing DB so we can detect a reset.
		const { DatabaseSync } = await import("node:sqlite");
		const probe = new DatabaseSync(tmpDbPath);
		probe.prepare("CREATE TABLE marker_table (n INTEGER)").run();
		probe.prepare("INSERT INTO marker_table (n) VALUES (42)").run();
		probe.close();

		toolkit.seedDatabase({ dbPath: tmpDbPath, reset: true });
		expect(existsSync(tmpDbPath)).toBe(true);

		const verify = new DatabaseSync(tmpDbPath);
		try {
			const row = verify
				.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='marker_table'")
				.get();
			expect(row).toBeUndefined();
		} finally {
			verify.close();
		}
	});

	it("preserves an existing file (no reset side-effect) when reset is omitted: a marker row added between seedings is preserved", async () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		toolkit.seedDatabase({ dbPath: tmpDbPath });

		const { DatabaseSync } = await import("node:sqlite");
		const probe = new DatabaseSync(tmpDbPath);
		probe.prepare("CREATE TABLE marker_keep (n INTEGER)").run();
		probe.close();

		toolkit.seedDatabase({ dbPath: tmpDbPath });

		const verify = new DatabaseSync(tmpDbPath);
		try {
			const row = verify
				.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='marker_keep'")
				.get() as { name: string } | undefined;
			expect(row?.name).toBe("marker_keep");
		} finally {
			verify.close();
		}
	});

	it("does NOT call rmSync when dbPath is ':memory:' even with reset=true (no filesystem side effect)", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const db = makeDb();
		// If rmSync were attempted on :memory:, it would throw ENOENT (no such path)
		// and the call would surface as a test failure. The :memory: guard avoids this.
		expect(() => toolkit.seedDatabase({ db, dbPath: ":memory:", reset: true })).not.toThrow();
	});

	it("passes { force: true } to rmSync so reset=true on a non-existent dbPath does NOT throw ENOENT", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const absentPath = path.join(tmpDir, "never-existed.sqlite");
		expect(existsSync(absentPath)).toBe(false);
		// With { force: true }, rmSync silently no-ops on a missing path. Without
		// it (e.g. {} or { force: false }), rmSync throws ENOENT.
		expect(() => toolkit.seedDatabase({ dbPath: absentPath, reset: true })).not.toThrow();
		expect(existsSync(absentPath)).toBe(true);
	});
});

// ---------------------------------------------------------------------------
// seedDatabase — workspaceRoot resolution (LogicalOperator ??)
// ---------------------------------------------------------------------------

describe("seedDatabase — workspaceRoot", () => {
	it("uses an explicit workspaceRoot to derive the default dbPath when dbPath is omitted", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const workspaceRoot = path.join(tmpDir, "explicit-workspace");
		mkdirSync(workspaceRoot, { recursive: true });

		toolkit.seedDatabase({ workspaceRoot });

		const expected = path.join(workspaceRoot, ".data", "admin.sqlite");
		expect(existsSync(expected)).toBe(true);
	});
});

// ---------------------------------------------------------------------------
// seedDatabase — error wrapping (catch block in seedDatabase)
// ---------------------------------------------------------------------------

describe("seedDatabase — error wrapping", () => {
	it("wraps a downstream seeder error with the documented 'Database seeding failed:' prefix", () => {
		const toolkit = createAstropressSqliteSeedToolkit({
			readSchemaSql: () => {
				throw new Error("schema-load-fail");
			},
			loadBootstrapUsers: () => [],
			loadMediaSeeds: () => [],
			redirectRules: [],
			comments: [],
			systemRoutes: [],
			archiveRoutes: [],
			marketingRoutes: [],
			siteSettings: {
				siteTitle: "T",
				siteTagline: "G",
				donationUrl: "",
				newsletterEnabled: false,
				commentsDefaultPolicy: "open-moderated",
			},
		});
		const db = makeDb();
		expect(() => toolkit.seedDatabase({ db, dbPath: ":memory:" })).toThrow(
			/^Database seeding failed:/,
		);
	});
});

// ---------------------------------------------------------------------------
// getDefaultAdminDbPath — workspaceRoot resolution
// ---------------------------------------------------------------------------

describe("getDefaultAdminDbPath", () => {
	it("returns '<workspaceRoot>/.data/admin.sqlite' when no override is provided", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		expect(toolkit.getDefaultAdminDbPath("/abs/workspace")).toBe(
			path.join("/abs/workspace", ".data", "admin.sqlite"),
		);
	});

	it("delegates to the user-provided getDefaultAdminDbPath option when supplied (?? short-circuits)", () => {
		const toolkit = createAstropressSqliteSeedToolkit({
			readSchemaSql: () => "",
			loadBootstrapUsers: () => [],
			loadMediaSeeds: () => [],
			redirectRules: [],
			comments: [],
			systemRoutes: [],
			archiveRoutes: [],
			marketingRoutes: [],
			siteSettings: {
				siteTitle: "T",
				siteTagline: "G",
				donationUrl: "",
				newsletterEnabled: false,
				commentsDefaultPolicy: "open-moderated",
			},
			getDefaultAdminDbPath: (root) => `${root}/custom-override.sqlite`,
		});
		expect(toolkit.getDefaultAdminDbPath("/abs/workspace")).toBe(
			"/abs/workspace/custom-override.sqlite",
		);
	});
});

// ---------------------------------------------------------------------------
// openSeedDatabase — :memory: vs file branches
// ---------------------------------------------------------------------------

describe("openSeedDatabase", () => {
	it("opens a :memory: database with foreign_keys ON (no journal_mode/synchronous pragmas applied)", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const db = toolkit.openSeedDatabase(":memory:");
		try {
			const fk = db.prepare("PRAGMA foreign_keys").get() as { foreign_keys: number };
			expect(fk.foreign_keys).toBe(1);
			// :memory: journal_mode is always "memory" (cannot be set to WAL); the
			// :memory: guard means the WAL pragma never runs, but the result is
			// the same — confirming :memory: opens cleanly.
			const jm = db.prepare("PRAGMA journal_mode").get() as { journal_mode: string };
			expect(jm.journal_mode).toBe("memory");
		} finally {
			db.close();
		}
	});

	it("applies WAL + NORMAL synchronous pragmas to a file-based database", () => {
		const toolkit = createDefaultAstropressSqliteSeedToolkit();
		const db = toolkit.openSeedDatabase(tmpDbPath);
		try {
			const jm = db.prepare("PRAGMA journal_mode").get() as { journal_mode: string };
			expect(jm.journal_mode).toBe("wal");
			const sync = db.prepare("PRAGMA synchronous").get() as { synchronous: number };
			// PRAGMA synchronous = NORMAL → 1
			expect(sync.synchronous).toBe(1);
		} finally {
			db.close();
		}
	});
});

tests/vite-runtime-alias.test.ts.source:
import {
	createAstropressLocalRuntimeModulePlugin,
	createAstropressPackageResolverPlugin,
	createAstropressViteAliases,
	isAstropressLocalRuntimeModuleRequest,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

describe("vite runtime alias helpers", () => {
	const localRuntimeModulesPath = "/tmp/site/src/astropress/local-runtime-modules.ts";

	it("matches relative and resolved local runtime module requests", () => {
		expect(
			isAstropressLocalRuntimeModuleRequest("./local-runtime-modules", localRuntimeModulesPath),
		).toBe(true);
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"/tmp/site/src/astropress/local-runtime-modules.ts",
				localRuntimeModulesPath,
			),
		).toBe(true);
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"file:///tmp/site/src/astropress/local-runtime-modules.ts",
				localRuntimeModulesPath,
			),
		).toBe(true);
		expect(isAstropressLocalRuntimeModuleRequest("./something-else", localRuntimeModulesPath)).toBe(
			false,
		);
	});

	it("creates a pre-resolution plugin that rewrites runtime module imports", () => {
		const plugin = createAstropressLocalRuntimeModulePlugin(localRuntimeModulesPath);

		expect(plugin.name).toBe("astropress-local-runtime-modules");
		expect(plugin.enforce).toBe("pre");
		expect(plugin.resolveId("./local-runtime-modules")).toBe(localRuntimeModulesPath);
		expect(plugin.resolveId("./not-it")).toBeNull();
	});

	it("normalizes Windows-style file:// URLs to a drive-letter path", () => {
		// After file:// stripping, /C:/path matches ^/[a-zA-Z]:/ → slice(1) → C:/path
		const winPath = "C:/site/src/astropress/local-runtime-modules.ts";
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"file:///C:/site/src/astropress/local-runtime-modules.ts",
				winPath,
			),
		).toBe(true);
	});

	it("intercepts the scoped package import path used by Vite when noExternal is active", () => {
		// When ssr.noExternal includes '@astropress-diy/astropress', Vite processes
		// the package through its plugin pipeline. Imports inside the dist files
		// (e.g. admin-store-dispatch.js → "./local-runtime-modules") still arrive
		// as the raw "./local-runtime-modules" string and are handled by the first
		// check. The scoped-package form is used when a consumer imports directly:
		//   import ... from "@astropress-diy/astropress/local-runtime-modules"
		// Both must be caught so the host's SQLite implementation is used, not the
		// dist stub that throws `unavailable()`.
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"@astropress-diy/astropress/local-runtime-modules",
				localRuntimeModulesPath,
			),
		).toBe(true);
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"@astropress-diy/astropress/local-runtime-modules.ts",
				localRuntimeModulesPath,
			),
		).toBe(true);
	});

	it("intercepts absolute dist-stub paths that Vite may resolve before calling resolveId", () => {
		// With noExternal active, Vite can resolve the relative import to an
		// absolute path (pointing into the package dist) before the plugin's
		// resolveId runs. Both Unix and Windows forms must be handled.
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"/home/runner/work/astropress/packages/astropress/dist/src/local-runtime-modules.js",
				localRuntimeModulesPath,
			),
		).toBe(true);
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"C:/work/astropress/packages/astropress/dist/src/local-runtime-modules.js",
				localRuntimeModulesPath,
			),
		).toBe(true);
		// Unrelated absolute paths must not match.
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"/home/runner/work/astropress/packages/astropress/dist/src/admin-store-dispatch.js",
				localRuntimeModulesPath,
			),
		).toBe(false);
	});

	it("builds alias rules for local runtime modules and cloudflare workers stubs", () => {
		const aliases = createAstropressViteAliases({
			localRuntimeModulesPath,
			cloudflareWorkersStubPath: "/tmp/site/src/cloudflare-workers-stub.ts",
		});

		expect(aliases).toHaveLength(3);
		expect(aliases[0]).toEqual({
			find: "cloudflare:workers",
			replacement: "/tmp/site/src/cloudflare-workers-stub.ts",
		});
		expect(aliases[1].replacement).toBe(localRuntimeModulesPath);
		expect(aliases[2].replacement).toBe(localRuntimeModulesPath);
	});
});

describe("createAstropressPackageResolverPlugin — npm consumer bare-import redirect", () => {
	// Regression guard: Vite 7's module runner does not invoke resolveId plugins for
	// bare specifiers imported from within node_modules files when the package is
	// listed under noExternal. The correct fix is that published .astro pages must use
	// the scoped package name (@astropress-diy/astropress/…) directly. This plugin
	// remains as belt-and-suspenders for user-land imports only. Tests here verify the
	// plugin's resolution logic is correct for the cases it does handle.
	const packageRoot = "/home/site/node_modules/@astropress-diy/astropress";

	it("has the expected plugin metadata", () => {
		const plugin = createAstropressPackageResolverPlugin(packageRoot);
		expect(plugin.name).toBe("astropress-package-resolver");
		expect(plugin.enforce).toBe("pre");
	});

	it("resolves bare astropress to dist/index.js", () => {
		const plugin = createAstropressPackageResolverPlugin(packageRoot);
		expect(plugin.resolveId("astropress")).toBe(`${packageRoot}/dist/index.js`);
	});

	it("resolves astropress/components/X to the package components directory", () => {
		const plugin = createAstropressPackageResolverPlugin(packageRoot);
		expect(plugin.resolveId("astropress/components/AdminLayout.astro")).toBe(
			`${packageRoot}/components/AdminLayout.astro`,
		);
		expect(plugin.resolveId("astropress/components/CsrfInput.astro")).toBe(
			`${packageRoot}/components/CsrfInput.astro`,
		);
	});

	it("resolves astropress/X subpaths to dist/src/X.js", () => {
		const plugin = createAstropressPackageResolverPlugin(packageRoot);
		expect(plugin.resolveId("astropress/services-config")).toBe(
			`${packageRoot}/dist/src/services-config.js`,
		);
		expect(plugin.resolveId("astropress/newsletter-adapter")).toBe(
			`${packageRoot}/dist/src/newsletter-adapter.js`,
		);
		expect(plugin.resolveId("astropress/runtime-env")).toBe(
			`${packageRoot}/dist/src/runtime-env.js`,
		);
	});

	it("returns null for unrelated imports", () => {
		const plugin = createAstropressPackageResolverPlugin(packageRoot);
		expect(plugin.resolveId("./local-runtime-modules")).toBeNull();
		expect(plugin.resolveId("@astropress-diy/astropress")).toBeNull();
		expect(plugin.resolveId("astro")).toBeNull();
	});
});

describe("createAstropressLocalRuntimeModulePlugin — missing-alias guard", () => {
	it("throws a descriptive error when the runtime modules path is empty", () => {
		expect(() => createAstropressLocalRuntimeModulePlugin("")).toThrow(
			"[astropress] Missing Vite alias: 'local-runtime-modules'. " +
				"Add astropressIntegration() to your astro.config.mjs — " +
				"see https://astropress.diy/docs/quick-start#step-2-add-the-integration",
		);
	});
});

describe("normalizeRuntimeRequest — exercised via isAstropressLocalRuntimeModuleRequest", () => {
	// A localRuntimeModulesPath that does NOT contain the literal
	// "local-runtime-modules" so the hardcoded `.endsWith(...)` fallbacks cannot
	// match — every `true` result must flow through the path-equality branch,
	// making the normalization logic observable.
	const customPath = "/tmp/site/custom-modules.ts";

	it("normalizes backslash separators to forward slashes before comparing", () => {
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"\\tmp\\site\\custom-modules.ts",
				"/tmp/site/custom-modules.ts",
			),
		).toBe(true);
	});

	it("strips a file:// prefix before comparing", () => {
		expect(
			isAstropressLocalRuntimeModuleRequest("file:///tmp/site/custom-modules.ts", customPath),
		).toBe(true);
		// A non-file:// path that does not equal the target stays unmatched.
		expect(isAstropressLocalRuntimeModuleRequest("/tmp/site/other.ts", customPath)).toBe(false);
	});

	it("strips a two-slash file:// prefix as well as the three-slash form", () => {
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"file://tmp/site/custom-modules.ts",
				"/tmp/site/custom-modules.ts",
			),
		).toBe(true);
	});

	it("percent-decodes the path after stripping file://", () => {
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"file:///tmp/site%20space/custom-modules.ts",
				"/tmp/site space/custom-modules.ts",
			),
		).toBe(true);
	});

	it("does not throw on a malformed percent sequence in a non-file URL", () => {
		// The decodeURIComponent call lives behind the file:// guard; a bare
		// path containing an invalid `%` sequence must pass through untouched.
		expect(() =>
			isAstropressLocalRuntimeModuleRequest("ab%zz/custom-modules.ts", customPath),
		).not.toThrow();
		expect(isAstropressLocalRuntimeModuleRequest("ab%zz/custom-modules.ts", customPath)).toBe(
			false,
		);
	});

	it("slices the leading slash off a Windows drive-letter path", () => {
		// The id carries a leading-slash drive path (from file:// stripping); the
		// target has none. They only compare equal once the drive-letter slice
		// runs on the id — so the slice and its `/^\/[a-zA-Z]:\//` guard are both
		// observable here.
		expect(
			isAstropressLocalRuntimeModuleRequest(
				"file:///C:/site/custom-modules.ts",
				"C:/site/custom-modules.ts",
			),
		).toBe(true);
	});

	it("returns true via the path-equality branch even when no suffix matches", () => {
		expect(isAstropressLocalRuntimeModuleRequest(customPath, customPath)).toBe(true);
	});
});

describe("createAstropressViteAliases — find regexes and optional branches", () => {
	const localRuntimeModulesPath = "/tmp/site/src/astropress/local-runtime-modules.ts";

	it("emits exactly the two runtime-module aliases with their find regexes when no options are set", () => {
		const aliases = createAstropressViteAliases({ localRuntimeModulesPath });
		expect(aliases).toHaveLength(2);
		expect(aliases[0]).toEqual({
			find: /\/local-runtime-modules(?:\.[jt]s)?$/,
			replacement: localRuntimeModulesPath,
		});
		expect(aliases[1]).toEqual({
			find: /^\.\/local-runtime-modules(?:\.[jt]s)?$/,
			replacement: localRuntimeModulesPath,
		});
	});

	it("first find regex matches resolved runtime-module paths and rejects near-misses", () => {
		const [first] = createAstropressViteAliases({ localRuntimeModulesPath });
		const re = first.find as RegExp;
		expect(re.test("/x/local-runtime-modules")).toBe(true);
		expect(re.test("/x/local-runtime-modules.ts")).toBe(true);
		expect(re.test("/x/local-runtime-modules.js")).toBe(true);
		expect(re.test("/x/local-runtime-modules.css")).toBe(false);
		expect(re.test("/x/local-runtime-modules.ts.map")).toBe(false);
	});

	it("appends astropress package aliases only when astropressPackageRoot is provided", () => {
		const root = "/home/site/node_modules/@astropress-diy/astropress";
		const aliases = createAstropressViteAliases({
			localRuntimeModulesPath,
			astropressPackageRoot: root,
		});
		expect(aliases).toHaveLength(4);
		expect(aliases[2]).toEqual({ find: /^astropress\/(.+)$/, replacement: `${root}/$1` });
		expect(aliases[3]).toEqual({ find: /^astropress$/, replacement: root });
	});

	it("prepends the cloudflare:workers alias when a stub path is provided", () => {
		const aliases = createAstropressViteAliases({
			localRuntimeModulesPath,
			cloudflareWorkersStubPath: "/tmp/site/stub.ts",
		});
		expect(aliases[0]).toEqual({
			find: "cloudflare:workers",
			replacement: "/tmp/site/stub.ts",
		});
	});

	it("does not prepend a cloudflare alias when no stub path is provided", () => {
		const aliases = createAstropressViteAliases({ localRuntimeModulesPath });
		expect(aliases.some((a) => a.find === "cloudflare:workers")).toBe(false);
	});
});

tests/runtime-actions-media-helpers.test.source:
// Unit tests for runtime-actions-media-helpers.ts, exercising helpers directly
// to pin every behavioural branch: dimension detection, thumbnail generation,
// responsive-format gating, and the storage-callback contracts for thumbnails
// and srcset variants.
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const { mockImageSize, mockSharp, mockStoreMedia, mockGenerateSrcset, sharpInstance } = vi.hoisted(
	() => {
		const sharpInstance = {
			resize: vi.fn(),
			webp: vi.fn(),
			toBuffer: vi.fn(),
		};
		return {
			mockImageSize: vi.fn(),
			mockSharp: vi.fn(),
			mockStoreMedia: vi.fn(),
			mockGenerateSrcset: vi.fn(),
			sharpInstance,
		};
	},
);

vi.mock("image-size", () => ({ imageSize: mockImageSize }));
vi.mock("sharp", () => ({ default: mockSharp }));
vi.mock("../src/runtime-media-storage", () => ({
	storeRuntimeMediaObject: mockStoreMedia,
	deleteRuntimeMediaObject: vi.fn(),
}));
vi.mock("../src/runtime-media-storage.js", () => ({
	storeRuntimeMediaObject: mockStoreMedia,
	deleteRuntimeMediaObject: vi.fn(),
}));
vi.mock("../src/local-image-storage.js", () => ({
	generateSrcset: mockGenerateSrcset,
}));

// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let detectImageDimensions: typeof import("../src/runtime-actions-media-helpers.js").detectImageDimensions;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let generateThumbnail: typeof import("../src/runtime-actions-media-helpers.js").generateThumbnail;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let isResponsiveImageFormat: typeof import("../src/runtime-actions-media-helpers.js").isResponsiveImageFormat;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let generateAndStoreThumbnail: typeof import("../src/runtime-actions-media-helpers.js").generateAndStoreThumbnail;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let generateAndStoreSrcset: typeof import("../src/runtime-actions-media-helpers.js").generateAndStoreSrcset;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let detectImageDimensionsForMime: typeof import("../src/runtime-actions-media-helpers.js").detectImageDimensionsForMime;

beforeEach(async () => {
	vi.resetModules();
	({
		detectImageDimensions,
		generateThumbnail,
		isResponsiveImageFormat,
		generateAndStoreThumbnail,
		generateAndStoreSrcset,
		detectImageDimensionsForMime,
	} = await import("../src/runtime-actions-media-helpers.js"));
	mockImageSize.mockReset();
	mockSharp.mockReset();
	mockStoreMedia.mockReset();
	mockGenerateSrcset.mockReset();
	sharpInstance.resize.mockReset();
	sharpInstance.webp.mockReset();
	sharpInstance.toBuffer.mockReset();
	sharpInstance.resize.mockReturnValue(sharpInstance);
	sharpInstance.webp.mockReturnValue(sharpInstance);
	mockSharp.mockReturnValue(sharpInstance);
});

afterEach(() => {
	vi.clearAllMocks();
});

describe("detectImageDimensions", () => {
	it("returns null when only width is detected (height missing)", async () => {
		mockImageSize.mockReturnValue({ width: 200 });
		const result = await detectImageDimensions(new Uint8Array([1, 2]));
		expect(result).toBeNull();
	});

	it("returns null when only height is detected (width missing)", async () => {
		mockImageSize.mockReturnValue({ height: 300 });
		const result = await detectImageDimensions(new Uint8Array([1, 2]));
		expect(result).toBeNull();
	});

	it("returns the {width,height} object when both are detected", async () => {
		mockImageSize.mockReturnValue({ width: 200, height: 150, type: "png" });
		const result = await detectImageDimensions(new Uint8Array([1, 2]));
		expect(result).toEqual({ width: 200, height: 150 });
	});

	it("returns null (not undefined) when image-size throws", async () => {
		mockImageSize.mockImplementation(() => {
			throw new Error("bad image");
		});
		const result = await detectImageDimensions(new Uint8Array([1, 2]));
		expect(result).toBeNull();
	});
});

describe("generateThumbnail", () => {
	it("invokes sharp().resize({width:400}).webp().toBuffer() and returns its bytes", async () => {
		const out = Buffer.from([0xaa, 0xbb, 0xcc]);
		sharpInstance.toBuffer.mockResolvedValue(out);
		const result = await generateThumbnail(new Uint8Array([0xff]), 800);
		expect(sharpInstance.resize).toHaveBeenCalledWith({ width: 400 });
		expect(sharpInstance.webp).toHaveBeenCalled();
		expect(result).toBeInstanceOf(Uint8Array);
		expect(Array.from(result as Uint8Array)).toEqual([0xaa, 0xbb, 0xcc]);
	});

	it("returns null (not undefined) when sharp throws", async () => {
		mockSharp.mockImplementation(() => {
			throw new Error("no sharp");
		});
		const result = await generateThumbnail(new Uint8Array([0xff]), 800);
		expect(result).toBeNull();
	});
});

describe("isResponsiveImageFormat", () => {
	it("returns true for image/jpeg", () => {
		expect(isResponsiveImageFormat("image/jpeg")).toBe(true);
	});
	it("returns true for image/png", () => {
		expect(isResponsiveImageFormat("image/png")).toBe(true);
	});
	it("returns false for image/svg+xml", () => {
		expect(isResponsiveImageFormat("image/svg+xml")).toBe(false);
	});
	it("returns false for non-image types", () => {
		expect(isResponsiveImageFormat("application/pdf")).toBe(false);
	});
});

describe("generateAndStoreThumbnail", () => {
	const input = {
		filename: "photo.jpg",
		bytes: new Uint8Array([0xff, 0xd8]),
		mimeType: "image/jpeg",
		title: "Photo",
		altText: "alt",
	};

	it("returns null without calling sharp when width is exactly 400", async () => {
		const result = await generateAndStoreThumbnail(input, "photo.jpg", 400, null);
		expect(result).toBeNull();
		expect(mockSharp).not.toHaveBeenCalled();
		expect(mockStoreMedia).not.toHaveBeenCalled();
	});

	it("generates a thumbnail when width is greater than 400 (boundary 401)", async () => {
		sharpInstance.toBuffer.mockResolvedValue(Buffer.from([0x11]));
		mockStoreMedia.mockResolvedValue({
			ok: true,
			asset: { publicPath: "/p/photo-thumb.webp" },
		});
		const result = await generateAndStoreThumbnail(input, "photo.jpg", 401, null);
		expect(result).toBe("/p/photo-thumb.webp");
		expect(mockSharp).toHaveBeenCalled();
	});

	it("returns null when thumbnail generation produces no bytes (sharp unavailable)", async () => {
		mockSharp.mockImplementation(() => {
			throw new Error("no sharp");
		});
		const result = await generateAndStoreThumbnail(input, "photo.jpg", 800, null);
		expect(result).toBeNull();
		expect(mockStoreMedia).not.toHaveBeenCalled();
	});

	it("stores the thumbnail with filename=<basename>-thumb.webp and mimeType=image/webp, merging the input object", async () => {
		sharpInstance.toBuffer.mockResolvedValue(Buffer.from([0x22]));
		mockStoreMedia.mockResolvedValue({
			ok: true,
			asset: { publicPath: "/p/photo-thumb.webp" },
		});
		await generateAndStoreThumbnail(input, "photo.jpg", 800, null);
		expect(mockStoreMedia).toHaveBeenCalledTimes(1);
		const [arg, localsArg] = mockStoreMedia.mock.calls[0];
		expect(arg).toMatchObject({
			filename: "photo-thumb.webp",
			mimeType: "image/webp",
			title: "Photo",
			altText: "alt",
		});
		expect(arg.bytes).toBeInstanceOf(Uint8Array);
		expect(Array.from(arg.bytes as Uint8Array)).toEqual([0x22]);
		expect(localsArg).toBeNull();
	});

	it("appends -thumb.webp without splitting on dot for filenames lacking an extension", async () => {
		sharpInstance.toBuffer.mockResolvedValue(Buffer.from([0x33]));
		mockStoreMedia.mockResolvedValue({
			ok: true,
			asset: { publicPath: "/p/noext-thumb.webp" },
		});
		await generateAndStoreThumbnail(input, "noext", 800, null);
		expect(mockStoreMedia.mock.calls[0][0]).toMatchObject({
			filename: "noext-thumb.webp",
		});
	});

	it("treats a leading-dot filename (dot at index 0) as having no extension", async () => {
		// lastIndexOf(".") === 0 → `dot > 0` is false → basename is the whole filename
		sharpInstance.toBuffer.mockResolvedValue(Buffer.from([0x44]));
		mockStoreMedia.mockResolvedValue({
			ok: true,
			asset: { publicPath: "/p/.hidden-thumb.webp" },
		});
		await generateAndStoreThumbnail(input, ".hidden", 800, null);
		expect(mockStoreMedia.mock.calls[0][0]).toMatchObject({
			filename: ".hidden-thumb.webp",
		});
	});

	it("returns null (not the asset path) when thumbnail storage fails", async () => {
		sharpInstance.toBuffer.mockResolvedValue(Buffer.from([0x55]));
		mockStoreMedia.mockResolvedValue({ ok: false, error: "boom" });
		const result = await generateAndStoreThumbnail(input, "photo.jpg", 800, null);
		expect(result).toBeNull();
	});
});

describe("generateAndStoreSrcset", () => {
	const input = {
		filename: "photo.jpg",
		bytes: new Uint8Array([0xff, 0xd8]),
		mimeType: "image/jpeg",
		title: "Photo",
		altText: "alt",
	};

	it("invokes generateSrcset with (bytes, publicPath, callback) and returns its result", async () => {
		mockGenerateSrcset.mockResolvedValue("/p/photo-400w.webp 400w");
		const result = await generateAndStoreSrcset(input, "/p/photo.jpg", null);
		expect(mockGenerateSrcset).toHaveBeenCalledTimes(1);
		const [bytesArg, pathArg, cb] = mockGenerateSrcset.mock.calls[0];
		expect(bytesArg).toBe(input.bytes);
		expect(pathArg).toBe("/p/photo.jpg");
		expect(typeof cb).toBe("function");
		expect(result).toBe("/p/photo-400w.webp 400w");
	});

	it("callback forwards (filename, bytes) to storeRuntimeMediaObject with mimeType image/webp, merging the input", async () => {
		mockStoreMedia.mockResolvedValue({
			ok: true,
			asset: { publicPath: "/p/photo-400w.webp" },
		});
		mockGenerateSrcset.mockImplementation(
			async (
				_bytes: Uint8Array,
				_path: string,
				cb: (f: string, b: Uint8Array) => Promise<string | null>,
			) => cb("photo-400w.webp", new Uint8Array([0x66])),
		);
		const result = await generateAndStoreSrcset(input, "/p/photo.jpg", null);
		expect(result).toBe("/p/photo-400w.webp");
		const [arg] = mockStoreMedia.mock.calls[0];
		expect(arg).toMatchObject({
			filename: "photo-400w.webp",
			mimeType: "image/webp",
			title: "Photo",
			altText: "alt",
		});
		expect(Array.from(arg.bytes as Uint8Array)).toEqual([0x66]);
	});

	it("callback returns null when variant storage fails", async () => {
		mockStoreMedia.mockResolvedValue({ ok: false, error: "nope" });
		let callbackResult: string | null = "unset";
		mockGenerateSrcset.mockImplementation(
			async (
				_bytes: Uint8Array,
				_path: string,
				cb: (f: string, b: Uint8Array) => Promise<string | null>,
			) => {
				callbackResult = await cb("photo-400w.webp", new Uint8Array([0x77]));
				return null;
			},
		);
		await generateAndStoreSrcset(input, "/p/photo.jpg", null);
		expect(callbackResult).toBeNull();
	});
});

describe("detectImageDimensionsForMime", () => {
	it("returns null without invoking image-size for non-image mimeTypes", async () => {
		const result = await detectImageDimensionsForMime(new Uint8Array([1, 2]), "application/pdf");
		expect(result).toBeNull();
		expect(mockImageSize).not.toHaveBeenCalled();
	});

	it("delegates to detectImageDimensions when the mime begins with image/", async () => {
		mockImageSize.mockReturnValue({ width: 10, height: 20 });
		const result = await detectImageDimensionsForMime(new Uint8Array([1, 2]), "image/png");
		expect(result).toEqual({ width: 10, height: 20 });
		expect(mockImageSize).toHaveBeenCalledTimes(1);
	});

	it("returns null for the empty mimeType (does not blindly call image-size)", async () => {
		const result = await detectImageDimensionsForMime(new Uint8Array([1, 2]), "");
		expect(result).toBeNull();
		expect(mockImageSize).not.toHaveBeenCalled();
	});
});

tests/wordpress-import.contract.test.ts.source:
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";

import { describe, expect, it, vi } from "vitest";
import { createAstropressWordPressImportSource } from "../src/import/wordpress.js";

// SVG passes through downloadMedia without sharp transcoding, so no real
// image data is needed — the contract test verifies pipeline flow, not format.
const SVG_BYTES = new TextEncoder().encode("<svg xmlns='http://www.w3.org/2000/svg'/>");

describe("wordpress import contract", () => {
	it("parses WXR content into staged import artifacts and redirects", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(async (url: string) => {
				if (typeof url === "string" && url.startsWith("https://example.org/")) {
					return new Response(SVG_BYTES, {
						status: 200,
						headers: { "content-type": "image/svg+xml" },
					});
				}
				throw new Error(`Unexpected fetch in test: ${url}`);
			}),
		);
		const workspace = await mkdtemp(join(tmpdir(), "astropress-wordpress-import-"));
		const artifactDir = join(workspace, "artifacts");
		const exportFile = join(workspace, "export.xml");
		await writeFile(
			exportFile,
			[
				"<rss>",
				"<channel>",
				"<wp:author>",
				"<wp:author_id>7</wp:author_id>",
				"<wp:author_login><![CDATA[admin]]></wp:author_login>",
				"<wp:author_email><![CDATA[admin@example.org]]></wp:author_email>",
				"<wp:author_display_name><![CDATA[Admin Person]]></wp:author_display_name>",
				"</wp:author>",
				"<item>",
				"<title><![CDATA[Hello World]]></title>",
				"<link>https://example.org/blog/hello-world/</link>",
				'<content:encoded><![CDATA[<p>Intro</p>[gallery ids="1,2"]]]></content:encoded>',
				"<excerpt:encoded><![CDATA[A short summary]]></excerpt:encoded>",
				"<wp:post_id>101</wp:post_id>",
				"<wp:post_date>2024-01-01 12:00:00</wp:post_date>",
				"<wp:post_name>hello-world</wp:post_name>",
				"<wp:status>publish</wp:status>",
				"<wp:post_type>post</wp:post_type>",
				'<category domain="category" nicename="news"><![CDATA[News]]></category>',
				'<category domain="post_tag" nicename="featured"><![CDATA[Featured]]></category>',
				"<wp:postmeta><wp:meta_key>_wp_old_slug</wp:meta_key><wp:meta_value>hello-old</wp:meta_value></wp:postmeta>",
				"<wp:comment><wp:comment_id>1</wp:comment_id><wp:comment_author><![CDATA[Pat Reader]]></wp:comment_author><wp:comment_author_email><![CDATA[pat@example.org]]></wp:comment_author_email><wp:comment_date>2024-01-02 10:00:00</wp:comment_date><wp:comment_approved>1</wp:comment_approved><wp:comment_content><![CDATA[Nice post]]></wp:comment_content></wp:comment>",
				"</item>",
				"<item>",
				"<title><![CDATA[About]]></title>",
				"<link>https://example.org/about/</link>",
				"<content:encoded><![CDATA[<p>About us</p>]]></content:encoded>",
				"<wp:post_id>102</wp:post_id>",
				"<wp:post_name>about</wp:post_name>",
				"<wp:status>draft</wp:status>",
				"<wp:post_type>page</wp:post_type>",
				"</item>",
				"<item>",
				"<title><![CDATA[Hero Image]]></title>",
				"<link>https://example.org/wp-content/uploads/2024/01/hero.png</link>",
				"<wp:post_id>201</wp:post_id>",
				"<wp:post_name>hero-image</wp:post_name>",
				"<wp:status>inherit</wp:status>",
				"<wp:post_type>attachment</wp:post_type>",
				"<wp:post_parent>101</wp:post_parent>",
				"<wp:attachment_url>https://example.org/wp-content/uploads/2024/01/hero.png</wp:attachment_url>",
				"</item>",
				"</channel>",
				"</rss>",
			].join(""),
			"utf8",
		);

		const importer = createAstropressWordPressImportSource();
		const inventory = await importer.inspectWordPress?.({ exportFile });
		const plan = await importer.planWordPressImport?.({
			inventory: inventory as NonNullable<typeof inventory>,
			downloadMedia: true,
			artifactDir,
		});
		const report = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: true,
			plan,
		});

		expect(inventory).toMatchObject({
			exportFile,
			detectedRecords: 3,
			detectedMedia: 1,
			detectedComments: 1,
			detectedUsers: 1,
			detectedShortcodes: 1,
			entityCounts: {
				posts: 1,
				pages: 1,
				attachments: 1,
				redirects: 1,
				comments: 1,
				users: 1,
				categories: 1,
				tags: 1,
			},
			remediationCandidates: ["post-101"],
		});
		expect(plan).toMatchObject({
			artifactDir,
			downloadMedia: true,
			resumeSupported: true,
			permalinkStrategy: "preserve-wordpress-links",
			entityCounts: {
				redirects: 1,
			},
		});
		expect(report).toMatchObject({
			status: "completed_with_warnings",
			importedRecords: 2,
			importedMedia: 1,
			importedComments: 1,
			importedUsers: 1,
			importedRedirects: 1,
			downloadedMedia: 1,
			artifacts: {
				artifactDir,
			},
		});

		const contentRecords = JSON.parse(
			await readFile(join(artifactDir, "content-records.json"), "utf8"),
		) as Record<string, unknown>[];
		const redirectRecords = JSON.parse(
			await readFile(join(artifactDir, "redirect-records.json"), "utf8"),
		) as Record<string, unknown>[];
		const mediaManifest = JSON.parse(
			await readFile(join(artifactDir, "media-manifest.json"), "utf8"),
		) as Record<string, unknown>[];
		const downloadState = JSON.parse(
			await readFile(join(artifactDir, "download-state.json"), "utf8"),
		) as { completed: string[]; failed: unknown[] };

		expect(contentRecords).toHaveLength(2);
		expect(contentRecords[0]).toMatchObject({
			id: "post-101",
			slug: "hello-world",
			legacyUrl: "/blog/hello-world/",
			categorySlugs: ["news"],
			tagSlugs: ["featured"],
		});
		expect(redirectRecords).toEqual([
			expect.objectContaining({
				sourcePath: "/blog/hello-old/",
				targetPath: "/blog/hello-world/",
			}),
		]);
		expect(mediaManifest).toEqual([
			expect.objectContaining({
				id: "media-201",
				parentLegacyId: "101",
			}),
		]);
		expect(downloadState.completed).toContain("media-201");
		expect(downloadState.failed).toEqual([]);

		const importReport = JSON.parse(
			await readFile(join(artifactDir, "import-report.json"), "utf8"),
		) as Record<string, unknown>;
		expect(importReport).toMatchObject({
			counts: { posts: 1 },
			mediaErrors: [],
		});
		expect(
			importReport.status === "completed" || importReport.status === "completed_with_warnings",
		).toBe(true);

		const resumed = await importer.resumeWordPressImport?.({
			exportFile,
			artifactDir,
			downloadMedia: true,
		});
		expect(resumed?.downloadedMedia).toBe(0);
		expect(resumed?.artifacts?.downloadStateFile).toBe(join(artifactDir, "download-state.json"));

		await rm(workspace, { recursive: true, force: true });
		vi.unstubAllGlobals();
	});

	it("can apply staged imports into the local sqlite runtime idempotently", {
		timeout: 60_000,
	}, async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-wordpress-apply-"));
		const artifactDir = join(workspace, "artifacts");
		const adminDbPath = join(workspace, ".data", "admin.sqlite");
		const exportFile = join(workspace, "export.xml");
		await writeFile(
			exportFile,
			[
				"<rss>",
				"<channel>",
				"<wp:author><wp:author_id>7</wp:author_id><wp:author_login><![CDATA[admin]]></wp:author_login><wp:author_display_name><![CDATA[Admin Person]]></wp:author_display_name></wp:author>",
				'<item><title><![CDATA[Hello World]]></title><link>https://example.org/blog/hello-world/</link><content:encoded><![CDATA[<p>Intro</p>]]></content:encoded><excerpt:encoded><![CDATA[A short summary]]></excerpt:encoded><wp:post_id>101</wp:post_id><wp:post_name>hello-world</wp:post_name><wp:status>publish</wp:status><wp:post_type>post</wp:post_type><category domain="category" nicename="news"><![CDATA[News]]></category><category domain="post_tag" nicename="featured"><![CDATA[Featured]]></category><wp:postmeta><wp:meta_key>_wp_old_slug</wp:meta_key><wp:meta_value>hello-old</wp:meta_value></wp:postmeta><wp:comment><wp:comment_id>1</wp:comment_id><wp:comment_author><![CDATA[Pat Reader]]></wp:comment_author><wp:comment_content><![CDATA[Nice post]]></wp:comment_content><wp:comment_approved>1</wp:comment_approved></wp:comment></item>',
				"<item><title><![CDATA[Hero Image]]></title><link>https://example.org/wp-content/uploads/2024/01/hero.png</link><wp:post_id>201</wp:post_id><wp:post_name>hero-image</wp:post_name><wp:status>inherit</wp:status><wp:post_type>attachment</wp:post_type><wp:post_parent>101</wp:post_parent><wp:attachment_url>https://example.org/wp-content/uploads/2024/01/hero.png</wp:attachment_url></item>",
				"</channel>",
				"</rss>",
			].join(""),
			"utf8",
		);

		const importer = createAstropressWordPressImportSource();
		const first = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: true,
			applyLocal: true,
			workspaceRoot: workspace,
			adminDbPath,
		});
		const second = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: true,
			applyLocal: true,
			workspaceRoot: workspace,
			adminDbPath,
		});

		expect(first.localApply).toMatchObject({
			runtime: "sqlite-local",
			adminDbPath,
			appliedRecords: 1,
			appliedMedia: 1,
			appliedComments: 1,
			appliedUsers: 1,
			appliedRedirects: 1,
		});
		expect(second.localApply?.adminDbPath).toBe(adminDbPath);
		expect(first.artifacts?.localApplyReportFile).toBe(
			join(artifactDir, "wordpress.local-apply.json"),
		);

		const db = new DatabaseSync(adminDbPath);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM content_entries").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM authors WHERE deleted_at IS NULL").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM categories WHERE deleted_at IS NULL").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM tags WHERE deleted_at IS NULL").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM comments").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM media_assets WHERE deleted_at IS NULL").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db
					.prepare("SELECT COUNT(*) AS count FROM redirect_rules WHERE deleted_at IS NULL")
					.get() as { count: number }
			).count,
		).toBe(1);
		db.close();

		await rm(workspace, { recursive: true, force: true });
	});

	it("skips local apply when applyLocal is false", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-wordpress-noapply-"));
		const artifactDir = join(workspace, "artifacts");
		const exportFile = join(workspace, "export.xml");
		await writeFile(
			exportFile,
			[
				"<rss><channel>",
				"<item><title><![CDATA[Hello]]></title><link>https://example.org/blog/hello/</link><content:encoded><![CDATA[<p>Hi</p>]]></content:encoded><wp:post_id>1</wp:post_id><wp:post_name>hello</wp:post_name><wp:status>publish</wp:status><wp:post_type>post</wp:post_type></item>",
				"</channel></rss>",
			].join(""),
			"utf8",
		);

		const importer = createAstropressWordPressImportSource();
		const report = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: false,
			applyLocal: false,
		});

		// localApply must be undefined when applyLocal: false
		expect(report.localApply).toBeUndefined();
		expect(report.importedRecords).toBe(1);

		await rm(workspace, { recursive: true, force: true });
	});
});

