import { describe, expect, it } from "vitest";
import {
	cloudflareActorEmail,
	FULL_STACK_CAPABILITIES,
	listTranslationRecords,
	mapContentRecordKind,
	normalizeContentStatus,
	nowIso,
	saveD1Revision,
	toContentStoreRecord,
	toRedirectRecord,
	toTranslationRecord,
} from "../../src/adapters/adapter-record-helpers";
import { makeDb } from "../helpers/make-db.js";
import { SqliteBackedD1Database } from "../helpers/provider-test-fixtures.js";

describe("FULL_STACK_CAPABILITIES", () => {
	it("declares every full-stack capability as true", () => {
		expect(FULL_STACK_CAPABILITIES).toEqual({
			hostedAdmin: true,
			previewEnvironments: true,
			serverRuntime: true,
			database: true,
			objectStorage: true,
			gitSync: true,
		});
	});
});

describe("mapContentRecordKind", () => {
	it("returns 'post' only when kind is exactly 'post'", () => {
		expect(mapContentRecordKind({ kind: "post" })).toBe("post");
	});

	it("returns 'page' for any non-'post' kind including null/undefined/page", () => {
		expect(mapContentRecordKind({ kind: "page" })).toBe("page");
		expect(mapContentRecordKind({ kind: null })).toBe("page");
		expect(mapContentRecordKind({})).toBe("page");
		expect(mapContentRecordKind({ kind: "POST" })).toBe("page");
	});
});

describe("nowIso", () => {
	it("returns a parseable ISO-8601 timestamp at the current moment", () => {
		const before = Date.now();
		const result = nowIso();
		const after = Date.now();
		expect(typeof result).toBe("string");
		const parsed = Date.parse(result);
		expect(Number.isFinite(parsed)).toBe(true);
		expect(parsed).toBeGreaterThanOrEqual(before);
		expect(parsed).toBeLessThanOrEqual(after);
		// Must include the "T" separator and the trailing "Z"
		expect(result).toMatch(/^\d{4}-\d{2}-\d{2}T.+Z$/);
	});
});

describe("cloudflareActorEmail", () => {
	it("returns the exact admin@example.com placeholder", () => {
		expect(cloudflareActorEmail()).toBe("admin@example.com");
	});
});

describe("normalizeContentStatus", () => {
	it("returns 'published' / 'draft' / 'archived' unchanged", () => {
		expect(normalizeContentStatus("published")).toBe("published");
		expect(normalizeContentStatus("draft")).toBe("draft");
		expect(normalizeContentStatus("archived")).toBe("archived");
	});

	it("collapses commons 'review' to 'draft' (the adapter status type excludes review)", () => {
		// Force the commons normalizer to return 'review' by passing the literal.
		expect(
			normalizeContentStatus("review" as unknown as Parameters<typeof normalizeContentStatus>[0]),
		).toBe("draft");
	});

	it("falls through commons default for unknown statuses, then collapses to draft", () => {
		expect(
			normalizeContentStatus("unknown" as unknown as Parameters<typeof normalizeContentStatus>[0]),
		).not.toBe("review");
	});
});

describe("toTranslationRecord", () => {
	it("maps state='published' to status 'published'", () => {
		const r = toTranslationRecord("/es/about", "published", "2025-01-01T00:00:00Z", "alice");
		expect(r).toEqual({
			id: "/es/about",
			kind: "translation",
			slug: "/es/about",
			status: "published",
			title: "/es/about",
			metadata: { state: "published", updatedAt: "2025-01-01T00:00:00Z", updatedBy: "alice" },
		});
	});

	it("maps any non-'published' state to status 'draft'", () => {
		expect(
			toTranslationRecord("/es/x", "not_started", "2025-01-01T00:00:00Z", "alice").status,
		).toBe("draft");
		expect(toTranslationRecord("/es/x", "reviewed", "2025-01-01T00:00:00Z", "alice").status).toBe(
			"draft",
		);
		expect(toTranslationRecord("/es/x", "", "2025-01-01T00:00:00Z", "alice").status).toBe("draft");
	});

	it("uses route as both id, slug, and title", () => {
		const r = toTranslationRecord("/path", "draft", "t", "u");
		expect(r.id).toBe("/path");
		expect(r.slug).toBe("/path");
		expect(r.title).toBe("/path");
	});

	it("packs state, updatedAt, and updatedBy verbatim into metadata", () => {
		const r = toTranslationRecord("/p", "partial", "2025-06-01T12:00:00Z", "bob@example.com");
		expect(r.metadata).toEqual({
			state: "partial",
			updatedAt: "2025-06-01T12:00:00Z",
			updatedBy: "bob@example.com",
		});
	});
});

describe("listTranslationRecords", () => {
	it("reads translation_overrides rows and maps each through toTranslationRecord, ordered by route ASC", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		db.prepare(
			"INSERT INTO translation_overrides (route, state, updated_at, updated_by) VALUES (?, ?, ?, ?)",
		).run("/es/zebra", "draft", "2025-01-02T00:00:00Z", "alice");
		db.prepare(
			"INSERT INTO translation_overrides (route, state, updated_at, updated_by) VALUES (?, ?, ?, ?)",
		).run("/es/apple", "published", "2025-01-01T00:00:00Z", "bob");

		const rows = await listTranslationRecords(d1);
		expect(rows).toHaveLength(2);
		expect(rows[0]).toEqual({
			id: "/es/apple",
			kind: "translation",
			slug: "/es/apple",
			status: "published",
			title: "/es/apple",
			metadata: { state: "published", updatedAt: "2025-01-01T00:00:00Z", updatedBy: "bob" },
		});
		expect(rows[1].id).toBe("/es/zebra");
		expect(rows[1].status).toBe("draft");
	});

	it("returns [] when the translation_overrides table is empty", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		const rows = await listTranslationRecords(d1);
		expect(rows).toEqual([]);
	});
});

describe("toContentStoreRecord re-export", () => {
	it("forwards to the commons mapper (smoke check)", () => {
		const r = toContentStoreRecord({
			id: "x",
			slug: "x",
			kind: "post",
			status: "published",
			title: "T",
		});
		expect(r.id).toBe("x");
		expect(r.kind).toBe("post");
	});
});

describe("toRedirectRecord re-export", () => {
	it("forwards to the commons mapper (smoke check)", () => {
		const r = toRedirectRecord({
			source_path: "/old",
			destination_path: "/new",
			status_code: 301,
			active: 1,
		});
		expect(r).toBeTruthy();
	});
});

function seedParent(db: ReturnType<typeof makeDb>, slug: string) {
	db.prepare(
		`INSERT INTO content_overrides (slug, title, status, updated_by) VALUES (?, ?, ?, ?)`,
	).run(slug, slug, "draft", "seed@test.local");
}

describe("saveD1Revision", () => {
	it("inserts a row with source='reviewed' and persists every snapshot field", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		seedParent(db, "hello-world");
		await saveD1Revision(
			d1,
			{
				id: "rev-1",
				recordId: "hello-world",
				createdAt: "2025-01-01T00:00:00Z",
				actorId: "alice@example.com",
				summary: "first revision",
				snapshot: {
					title: "Snap Title",
					status: "published",
					scheduledAt: "2025-02-01T00:00:00Z",
					body: "<p>body</p>",
					seoTitle: "Snap SEO",
					metaDescription: "Snap Meta",
					excerpt: "snippet",
					ogTitle: "OG T",
					ogDescription: "OG D",
					ogImage: "https://example.com/og.png",
					authorIds: [1, 2],
					categoryIds: [3],
					tagIds: [],
					canonicalUrlOverride: "https://example.com/c",
					robotsDirective: "noindex",
				},
			},
			"fallback@example.com",
		);

		const row = db
			.prepare(
				"SELECT id, slug, source, title, status, scheduled_at, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, author_ids, category_ids, tag_ids, canonical_url_override, robots_directive, revision_note, created_at, created_by FROM content_revisions WHERE id = 'rev-1'",
			)
			.get() as Record<string, unknown>;
		expect(row.source).toBe("reviewed");
		expect(row.slug).toBe("hello-world");
		expect(row.title).toBe("Snap Title");
		expect(row.status).toBe("published");
		expect(row.scheduled_at).toBe("2025-02-01T00:00:00Z");
		expect(row.body).toBe("<p>body</p>");
		expect(row.seo_title).toBe("Snap SEO");
		expect(row.meta_description).toBe("Snap Meta");
		expect(row.excerpt).toBe("snippet");
		expect(row.og_title).toBe("OG T");
		expect(row.og_description).toBe("OG D");
		expect(row.og_image).toBe("https://example.com/og.png");
		expect(JSON.parse(row.author_ids as string)).toEqual([1, 2]);
		expect(JSON.parse(row.category_ids as string)).toEqual([3]);
		expect(JSON.parse(row.tag_ids as string)).toEqual([]);
		expect(row.canonical_url_override).toBe("https://example.com/c");
		expect(row.robots_directive).toBe("noindex");
		expect(row.revision_note).toBe("first revision");
		expect(row.created_at).toBe("2025-01-01T00:00:00Z");
		expect(row.created_by).toBe("alice@example.com");
	});

	it("falls back to actorEmail when revision.actorId is null/undefined", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		seedParent(db, "hello-world");
		await saveD1Revision(
			d1,
			{
				id: "rev-2",
				recordId: "hello-world",
				createdAt: "2025-01-01T00:00:00Z",
				actorId: null,
				summary: null,
				snapshot: { title: "T", status: "draft" },
			},
			"fallback@example.com",
		);
		const row = db
			.prepare("SELECT created_by, revision_note FROM content_revisions WHERE id = 'rev-2'")
			.get() as { created_by: string; revision_note: string | null };
		expect(row.created_by).toBe("fallback@example.com");
		expect(row.revision_note).toBeNull();
	});

	it("falls back title/seoTitle/metaDescription to recordId when snapshot lacks them", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		seedParent(db, "bare-record");
		await saveD1Revision(
			d1,
			{
				id: "rev-3",
				recordId: "bare-record",
				createdAt: "2025-01-01T00:00:00Z",
				snapshot: { status: "draft" },
			},
			"fallback@example.com",
		);
		const row = db
			.prepare(
				"SELECT title, seo_title, meta_description FROM content_revisions WHERE id = 'rev-3'",
			)
			.get() as { title: string; seo_title: string; meta_description: string };
		expect(row.title).toBe("bare-record");
		expect(row.seo_title).toBe("bare-record");
		expect(row.meta_description).toBe("bare-record");
	});

	it("uses snapshot.title as the seoTitle/metaDescription fallback when those fields are absent", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		seedParent(db, "rid");
		await saveD1Revision(
			d1,
			{
				id: "rev-4",
				recordId: "rid",
				createdAt: "2025-01-01T00:00:00Z",
				snapshot: { title: "Snap T", status: "draft" },
			},
			"fallback@example.com",
		);
		const row = db
			.prepare("SELECT seo_title, meta_description FROM content_revisions WHERE id = 'rev-4'")
			.get() as { seo_title: string; meta_description: string };
		expect(row.seo_title).toBe("Snap T");
		expect(row.meta_description).toBe("Snap T");
	});

	it("serializes missing authorIds/categoryIds/tagIds as JSON '[]'", async () => {
		const db = makeDb();
		const d1 = new SqliteBackedD1Database(db);
		seedParent(db, "rid");
		await saveD1Revision(
			d1,
			{
				id: "rev-5",
				recordId: "rid",
				createdAt: "2025-01-01T00:00:00Z",
				snapshot: { title: "T", status: "draft" },
			},
			"fallback@example.com",
		);
		const row = db
			.prepare("SELECT author_ids, category_ids, tag_ids FROM content_revisions WHERE id = 'rev-5'")
			.get() as { author_ids: string; category_ids: string; tag_ids: string };
		expect(row.author_ids).toBe("[]");
		expect(row.category_ids).toBe("[]");
		expect(row.tag_ids).toBe("[]");
	});
});

tests/webhook-store.test.ts.source:
import { describe, expect, it, vi } from "vitest";

import { verifyMlDsaMessage } from "../src/crypto-primitives.js";
import type { WebhookEvent, WebhookRecord, WebhookStore } from "../src/platform-contracts";
import { createWebhookStore } from "../src/sqlite-runtime/webhooks.js";
import { makeDb } from "./helpers/make-db.js";

const { loggerErrorSpy } = vi.hoisted(() => ({ loggerErrorSpy: vi.fn() }));

vi.mock("../src/runtime-logger", () => ({
	createLogger: () => ({
		info: vi.fn(),
		warn: vi.fn(),
		error: loggerErrorSpy,
	}),
}));

describe("WebhookRecord shape", () => {
	it("has all required fields", () => {
		const record: WebhookRecord = {
			id: "wh_01",
			url: "https://example.com/hook",
			events: ["content.published"],
			active: true,
			createdAt: new Date().toISOString(),
		};

		expect(record.id).toBe("wh_01");
		expect(record.url).toBe("https://example.com/hook");
		expect(record.active).toBe(true);
		expect(record.lastFiredAt).toBeUndefined();
	});

	it("supports all defined webhook events", () => {
		const allEvents: WebhookEvent[] = [
			"content.published",
			"content.updated",
			"content.deleted",
			"media.uploaded",
			"media.deleted",
		];
		const record: WebhookRecord = {
			id: "wh_02",
			url: "https://example.com/hook",
			events: allEvents,
			active: true,
			createdAt: new Date().toISOString(),
		};
		expect(record.events).toHaveLength(5);
	});
});

describe("WebhookStore SQLite implementation", () => {
	it("create: returns a one-time ML-DSA verification bundle", async () => {
		const db = makeDb();
		const store = createWebhookStore(db, fetch);

		const { record, verification } = await store.create({
			url: "https://example.com/hook",
			events: ["content.published"],
		});

		expect(verification.algorithm).toBe("ML-DSA-65");
		expect(verification.keyId).toBe(record.id);
		expect(verification.publicKey.length).toBeGreaterThan(100);
		expect(record.url).toBe("https://example.com/hook");
		expect(record.events).toEqual(["content.published"]);
		expect(record.active).toBe(true);

		// The private signing key is stored server-side; the public key is returned once.
		const row = db.prepare("SELECT secret_hash FROM webhooks WHERE id = ?").get(record.id) as {
			secret_hash: string;
		};
		expect(row.secret_hash).not.toBe(verification.publicKey);
	});

	it("list: returns only active (non-deleted) webhooks", async () => {
		const db = makeDb();
		const store = createWebhookStore(db, fetch);

		const { record: r1 } = await store.create({
			url: "https://a.com/hook",
			events: ["content.published"],
		});
		const { record: r2 } = await store.create({
			url: "https://b.com/hook",
			events: ["media.uploaded"],
		});
		await store.delete(r1.id);

		const active = await store.list();
		expect(active.some((w) => w.id === r2.id)).toBe(true);
		expect(active.some((w) => w.id === r1.id)).toBe(false);
	});

	it("delete: soft-deletes so the webhook is gone from list", async () => {
		const db = makeDb();
		const store = createWebhookStore(db, fetch);
		const { record } = await store.create({
			url: "https://c.com/hook",
			events: ["content.deleted"],
		});

		await store.delete(record.id);

		const row = db.prepare("SELECT deleted_at FROM webhooks WHERE id = ?").get(record.id) as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();
	});

	it("dispatch: sends POST with ML-DSA-65 signature headers", async () => {
		const db = makeDb();
		let capturedRequest: Request | undefined;
		const mockFetch = async (req: Request) => {
			capturedRequest = req;
			return new Response("ok", { status: 200 });
		};

		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record, verification } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		const payload = { id: "post-1", status: "published" };
		await store.dispatch("content.published", payload);

		expect(capturedRequest).toBeDefined();
		expect(capturedRequest?.method).toBe("POST");

		const sig = capturedRequest?.headers.get("x-astropress-signature");
		expect(sig).toBeTruthy();
		expect(capturedRequest?.headers.get("x-astropress-signature-alg")).toBe("ML-DSA-65");
		expect(capturedRequest?.headers.get("x-astropress-key-id")).toBe(record.id);

		const body = await capturedRequest?.clone().text();
		expect(verifyMlDsaMessage(body, sig as string, verification.publicKey)).toBe(true);
	});

	it("dispatch: partial failure does not throw", async () => {
		const db = makeDb();
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			if (callCount === 1) throw new Error("Network error");
			return new Response("ok", { status: 200 });
		};

		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});
		await store.create({
			url: "https://ok.example.com/hook",
			events: ["content.updated"],
		});

		await expect(store.dispatch("content.updated", { test: true })).resolves.not.toThrow();
		expect(callCount).toBe(2);
	});

	it("dispatch: skips webhooks not subscribed to the event", async () => {
		const db = makeDb();
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			return new Response("ok", { status: 200 });
		};

		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://media.example.com/hook",
			events: ["media.uploaded"],
		});

		await store.dispatch("content.published", { id: "x" });
		expect(callCount).toBe(0);
	});
});

describe("WebhookStore mutation pins", () => {
	function insertWebhookRow(
		db: ReturnType<typeof makeDb>,
		row: { id: string; url: string; active: number },
	) {
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run(row.id, row.url, JSON.stringify(["content.published"]), "secret", row.active);
	}

	it("list: maps the active column to a boolean (kills L27 ConditionalExpression true/false & EqualityOperator)", async () => {
		// rowToRecord computes `active: row.active === 1`. Mutants that force the
		// result to true/false, or flip `===` to `!==`, are only observable when
		// list() returns both an active (1) and an inactive (0) non-deleted row.
		const db = makeDb();
		insertWebhookRow(db, { id: "wh_on", url: "https://on.example.com", active: 1 });
		insertWebhookRow(db, { id: "wh_off", url: "https://off.example.com", active: 0 });
		const store = createWebhookStore(db, fetch);

		const list = await store.list();
		expect(list.find((w) => w.id === "wh_on")?.active).toBe(true);
		expect(list.find((w) => w.id === "wh_off")?.active).toBe(false);
	});

	it("list: maps last_fired_at to lastFiredAt after a dispatch (kills L29 LogicalOperator ?? → &&)", async () => {
		// `lastFiredAt: row.last_fired_at ?? null`. With `&&` the mapping yields
		// null even when the column holds a timestamp.
		const db = makeDb();
		const mockFetch = async () => new Response("ok", { status: 200 });
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});
		await store.dispatch("content.published", { id: "x" });

		const listed = (await store.list()).find((w) => w.id === record.id);
		expect(typeof listed?.lastFiredAt).toBe("string");
		expect(listed?.lastFiredAt).toBeTruthy();
	});

	it("dispatch: request body carries the event, payload, and a timestamp (kills L87 ObjectLiteral {})", async () => {
		const db = makeDb();
		let capturedRequest: Request | undefined;
		const mockFetch = async (req: Request) => {
			capturedRequest = req;
			return new Response("ok", { status: 200 });
		};
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "post-7", status: "published" });

		const body = JSON.parse((await capturedRequest?.clone().text()) ?? "{}") as {
			event?: string;
			payload?: { id?: string; status?: string };
			timestamp?: string;
		};
		expect(body.event).toBe("content.published");
		expect(body.payload).toEqual({ id: "post-7", status: "published" });
		expect(typeof body.timestamp).toBe("string");
	});

	it("dispatch: sends an application/json Content-Type header (kills L102 StringLiteral '')", async () => {
		const db = makeDb();
		let capturedRequest: Request | undefined;
		const mockFetch = async (req: Request) => {
			capturedRequest = req;
			return new Response("ok", { status: 200 });
		};
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		expect(capturedRequest?.headers.get("content-type")).toBe("application/json");
	});

	it("dispatch: successful delivery records last_fired_at (kills L118 StringLiteral '')", async () => {
		const db = makeDb();
		const mockFetch = async () => new Response("ok", { status: 200 });
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).not.toBeNull();
	});

	it("dispatch: failed delivery leaves last_fired_at NULL and logs the error (kills L111 BlockStatement, L112 StringLiteral & ObjectLiteral)", async () => {
		// The catch block logs and `return`s before the last_fired_at UPDATE.
		// Emptying it (BlockStatement {}) would let the UPDATE run on a failed
		// delivery; blanking the log message or its meta object drops the error
		// context.
		loggerErrorSpy.mockClear();
		const db = makeDb();
		const mockFetch = async () => {
			throw new Error("Network error");
		};
		const store = createWebhookStore(db, mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});

		await store.dispatch("content.updated", { id: "x" });

		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).toBeNull();

		expect(loggerErrorSpy).toHaveBeenCalledTimes(1);
		const [message, meta] = loggerErrorSpy.mock.calls[0] as [string, { error?: unknown }];
		expect(message).toContain("content.updated");
		expect(message).toContain("https://fail.example.com/hook");
		expect(meta.error).toBeInstanceOf(Error);
	});
});

// Type-level smoke test
function assertWebhookStoreShape(store: WebhookStore) {
	const _list = store.list;
	const _create = store.create;
	const _delete = store.delete;
	const _dispatch = store.dispatch;
	return { _list, _create, _delete, _dispatch };
}

void assertWebhookStoreShape;

