import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";

import { describe, expect, it } from "vitest";

import {
	rollbackAstropressLastMigration,
	runAstropressDbMigrationsForCli,
} from "../src/db-migrate-ops.js";
import {
	ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE,
	checkSchemaVersionAhead,
	readAstropressSqliteSchemaSql,
	runAstropressMigrations,
} from "../src/sqlite-bootstrap.js";
import { makeDb } from "./helpers/make-db.js";

describe("db-migrate-ops", () => {
	function setupDb(dir: string): string {
		const dbPath = join(dir, "admin.sqlite");
		const db = new DatabaseSync(dbPath);
		db.exec(readAstropressSqliteSchemaSql());
		db.close();
		return dbPath;
	}

	it("applies migrations and returns applied/skipped lists", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-db-migrate-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_add_feature.sql"),
			"CREATE TABLE IF NOT EXISTS feature_flags (id INTEGER PRIMARY KEY);",
		);
		writeFileSync(
			join(migrationsDir, "0002_add_index.sql"),
			"CREATE INDEX IF NOT EXISTS idx_content_slug ON content_entries (slug);",
		);

		const dbPath = setupDb(dir);
		const report = runAstropressDbMigrationsForCli({ dbPath, migrationsDir });

		expect(report.applied).toEqual(["0001_add_feature.sql", "0002_add_index.sql"]);
		expect(report.skipped).toEqual([]);
		expect(report.dryRun).toBe(false);

		// Re-running skips already-applied migrations
		const report2 = runAstropressDbMigrationsForCli({ dbPath, migrationsDir });
		expect(report2.applied).toEqual([]);
		expect(report2.skipped).toEqual(["0001_add_feature.sql", "0002_add_index.sql"]);

		rmSync(dir, { recursive: true });
	});

	it("dry-run does not write to the real database", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-db-migrate-dry-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_dry.sql"),
			"CREATE TABLE IF NOT EXISTS dry_table (id INTEGER PRIMARY KEY);",
		);

		const dbPath = setupDb(dir);
		const report = runAstropressDbMigrationsForCli({
			dbPath,
			migrationsDir,
			dryRun: true,
		});

		expect(report.applied).toEqual(["0001_dry.sql"]);
		expect(report.dryRun).toBe(true);

		// Real DB should NOT have the migration recorded (dry-run uses in-memory DB)
		const db = new DatabaseSync(dbPath);
		const rows = db.prepare("SELECT name FROM schema_migrations WHERE name = '0001_dry.sql'").all();
		db.close();
		expect(rows).toHaveLength(0);

		rmSync(dir, { recursive: true });
	});

	it("returns empty applied/skipped when migrations directory does not exist", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-db-migrate-empty-"));
		const dbPath = setupDb(dir);
		const report = runAstropressDbMigrationsForCli({
			dbPath,
			migrationsDir: join(dir, "no-such-dir"),
		});

		expect(report.applied).toEqual([]);
		expect(report.skipped).toEqual([]);

		rmSync(dir, { recursive: true });
	});

	it("rollback_sql is stored with each migration when a .down.sql companion file exists", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-rollback-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_add_tags.sql"),
			"CREATE TABLE IF NOT EXISTS tags (id INTEGER PRIMARY KEY);",
		);
		writeFileSync(join(migrationsDir, "0001_add_tags.down.sql"), "DROP TABLE IF EXISTS tags;");

		const db = makeDb();
		runAstropressMigrations(db, migrationsDir);

		const row = db
			.prepare("SELECT rollback_sql FROM schema_migrations WHERE name = '0001_add_tags.sql'")
			.get() as { rollback_sql: string | null } | undefined;
		expect(row?.rollback_sql).toBe("DROP TABLE IF EXISTS tags;");

		rmSync(dir, { recursive: true });
	});

	it("rollback_sql is NULL when no .down.sql companion exists", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-no-rollback-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_add_flags.sql"),
			"CREATE TABLE IF NOT EXISTS feature_flags (id INTEGER PRIMARY KEY);",
		);

		const db = makeDb();
		runAstropressMigrations(db, migrationsDir);

		const row = db
			.prepare("SELECT rollback_sql FROM schema_migrations WHERE name = '0001_add_flags.sql'")
			.get() as { rollback_sql: string | null } | undefined;
		expect(row?.rollback_sql).toBeNull();

		rmSync(dir, { recursive: true });
	});

	it("rollbackAstropressLastMigration rolls back the last migration when rollback_sql exists", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-rollback-exec-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_add_rollback_table.sql"),
			"CREATE TABLE IF NOT EXISTS rollback_test (id INTEGER PRIMARY KEY);",
		);
		writeFileSync(
			join(migrationsDir, "0001_add_rollback_table.down.sql"),
			"DROP TABLE IF EXISTS rollback_test;",
		);

		const dbPath = setupDb(dir);
		runAstropressDbMigrationsForCli({ dbPath, migrationsDir });

		const report = rollbackAstropressLastMigration({ dbPath });
		expect(report.status).toBe("rolled_back");
		expect(report.migrationName).toBe("0001_add_rollback_table.sql");
		expect(report.dryRun).toBe(false);

		// Migration record should be gone
		const db = new DatabaseSync(dbPath);
		const rows = db
			.prepare("SELECT name FROM schema_migrations WHERE name = '0001_add_rollback_table.sql'")
			.all();
		db.close();
		expect(rows).toHaveLength(0);

		rmSync(dir, { recursive: true });
	});

	it("rollbackAstropressLastMigration returns no_rollback_sql when no .down.sql was stored", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-rollback-missing-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_no_down.sql"),
			"CREATE TABLE IF NOT EXISTS no_down_test (id INTEGER PRIMARY KEY);",
		);

		const dbPath = setupDb(dir);
		runAstropressDbMigrationsForCli({ dbPath, migrationsDir });

		const report = rollbackAstropressLastMigration({ dbPath });
		expect(report.status).toBe("no_rollback_sql");
		expect(report.migrationName).toBe("0001_no_down.sql");

		rmSync(dir, { recursive: true });
	});

	it("rollbackAstropressLastMigration returns no_migrations when no migrations have been applied", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-rollback-empty-"));
		const dbPath = setupDb(dir);

		const report = rollbackAstropressLastMigration({ dbPath });
		expect(report.status).toBe("no_migrations");
		expect(report.migrationName).toBeNull();

		rmSync(dir, { recursive: true });
	});

	it("rollbackAstropressLastMigration dry-run does not write changes", () => {
		const dir = mkdtempSync(join(tmpdir(), "astropress-rollback-dryrun-"));
		const migrationsDir = join(dir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_dryrun.sql"),
			"CREATE TABLE IF NOT EXISTS dry_rollback (id INTEGER PRIMARY KEY);",
		);
		writeFileSync(
			join(migrationsDir, "0001_dryrun.down.sql"),
			"DROP TABLE IF EXISTS dry_rollback;",
		);

		const dbPath = setupDb(dir);
		runAstropressDbMigrationsForCli({ dbPath, migrationsDir });

		const report = rollbackAstropressLastMigration({ dbPath, dryRun: true });
		expect(report.status).toBe("dry_run");
		expect(report.dryRun).toBe(true);

		// Migration record should still exist after dry-run
		const db = new DatabaseSync(dbPath);
		const rows = db
			.prepare("SELECT name FROM schema_migrations WHERE name = '0001_dryrun.sql'")
			.all();
		db.close();
		expect(rows).toHaveLength(1);

		rmSync(dir, { recursive: true });
	});

	it("checkSchemaVersionAhead returns isAhead=false for a fresh baseline-only DB", () => {
		const db = makeDb();
		// Fresh DB has 'baseline-schema' applied via applyCommittedSchema equivalent
		// For this test, insert the baseline entry manually
		db.prepare("INSERT OR IGNORE INTO schema_migrations (name) VALUES ('baseline-schema')").run();

		const result = checkSchemaVersionAhead(db, ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE);
		expect(result).not.toBeNull();
		expect(result?.isAhead).toBe(false);
		expect(result?.dbCount).toBe(1);
		expect(result?.frameworkCount).toBe(ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE);
	});

	it("checkSchemaVersionAhead returns isAhead=true when host app migrations are present", () => {
		const db = makeDb();
		db.prepare("INSERT OR IGNORE INTO schema_migrations (name) VALUES ('baseline-schema')").run();
		db.prepare("INSERT INTO schema_migrations (name) VALUES ('0001_host_migration.sql')").run();
		db.prepare("INSERT INTO schema_migrations (name) VALUES ('0002_host_migration.sql')").run();

		const result = checkSchemaVersionAhead(db, ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE);
		expect(result?.isAhead).toBe(true);
		expect(result?.dbCount).toBe(3);
		expect(result?.frameworkCount).toBe(1);
	});
});

tests/runtime-actions-taxonomies.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { registerCms } from "../src/config";
import {
	createRuntimeAuthor,
	createRuntimeCategory,
	createRuntimeTag,
	deleteRuntimeAuthor,
	deleteRuntimeCategory,
	deleteRuntimeTag,
	updateRuntimeAuthor,
	updateRuntimeCategory,
	updateRuntimeTag,
} from "../src/runtime-actions-taxonomies";
import { makeDb, STANDARD_ACTOR, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import { makeLocals } from "./helpers/make-locals.js";

const actor = STANDARD_ACTOR;

let db: DatabaseSync;
let locals: App.Locals;

interface AuditRow {
	action: string;
	resource_type: string;
	resource_id: string;
	summary: string;
}

function latestAudit(): AuditRow | undefined {
	return db
		.prepare(
			"SELECT action, resource_type, resource_id, summary FROM audit_events ORDER BY id DESC LIMIT 1",
		)
		.get() as AuditRow | undefined;
}

beforeEach(() => {
	db = makeDb();
	locals = makeLocals(db);
	registerCms(STANDARD_CMS_CONFIG);

	db.prepare("INSERT INTO authors (name, slug, bio) VALUES (?, ?, ?)").run(
		"Existing Author",
		"existing-author",
		"Bio",
	);
	db.prepare("INSERT INTO categories (name, slug) VALUES (?, ?)").run(
		"Existing Cat",
		"existing-cat",
	);
	db.prepare("INSERT INTO tags (name, slug) VALUES (?, ?)").run("Existing Tag", "existing-tag");
});

describe("createRuntimeAuthor", () => {
	it("creates an author and records audit with trimmed summary", async () => {
		const result = await createRuntimeAuthor({ name: "  New Author  " }, actor, locals);
		expect(result).toMatchObject({ ok: true });
		const row = db.prepare("SELECT name FROM authors WHERE slug = 'new-author'").get() as
			| { name: string }
			| undefined;
		expect(row?.name).toBe("New Author");
		expect(latestAudit()).toMatchObject({
			action: "author.create",
			resource_type: "content",
			resource_id: "  New Author  ",
			summary: "Created author New Author.",
		});
	});

	it("uses input.slug as resource_id when provided (?? left branch)", async () => {
		await createRuntimeAuthor({ name: "Display", slug: "explicit-slug" }, actor, locals);
		expect(latestAudit()?.resource_id).toBe("explicit-slug");
	});

	it("rejects duplicate slug and skips audit", async () => {
		const result = await createRuntimeAuthor({ name: "Existing Author" }, actor, locals);
		expect(result).toMatchObject({ ok: false });
		expect(latestAudit()).toBeUndefined();
	});

	it("rejects empty name and skips audit", async () => {
		const result = await createRuntimeAuthor({ name: "   " }, actor, locals);
		expect(result).toMatchObject({ ok: false });
		expect(latestAudit()).toBeUndefined();
	});
});

describe("updateRuntimeAuthor", () => {
	it("updates name and bio and records audit", async () => {
		const { lastInsertRowid: id } = db
			.prepare("INSERT INTO authors (name, slug) VALUES (?, ?)")
			.run("Old", "old-author");
		const result = await updateRuntimeAuthor(
			{ id: Number(id), name: "  New Name  ", bio: "New bio" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: true });
		const row = db.prepare("SELECT name, bio FROM authors WHERE id = ?").get(Number(id)) as {
			name: string;
			bio: string;
		};
		expect(row.name).toBe("New Name");
		expect(latestAudit()).toMatchObject({
			action: "author.update",
			resource_type: "content",
			resource_id: String(id),
			summary: "Updated author New Name.",
		});
	});

	it("rejects empty name and skips audit", async () => {
		const result = await updateRuntimeAuthor({ id: 1, name: "  " }, actor, locals);
		expect(result).toMatchObject({ ok: false });
		expect(latestAudit()).toBeUndefined();
	});
});

describe("deleteRuntimeAuthor", () => {
	it("soft-deletes an author and records audit unconditionally", async () => {
		const { lastInsertRowid: id } = db
			.prepare("INSERT INTO authors (name, slug) VALUES (?, ?)")
			.run("To Delete", "to-delete");
		const result = await deleteRuntimeAuthor(Number(id), actor, locals);
		expect(result).toMatchObject({ ok: true });
		const row = db.prepare("SELECT deleted_at FROM authors WHERE id = ?").get(Number(id)) as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();
		expect(latestAudit()).toMatchObject({
			action: "author.delete",
			resource_type: "content",
			resource_id: String(id),
			summary: `Deleted author ${id}.`,
		});
	});
});

describe("createRuntimeCategory", () => {
	it("creates a category and records audit with trimmed summary", async () => {
		const result = await createRuntimeCategory({ name: "  New Cat  " }, actor, locals);
		expect(result).toMatchObject({ ok: true });
		expect(latestAudit()).toMatchObject({
			action: "category.create",
			resource_type: "content",
			resource_id: "  New Cat  ",
			summary: "Created category New Cat.",
		});
	});

	it("uses input.slug as resource_id when provided (?? left branch)", async () => {
		await createRuntimeCategory({ name: "Some Cat", slug: "explicit-cat-slug" }, actor, locals);
		expect(latestAudit()?.resource_id).toBe("explicit-cat-slug");
	});

	it("rejects duplicate slug and skips audit", async () => {
		const result = await createRuntimeCategory({ name: "Existing Cat" }, actor, locals);
		expect(result).toMatchObject({ ok: false });
		expect(latestAudit()).toBeUndefined();
