import { describe, expect, it } from "vitest";

import type { ApiScope, ApiTokenRecord, ApiTokenStore } from "../src/platform-contracts";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { hashOpaqueToken } from "../src/sqlite-runtime/utils.js";
import { makeDb } from "./helpers/make-db.js";

// ─── ApiTokenRecord shape ─────────────────────────────────────────────────────

describe("ApiTokenRecord shape", () => {
	it("has all required fields", () => {
		const record: ApiTokenRecord = {
			id: "tok_01",
			label: "AI assistant",
			scopes: ["content:read"],
			createdAt: new Date().toISOString(),
		};

		expect(record.id).toBe("tok_01");
		expect(record.label).toBe("AI assistant");
		expect(record.scopes).toContain("content:read");
		expect(record.revokedAt).toBeUndefined();
	});

	it("supports all defined scopes", () => {
		const allScopes: ApiScope[] = [
			"content:read",
			"content:write",
			"media:read",
			"media:write",
			"settings:read",
			"webhooks:manage",
			"import:write",
		];
		const record: ApiTokenRecord = {
			id: "tok_02",
			label: "Full access",
			scopes: allScopes,
			createdAt: new Date().toISOString(),
		};
		expect(record.scopes).toHaveLength(7);
	});

	it("optional fields are truly optional", () => {
		const minimal: ApiTokenRecord = {
			id: "tok_03",
			label: "Minimal",
			scopes: ["settings:read"],
			createdAt: "2026-01-01T00:00:00Z",
		};
		expect(minimal.expiresAt).toBeUndefined();
		expect(minimal.lastUsedAt).toBeUndefined();
		expect(minimal.revokedAt).toBeUndefined();
	});
});

describe("ApiTokenStore SQLite implementation", () => {
	it("create: stores hashed token and returns raw token once", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);

		const { record, rawToken } = await store.create({
			label: "test",
			scopes: ["content:read"],
		});

		expect(rawToken.length).toBeGreaterThanOrEqual(32);
		expect(record.label).toBe("test");
		expect(record.scopes).toEqual(["content:read"]);
		expect(record.revokedAt).toBeNull();

		// Hash stored, not raw token
		const row = db.prepare("SELECT token_hash FROM api_tokens WHERE id = ?").get(record.id) as {
			token_hash: string;
		};
		expect(row.token_hash).toBe(hashOpaqueToken(rawToken));
		expect(row.token_hash).not.toBe(rawToken);
	});

	it("list: returns tokens without token_hash", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		await store.create({ label: "alpha", scopes: ["content:read"] });
		await store.create({ label: "beta", scopes: ["media:read"] });

		const tokens = await store.list();
		expect(tokens).toHaveLength(2);
		const labels = tokens.map((t) => t.label);
		expect(labels).toContain("alpha");
		expect(labels).toContain("beta");
		// No hash exposed
		for (const token of tokens) {
			expect((token as Record<string, unknown>).token_hash).toBeUndefined();
		}
	});

	it("verify: valid unrevoked token succeeds and updates lastUsedAt", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { rawToken } = await store.create({
			label: "agent",
			scopes: ["content:read"],
		});

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");

		expect(result.record.label).toBe("agent");
		expect(result.record.lastUsedAt).not.toBeNull();
	});

	it("verify: revoked token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "short-lived",
			scopes: ["settings:read"],
		});

		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
	});

	it("verify: unknown token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("completely-unknown-token");
		expect(result.valid).toBe(false);
	});

	it("revoke: sets revokedAt timestamp", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revoke-me",
			scopes: ["content:write"],
		});

		await store.revoke(record.id);
		const tokens = await store.list();
		const revoked = tokens.find((t) => t.id === record.id);
		expect(revoked?.revokedAt).not.toBeNull();
	});

	it("verify: expired token returns { valid: false } with 'expired' reason", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const past = new Date(Date.now() - 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "expired",
			scopes: ["content:read"],
			expiresAt: past,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/expired/i);
	});

	it("verify: future-expiry token still verifies (pins < boundary on expires_at)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		const { rawToken, record } = await store.create({
			label: "future",
			scopes: ["content:read"],
			expiresAt: future,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");
		expect(result.record.expiresAt).toBe(future);
		expect(record.expiresAt).toBe(future);
	});

	it("create: persists expiresAt in the returned record (pins ?? null fallback)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "no-expiry",
			scopes: ["content:read"],
		});
		expect(record.expiresAt).toBeNull();
	});

	it("verify: revoked token reason mentions 'revoked' (pins reason literal)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "revoke-reason",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/revoked/i);
	});

	it("verify: unknown token reason mentions 'not found' (pins reason literal)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("nonexistent-token");
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/not found/i);
	});

	it("list: revoked tokens still appear in list (for admin display)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revocable",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);

		const tokens = await store.list();
		expect(tokens.some((t) => t.id === record.id)).toBe(true);
	});
});

// Type-level smoke test: ensure the interface is structurally correct
function assertApiTokenStoreShape(store: ApiTokenStore) {
	const _create = store.create;
	const _list = store.list;
	const _verify = store.verify;
	const _revoke = store.revoke;
	return { _create, _list, _verify, _revoke };
}

// Unused reference satisfies TypeScript without needing a real implementation
void assertApiTokenStoreShape;

tests/d1-rate-limit-part.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { createD1RateLimitPart } from "../src/d1-rate-limit-part";

interface PreparedSpy {
	prepare: ReturnType<typeof vi.fn>;
	binds: unknown[][];
	queries: string[];
	runs: number;
}

function makeDb(firstReturn: unknown): PreparedSpy & { db: never } {
	const binds: unknown[][] = [];
	const queries: string[] = [];
	let runs = 0;
	const stmt = (q: string) => {
		queries.push(q);
		return {
			bind(...args: unknown[]) {
				binds.push(args);
				return {
					async first() {
						return firstReturn;
					},
					async run() {
						runs++;
					},
				};
			},
		};
	};
	const prepare = vi.fn(stmt);
	return {
		db: { prepare } as never,
		prepare,
		binds,
		queries,
		get runs() {
			return runs;
		},
	} as PreparedSpy & { db: never };
}

beforeEach(() => {
	vi.useFakeTimers();
	vi.setSystemTime(new Date("2026-05-03T00:00:00Z"));
});

afterEach(() => {
	vi.useRealTimers();
});

describe("createD1RateLimitPart.checkRateLimit", () => {
	it("inserts a fresh row when no row exists and returns true", async () => {
		const m = makeDb(null);
		const part = createD1RateLimitPart(m.db);
		const ok = await part.checkRateLimit("k", 5, 60_000);
		expect(ok).toBe(true);
		// Pin the SELECT-query StringLiteral mutation: the read query MUST be
		// the rate-limits SELECT, not "" or any other string.
		expect(
			m.queries.some(
				(q) =>
					q.includes("SELECT") &&
					q.includes("rate_limits") &&
					q.includes("window_ms") &&
					q.includes("LIMIT 1"),
			),
		).toBe(true);
		expect(m.queries.some((q) => q.includes("INSERT INTO rate_limits"))).toBe(true);
		// Bound args of the INSERT include (key, now, windowMs).
		const insertBind = m.binds.find((b) => typeof b[0] === "string" && b.length === 3);
		expect(insertBind?.[0]).toBe("k");
		expect(insertBind?.[2]).toBe(60_000);
	});

	it("inserts a fresh row when window has expired", async () => {
		const m = makeDb({ count: 99, window_start_ms: 0, window_ms: 1 });
		const part = createD1RateLimitPart(m.db);
		const ok = await part.checkRateLimit("k", 5, 1);
		expect(ok).toBe(true);
		expect(m.queries.some((q) => q.includes("INSERT INTO rate_limits"))).toBe(true);
	});

	it("increments count when under limit and returns true", async () => {
		const now = Date.now();
		const m = makeDb({
			count: 2,
			window_start_ms: now - 100,
			window_ms: 60_000,
		});
		const part = createD1RateLimitPart(m.db);
		const ok = await part.checkRateLimit("k", 5, 60_000);
		expect(ok).toBe(true);
		expect(m.queries.some((q) => q.includes("UPDATE rate_limits SET count = count + 1"))).toBe(
			true,
		);
	});

	it("returns false when count is at the limit", async () => {
		const now = Date.now();
		const m = makeDb({
			count: 5,
			window_start_ms: now - 100,
			window_ms: 60_000,
		});
		const part = createD1RateLimitPart(m.db);
		const ok = await part.checkRateLimit("k", 5, 60_000);
		expect(ok).toBe(false);
	});

	it("treats elapsed === windowMs as still-in-window (boundary)", async () => {
		// Pins the EqualityOperator mutation `> windowMs` -> `>= windowMs`.
		// At elapsed exactly equal to windowMs the original returns false
		// (still in window, increment); the mutant would treat it as expired
		// and INSERT instead of UPDATE.
		const now = Date.now();
		const m = makeDb({
			count: 2,
			window_start_ms: now - 60_000,
			window_ms: 60_000,
		});
		const part = createD1RateLimitPart(m.db);
		await part.checkRateLimit("k", 5, 60_000);
		expect(m.queries.some((q) => q.includes("UPDATE rate_limits SET count = count + 1"))).toBe(
			true,
		);
		expect(m.queries.some((q) => q.includes("INSERT INTO rate_limits"))).toBe(false);
	});
});

describe("createD1RateLimitPart.peekRateLimit", () => {
	it("returns true when no row exists (does not write)", async () => {
		const m = makeDb(null);
		const part = createD1RateLimitPart(m.db);
		expect(await part.peekRateLimit("k", 5, 60_000)).toBe(true);
		expect(m.runs).toBe(0);
	});

	it("returns true when window has expired", async () => {
		const m = makeDb({ count: 99, window_start_ms: 0 });
		const part = createD1RateLimitPart(m.db);
		expect(await part.peekRateLimit("k", 5, 1)).toBe(true);
	});

	it("returns true when count is below limit", async () => {
		const now = Date.now();
		const m = makeDb({ count: 4, window_start_ms: now - 100 });
		const part = createD1RateLimitPart(m.db);
		expect(await part.peekRateLimit("k", 5, 60_000)).toBe(true);
	});

	it("returns false when count is at limit", async () => {
		const now = Date.now();
		const m = makeDb({ count: 5, window_start_ms: now - 100 });
		const part = createD1RateLimitPart(m.db);
		expect(await part.peekRateLimit("k", 5, 60_000)).toBe(false);
	});

	it("uses the rate-limits SELECT query (no LIMIT/columns mutation to '')", async () => {
		const m = makeDb(null);
		await createD1RateLimitPart(m.db).peekRateLimit("k", 5, 1);
		expect(
			m.queries.some(
				(q) => q.includes("SELECT") && q.includes("rate_limits") && q.includes("LIMIT 1"),
			),
		).toBe(true);
	});

	it("treats elapsed === windowMs as still-in-window (boundary)", async () => {
		const now = Date.now();
		const m = makeDb({ count: 5, window_start_ms: now - 60_000 });
		const part = createD1RateLimitPart(m.db);
		// At elapsed===windowMs: original returns row.count<max → 5<5=false.
		// Mutant `>= windowMs` would short-circuit to true (window expired).
		expect(await part.peekRateLimit("k", 5, 60_000)).toBe(false);
	});
});

describe("createD1RateLimitPart.recordFailedAttempt", () => {
	it("inserts fresh row when no row exists", async () => {
		const m = makeDb(null);
		const part = createD1RateLimitPart(m.db);
		await part.recordFailedAttempt("k", 5, 60_000);
		expect(m.queries.some((q) => q.includes("INSERT INTO rate_limits"))).toBe(true);
	});

	it("inserts fresh row when window has expired", async () => {
		const m = makeDb({ count: 99, window_start_ms: 0 });
		const part = createD1RateLimitPart(m.db);
		await part.recordFailedAttempt("k", 5, 1);
		expect(m.queries.some((q) => q.includes("INSERT INTO rate_limits"))).toBe(true);
	});

	it("increments count when row exists within window", async () => {
		const now = Date.now();
		const m = makeDb({ count: 2, window_start_ms: now - 100 });
		const part = createD1RateLimitPart(m.db);
		await part.recordFailedAttempt("k", 5, 60_000);
		expect(m.queries.some((q) => q.includes("UPDATE rate_limits SET count = count + 1"))).toBe(
			true,
		);
	});

	it("uses the rate-limits SELECT query (no StringLiteral mutation)", async () => {
		const m = makeDb(null);
		await createD1RateLimitPart(m.db).recordFailedAttempt("k", 5, 1);
		expect(
			m.queries.some(
				(q) => q.includes("SELECT") && q.includes("rate_limits") && q.includes("LIMIT 1"),
			),
		).toBe(true);
	});

	it("treats elapsed === windowMs as still-in-window (boundary)", async () => {
		const now = Date.now();
		const m = makeDb({ count: 2, window_start_ms: now - 60_000 });
		const part = createD1RateLimitPart(m.db);
		await part.recordFailedAttempt("k", 5, 60_000);
		// At elapsed===windowMs: original UPDATEs (still-in-window).
		// Mutant `>= windowMs` would INSERT (window expired).
		expect(m.queries.some((q) => q.includes("UPDATE rate_limits SET count = count + 1"))).toBe(
			true,
		);
		expect(m.queries.some((q) => q.includes("INSERT INTO rate_limits"))).toBe(false);
	});
});

tests/cloudflare-provider.integration.te.source:
import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { makeDb } from "./helpers/make-db.js";
import {
	createSeededCloudflareDatabase,
	SqliteBackedD1Database,
} from "./helpers/provider-test-fixtures.js";

describe("cloudflare provider integration", () => {
	it("creates a D1-backed Cloudflare adapter surface", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		expect(cloudflare.capabilities.name).toBe("cloudflare");
		expect(cloudflare.capabilities.database).toBe(true);
		expect(cloudflare.capabilities.objectStorage).toBe(true);
		expect(cloudflare.capabilities.staticPublishing).toBe(true);
		expect(cloudflare.capabilities.hostedAdmin).toBe(true);
		expect(cloudflare.capabilities.previewEnvironments).toBe(true);
		expect(cloudflare.capabilities.serverRuntime).toBe(true);
		expect(cloudflare.capabilities.gitSync).toBe(true);

		const user = await cloudflare.auth.signIn("admin@example.com", "password");
		expect(user?.isAdmin).toBe(true);
		expect(user?.id).toHaveLength(36);
		const storedSession = db.prepare("SELECT id FROM admin_sessions LIMIT 1").get() as {
			id: string;
		};
		expect(storedSession.id).not.toBe(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(await cloudflare.content.get("cloudflare-post")).toMatchObject({
			slug: "cloudflare-post",
			kind: "post",
			title: "Cloudflare post",
		});
		expect(await cloudflare.media.get("cloudflare-media-1")).toMatchObject({
			id: "cloudflare-media-1",
			mimeType: "image/png",
		});
		expect(await cloudflare.revisions.list("cloudflare-post")).toMatchObject([
			{
				id: "revision-cloudflare-1",
				recordId: "cloudflare-post",
			},
		]);
		await cloudflare.auth.signOut(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toBeNull();

		db.close();
	});

	it("persists writable records through the D1-backed Cloudflare adapter", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		const savedPost = await cloudflare.content.save({
			id: "cloudflare-write-post",
			kind: "post",
			slug: "cloudflare-write-post",
			status: "published",
			title: "Cloudflare write post",
			body: "<p>Writable Cloudflare body</p>",
			metadata: {
				metaDescription: "Writable Cloudflare record",
				seoTitle: "Cloudflare write post",
				legacyUrl: "/cloudflare-write-post",
			},
		});
		expect(savedPost.slug).toBe("cloudflare-write-post");
		expect(await cloudflare.content.get("cloudflare-write-post")).toMatchObject({
			slug: "cloudflare-write-post",
			kind: "post",
			title: "Cloudflare write post",
		});

		const translation = await cloudflare.content.save({
			id: "/es/cloudflare-write-post",
			kind: "translation",
			slug: "/es/cloudflare-write-post",
			status: "draft",
			metadata: {
				state: "translated",
			},
		});
		expect(translation.metadata).toMatchObject({
			state: "translated",
		});

		const redirect = await cloudflare.content.save({
			id: "/legacy-cloudflare-write-post",
			kind: "redirect",
			slug: "/legacy-cloudflare-write-post",
			status: "published",
			metadata: {
				targetPath: "/cloudflare-write-post",
				statusCode: 301,
			},
		});
		expect(redirect.metadata).toMatchObject({
			targetPath: "/cloudflare-write-post",
			statusCode: 301,
		});

		const settings = await cloudflare.content.save({
			id: "site-settings",
			kind: "settings",
			slug: "site-settings",
			status: "published",
			metadata: {
				siteTitle: "Cloudflare Writable Site",
			},
		});
		expect(settings.title).toBe("Cloudflare Writable Site");

		await cloudflare.media.put({
			id: "cloudflare-upload",
			filename: "cloudflare-upload.png",
			mimeType: "image/png",
			publicUrl: "https://cdn.example.com/cloudflare-upload.png",
			metadata: {
				altText: "Cloudflare upload",
				title: "cloudflare-upload.png",
			},
		});
		expect(await cloudflare.media.get("cloudflare-upload")).toMatchObject({
			id: "cloudflare-upload",
			mimeType: "image/png",
		});

		await cloudflare.revisions.append({
			id: "cloudflare-write-revision",
			recordId: "cloudflare-write-post",
			createdAt: "2026-01-01T00:00:00.000Z",
			actorId: "admin@example.com",
			summary: "Cloudflare write revision",
			snapshot: {
				title: "Cloudflare write post",
				status: "published",
				body: "<p>Writable Cloudflare body</p>",
				seoTitle: "Cloudflare write post",
				metaDescription: "Writable Cloudflare record",
			},
		});
		expect(await cloudflare.revisions.list("cloudflare-write-post")).toEqual(
			expect.arrayContaining([
				expect.objectContaining({
					id: "cloudflare-write-revision",
					recordId: "cloudflare-write-post",
				}),
			]),
		);

		await cloudflare.content.delete("/legacy-cloudflare-write-post");
		await cloudflare.media.delete("cloudflare-upload");

		expect(await cloudflare.content.get("/legacy-cloudflare-write-post")).toBeNull();
		expect(await cloudflare.media.get("cloudflare-upload")).toBeNull();

		db.close();
	});

	it("throws when saving an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		await expect(
			cloudflare.content.save({
				id: "comment-1",
				kind: "comment",
				slug: "comment-1",
				status: "published",
				metadata: {},
			} as Parameters<typeof cloudflare.content.save>[0]),
		).rejects.toThrow("does not support saving comment records yet");

		db.close();
	});

	it("returns without throwing when deleting an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();

		// Insert a comment record — the Cloudflare adapter lists comments via readStore
		// and surfaces them through content.get(). The delete path now degrades gracefully.
		db.prepare(
			`INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		).run(
			"comment-del-1",
			"Test Author",
			"test@example.com",
			"Test comment",
			"/blog",
			"pending",
			"open-moderated",
			"2026-01-01T00:00:00.000Z",
		);

		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Unsupported record kind — adapter degrades gracefully (no-op) rather than throwing
		await expect(cloudflare.content.delete("comment-del-1")).resolves.toBeUndefined();

		db.close();
	});
});

