import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { beforeEach, describe, expect, test, vi } from "vitest";
import type { LocalAccessStoreSurface } from "../src/access";
import { createAccessRepository, requiresAccess, seedStarterRoles } from "../src/access";
import { loadSqliteDatabase } from "../src/sqlite-bootstrap-helpers";

const SCHEMA = readFileSync(
	fileURLToPath(new URL("../src/sqlite-schema.sql", import.meta.url)),
	"utf8",
);

interface DbHandle {
	prepare: (sql: string) => {
		all: <T = unknown>(...args: unknown[]) => T[];
		get: <T = unknown>(...args: unknown[]) => T | undefined;
		run: (...args: unknown[]) => { changes: number };
	};
	exec: (sql: string) => void;
}

let currentStore: { access?: LocalAccessStoreSurface } = {};

vi.mock("../src/local-runtime-modules", async (orig) => {
	const original = await orig<typeof import("../src/local-runtime-modules")>();
	return {
		...original,
		loadLocalAdminStore: async () => currentStore as never,
	};
});

function buildLocalSurface(db: DbHandle): LocalAccessStoreSurface {
	const repo = createAccessRepository(db as never);
	return {
		resolveAccessSnapshotByEmail(email) {
			const row = db
				.prepare("SELECT id, is_admin FROM admin_users WHERE email = ? AND active = 1 LIMIT 1")
				.get<{ id: number; is_admin: number }>(email);
			if (!row) return null;
			return {
				userId: String(row.id),
				isAdmin: row.is_admin === 1,
				roles: repo.listUserRoleIds(row.id),
				attributes: repo.getUserAttributes(row.id),
				policies: repo.resolvePoliciesForUser(row.id),
			};
		},
	};
}

function fakeAstro(adminUser: { email: string; role: "admin" | "editor"; name: string } | null) {
	const calls: Array<{ path: string; status?: number }> = [];
	const astro = {
		locals: { adminUser } as unknown as App.Locals,
		redirect(path: string, status?: number) {
			calls.push({ path, status });
			return new Response(null, {
				status: status ?? 302,
				headers: { Location: path },
			});
		},
	};
	return { astro, calls };
}

describe("requiresAccess", () => {
	let db: DbHandle;
	beforeEach(async () => {
		const DbClass = await loadSqliteDatabase();
		const inst = new DbClass(":memory:");
		inst.exec(SCHEMA);
		db = inst as unknown as DbHandle;
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, is_admin) VALUES (?, 'h', 'Admin', 1)",
		).run("admin@example.com");
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, is_admin) VALUES (?, 'h', 'Editor', 0)",
		).run("editor@example.com");
		const repo = createAccessRepository(db as never);
		seedStarterRoles(repo);
		const editor = repo.listRoles().find((r) => r.name === "Editor");
		if (!editor) throw new Error("Editor role missing");
		const editorRow = db
			.prepare("SELECT id FROM admin_users WHERE email = ?")
			.get<{ id: number }>("editor@example.com");
		if (!editorRow) throw new Error("editor fixture missing");
		repo.assignRole({ userId: editorRow.id, roleId: editor.id });
		currentStore = { access: buildLocalSurface(db) };
	});

	test("returns null and continues when subject is allowed", async () => {
		const { astro, calls } = fakeAstro({
			email: "admin@example.com",
			role: "admin",
			name: "Admin",
		});
		const result = await requiresAccess(astro, "settings:edit");
		expect(result).toBeNull();
		expect(calls).toHaveLength(0);
	});

	test("redirects with forbidden path on deny — appends the engine reason for the UI banner", async () => {
		const { astro, calls } = fakeAstro({
			email: "editor@example.com",
			role: "editor",
			name: "Editor",
		});
		const result = await requiresAccess(astro, "users:invite");
		expect(result).not.toBeNull();
		expect(calls[0]?.path).toMatch(/^\/ap-admin\?error=insufficient-permissions&reason=/);
	});

	test("redirects to login when no admin user", async () => {
		const { astro, calls } = fakeAstro(null);
		const result = await requiresAccess(astro, "settings:edit");
		expect(result).not.toBeNull();
		expect(calls[0]?.path).toBe("/ap-admin/login");
	});

	test("respects override forbidden + login paths", async () => {
		const { astro: astro1, calls: calls1 } = fakeAstro({
			email: "editor@example.com",
			role: "editor",
			name: "Editor",
		});
		await requiresAccess(astro1, "users:invite", {
			forbiddenPath: "/ap-admin/forbidden",
		});
		expect(calls1[0]?.path).toBe("/ap-admin/forbidden");

		const { astro: astro2, calls: calls2 } = fakeAstro(null);
		await requiresAccess(astro2, "settings:edit", {
			loginPath: "/auth/login",
		});
		expect(calls2[0]?.path).toBe("/auth/login");
	});
});

tests/sqlite-seed-helpers.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	buildTableImportSql,
	buildTableImportStatements,
	guessMimeType,
	toSqlLiteral,
} from "../src/sqlite-seed-helpers";

describe("guessMimeType", () => {
	it("returns image/png for .png paths", () => {
		expect(guessMimeType("a.png")).toBe("image/png");
		expect(guessMimeType("/uploads/x.PNG")).toBe("image/png");
	});

	it("returns image/webp for .webp paths", () => {
		expect(guessMimeType("photo.webp")).toBe("image/webp");
	});

	it("returns image/gif for .gif paths", () => {
		expect(guessMimeType("anim.gif")).toBe("image/gif");
	});

	it("falls back to image/jpeg for unknown extensions", () => {
		expect(guessMimeType("file.jpg")).toBe("image/jpeg");
		expect(guessMimeType("file.jpeg")).toBe("image/jpeg");
		expect(guessMimeType("file.bin")).toBe("image/jpeg");
		expect(guessMimeType("file")).toBe("image/jpeg");
		expect(guessMimeType("")).toBe("image/jpeg");
	});

	it("matches case-insensitively (lowercases input first)", () => {
		expect(guessMimeType("X.WEBP")).toBe("image/webp");
		expect(guessMimeType("Y.GIF")).toBe("image/gif");
	});
});

describe("toSqlLiteral", () => {
	it("encodes null and undefined as NULL", () => {
		expect(toSqlLiteral(null)).toBe("NULL");
		expect(toSqlLiteral(undefined)).toBe("NULL");
	});

	it("renders numbers and bigints unquoted", () => {
		expect(toSqlLiteral(42)).toBe("42");
		expect(toSqlLiteral(0)).toBe("0");
		expect(toSqlLiteral(-7)).toBe("-7");
		expect(toSqlLiteral(BigInt(9007199254740993n))).toBe("9007199254740993");
	});

	it("renders booleans as 1 or 0 (sqlite convention)", () => {
		expect(toSqlLiteral(true)).toBe("1");
		expect(toSqlLiteral(false)).toBe("0");
	});

	it("renders Uint8Array as a hex blob literal", () => {
		expect(toSqlLiteral(new Uint8Array([0xde, 0xad, 0xbe, 0xef]))).toBe("X'deadbeef'");
		expect(toSqlLiteral(new Uint8Array([]))).toBe("X''");
	});

	it("quotes strings and escapes embedded single quotes", () => {
		expect(toSqlLiteral("hi")).toBe("'hi'");
		expect(toSqlLiteral("it's")).toBe("'it''s'");
		expect(toSqlLiteral("a'b'c")).toBe("'a''b''c'");
		expect(toSqlLiteral("")).toBe("''");
	});

	it("stringifies non-string non-special objects (Date, etc.) and quotes the result", () => {
		const date = new Date("2026-05-03T00:00:00Z");
		expect(toSqlLiteral(date)).toBe(`'${String(date)}'`);
	});
});

describe("buildTableImportStatements", () => {
	function makeDb(
		columnsByTable: Record<string, string[]>,
		rowsByTable: Record<string, Record<string, unknown>[]>,
	) {
		return {
			prepare(query: string) {
				if (query.startsWith("PRAGMA table_info")) {
					const m = query.match(/table_info\((\w+)\)/);
					const table = m?.[1] ?? "";
					const cols = columnsByTable[table] ?? [];
					return {
						all: () =>
							cols.map((name, idx) => ({
								cid: idx,
								name,
								type: "TEXT",
								notnull: 0,
								dflt_value: null,
								pk: 0,
							})),
					};
				}
				const m = query.match(/SELECT \* FROM (\w+)/);
				const table = m?.[1] ?? "";
				return {
					all: () => rowsByTable[table] ?? [],
				};
			},
		} as never;
	}

	it("returns an empty list when the table has no columns", () => {
		const db = makeDb({ posts: [] }, { posts: [{ a: 1 }] });
		expect(buildTableImportStatements(db, "posts")).toEqual([]);
	});

	it("emits DELETE then one INSERT per row, in column order", () => {
		const db = makeDb(
			{ posts: ["id", "title"] },
			{
				posts: [
					{ id: 1, title: "hi" },
					{ id: 2, title: "yo" },
				],
			},
		);
		const out = buildTableImportStatements(db, "posts");
		expect(out).toEqual([
			"DELETE FROM posts;",
			"INSERT INTO posts (id, title) VALUES (1, 'hi');",
			"INSERT INTO posts (id, title) VALUES (2, 'yo');",
		]);
	});

	it("renders each row's values via toSqlLiteral (quoting + null + bool)", () => {
		const db = makeDb(
			{ items: ["a", "b", "c", "d"] },
			{
				items: [{ a: null, b: true, c: 0, d: "hello" }],
			},
		);
		expect(buildTableImportStatements(db, "items")).toEqual([
			"DELETE FROM items;",
			"INSERT INTO items (a, b, c, d) VALUES (NULL, 1, 0, 'hello');",
		]);
	});
});

describe("buildTableImportSql", () => {
	it("joins the statements with newlines", () => {
		const db = {
			prepare(query: string) {
				if (query.startsWith("PRAGMA table_info")) {
					return {
						all: () => [{ cid: 0, name: "id", type: "INTEGER" }],
					};
				}
				return { all: () => [{ id: 7 }] };
			},
		} as never;
		expect(buildTableImportSql(db, "x")).toBe("DELETE FROM x;\nINSERT INTO x (id) VALUES (7);");
	});
});

