import { afterEach, describe, expect, it } from "vitest";

import {
	_resetOAuthRegistryForTests,
	type OAuthProviderDefinition,
} from "../../../src/integrations/oauth/registry";
import { buildAuthorizeRedirect, buildRedirectUri } from "../../../src/integrations/oauth/start";
import { verifyOAuthState } from "../../../src/integrations/oauth/state";

const GITHUB: OAuthProviderDefinition = {
	id: "github",
	domain: "deploy-hooks",
	label: "GitHub",
	authorizationUrl: "https://github.com/login/oauth/authorize",
	tokenUrl: "https://github.com/login/oauth/access_token",
	scopes: ["repo:status", "read:org"],
	clientIdEnv: "GITHUB_OAUTH_CLIENT_ID",
	clientSecretEnv: "GITHUB_OAUTH_CLIENT_SECRET",
	redirectPath: "/ap-admin/oauth/callback/github",
};

const NOW = 1_700_000_000_000;
const ROOT = "test-root-secret";

describe("buildRedirectUri", () => {
	it("joins origin and path with one slash", () => {
		expect(buildRedirectUri("https://x.example", "/cb")).toBe("https://x.example/cb");
	});

	it("trims trailing slashes from the origin", () => {
		expect(buildRedirectUri("https://x.example///", "/cb")).toBe("https://x.example/cb");
	});

	it("prepends a slash when the path is missing one", () => {
		expect(buildRedirectUri("https://x.example", "cb")).toBe("https://x.example/cb");
	});

	it("preserves the exact path beyond the leading slash", () => {
		expect(buildRedirectUri("https://x.example", "/ap-admin/oauth/callback/github")).toBe(
			"https://x.example/ap-admin/oauth/callback/github",
		);
	});

	it("returns just the prefixed path when origin is empty", () => {
		// kills end > 0 → end >= 0 / true mutants: distinguishes the
		// terminating end===0 case from the always-loop variants.
		expect(buildRedirectUri("", "/cb")).toBe("/cb");
	});

	it("returns just the prefixed path when origin is only slashes", () => {
		expect(buildRedirectUri("///", "/cb")).toBe("/cb");
	});
});

describe("buildAuthorizeRedirect", () => {
	afterEach(() => _resetOAuthRegistryForTests());

	it("returns a URL on the provider's authorize host with the expected query keys", async () => {
		const { redirectUrl } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/ap-admin/deploy-hooks",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const url = new URL(redirectUrl);
		expect(url.origin).toBe("https://github.com");
		expect(url.pathname).toBe("/login/oauth/authorize");
		expect(url.searchParams.get("client_id")).toBe("abc123");
		expect(url.searchParams.get("redirect_uri")).toBe(
			"https://my.example/ap-admin/oauth/callback/github",
		);
		expect(url.searchParams.get("response_type")).toBe("code");
		expect(url.searchParams.get("scope")).toBe("repo:status read:org");
		expect(url.searchParams.get("state")).toBeTruthy();
	});

	it("the issued state verifies under the same rootSecret + provider context", async () => {
		const { state } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/ap-admin/deploy-hooks",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const verified = await verifyOAuthState({
			token: state.token,
			rootSecret: ROOT,
			nowMs: NOW + 1000,
			expectedContext: {
				domain: GITHUB.domain,
				providerId: GITHUB.id,
				returnTo: "/ap-admin/deploy-hooks",
			},
		});
		expect(verified.ok).toBe(true);
	});

	it("does not verify under a different rootSecret", async () => {
		const { state } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/ap-admin/deploy-hooks",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		const verified = await verifyOAuthState({
			token: state.token,
			rootSecret: "different-root",
			nowMs: NOW + 1000,
		});
		expect(verified.ok).toBe(false);
	});

	it("space-joins multiple scopes into the scope query parameter", async () => {
		const { redirectUrl } = await buildAuthorizeRedirect({
			provider: { ...GITHUB, scopes: ["a", "b", "c"] },
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/x",
			rootSecret: ROOT,
			nowMs: NOW,
		});
		expect(new URL(redirectUrl).searchParams.get("scope")).toBe("a b c");
	});

	it("allows ttlMs to be plumbed through to the state issuer", async () => {
		const { state } = await buildAuthorizeRedirect({
			provider: GITHUB,
			origin: "https://my.example",
			clientId: "abc123",
			returnTo: "/x",
			rootSecret: ROOT,
			nowMs: NOW,
			ttlMs: 60_000,
		});
		expect(state.expiresAt).toBe(NOW + 60_000);
	});
});

tests/turnstile.test.ts.source:
import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";

import { isTurnstileEnabled, verifyTurnstileToken } from "../src/turnstile";

const originalFetch = globalThis.fetch;
const originalEnv = { ...process.env };

beforeEach(() => {
	for (const key of Object.keys(process.env)) {
		if (key.startsWith("TURNSTILE_") || key.startsWith("PUBLIC_TURNSTILE_") || key === "NODE_ENV") {
			delete process.env[key];
		}
	}
});

afterEach(() => {
	globalThis.fetch = originalFetch;
	for (const k of Object.keys(process.env)) delete process.env[k];
	for (const [k, v] of Object.entries(originalEnv)) process.env[k] = v as string;
});

describe("isTurnstileEnabled", () => {
	test("returns false when TURNSTILE_SECRET_KEY is unset", () => {
		expect(isTurnstileEnabled()).toBe(false);
	});

	test("returns true when TURNSTILE_SECRET_KEY is configured", () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		expect(isTurnstileEnabled()).toBe(true);
	});
});

describe("verifyTurnstileToken", () => {
	test("returns ok when no secret is configured (dev/test mode)", async () => {
		const result = await verifyTurnstileToken({ token: "anything" });
		expect(result).toEqual({ ok: true });
	});

	test("returns error when requireConfigured + production but no secret", async () => {
		process.env.PROD = "1";
		const result = await verifyTurnstileToken({
			token: "anything",
			requireConfigured: true,
		});
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/not configured/);
	});

	test("returns error when token is missing", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		const result = await verifyTurnstileToken({ token: null });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/required/);
	});

	test("returns error when token is whitespace-only", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		const result = await verifyTurnstileToken({ token: "   " });
		expect(result.ok).toBe(false);
	});

	test("returns ok when Cloudflare verifies the token", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: async () => ({ success: true }),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({
			token: "valid-token",
			ipAddress: "203.0.113.5",
		});
		expect(result).toEqual({ ok: true });
		const call = (globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls[0];
		expect(call[0]).toBe("https://challenges.cloudflare.com/turnstile/v0/siteverify");
		const body = call[1].body as URLSearchParams;
		expect(body.get("secret")).toBe("secret-1");
		expect(body.get("response")).toBe("valid-token");
		expect(body.get("remoteip")).toBe("203.0.113.5");
	});

	test("returns error when Cloudflare rejects the token", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: async () => ({
				success: false,
				"error-codes": ["invalid-input-response"],
			}),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "bad-token" });
		expect(result.ok).toBe(false);
		expect(result.error).toContain("invalid-input-response");
	});

	test("returns generic error when Cloudflare rejects with no error-codes", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: async () => ({ success: false }),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "bad" });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/failed/);
	});

	test("returns error when Cloudflare returns a non-OK response", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: false,
			json: async () => ({}),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "any" });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/could not be verified/);
	});

	test("returns error when fetch throws", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi
			.fn()
			.mockRejectedValue(new Error("network down")) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "any" });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/could not be verified/);
	});
});

