import { afterEach, describe, expect, it } from "vitest";

import { getAdminLocalePair, normalizeRoute } from "../src/admin-locale-links";
import { registerCms } from "../src/config";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
});

const TRANSLATION_STATUS = [
	{
		route: "/es/sobre",
		locale: "es",
		englishSourceUrl: "/about",
		translationState: "published",
	},
	{
		route: "/es/contacto",
		locale: "es",
		englishSourceUrl: "/contact",
		translationState: "in_progress",
	},
];

function setup() {
	registerCms({
		siteUrl: "https://example.org",
		templateKeys: ["home"],
		seedPages: [],
		archives: [],
		translationStatus: TRANSLATION_STATUS as never,
	} as never);
}

describe("getAdminLocalePair", () => {
	it("returns es pair when route matches a localized entry", () => {
		setup();
		const pair = getAdminLocalePair("/es/sobre");
		expect(pair).toEqual({
			currentLocale: "es",
			englishRoute: "/about",
			localizedRoute: "/es/sobre",
			translationState: "published",
		});
	});

	it("returns en pair when route matches an englishSourceUrl", () => {
		setup();
		const pair = getAdminLocalePair("/about");
		expect(pair).toEqual({
			currentLocale: "en",
			englishRoute: "/about",
			localizedRoute: "/es/sobre",
			translationState: "published",
		});
	});

	it("returns null when route matches nothing", () => {
		setup();
		expect(getAdminLocalePair("/nope")).toBeNull();
	});

	it("normalizes trailing slashes before matching (localized side)", () => {
		setup();
		expect(getAdminLocalePair("/es/sobre/")?.currentLocale).toBe("es");
		expect(getAdminLocalePair("/es/sobre//")?.currentLocale).toBe("es");
	});

	it("normalizes trailing slashes before matching (english side)", () => {
		setup();
		expect(getAdminLocalePair("/about/")?.currentLocale).toBe("en");
	});

	it("treats empty input as '/' (no match in fixture)", () => {
		setup();
		expect(getAdminLocalePair("")).toBeNull();
	});

	it("treats only-slash input as '/'", () => {
		setup();
		expect(getAdminLocalePair("/")).toBeNull();
	});

	it("a string of all slashes normalizes to '/'", () => {
		setup();
		// "////" → trim trailing slashes leaves "" → return "/"
		expect(getAdminLocalePair("////")).toBeNull();
	});

	it("propagates translationState verbatim from the matching entry", () => {
		setup();
		expect(getAdminLocalePair("/es/contacto")?.translationState).toBe("in_progress");
	});
});

describe("normalizeRoute", () => {
	it("returns '/' for empty input", () => {
		expect(normalizeRoute("")).toBe("/");
	});

	it("returns '/' for undefined-coerced falsy input", () => {
		// Pins the !route branch — a mutant that drops it would try to
		// regex-replace on "" and return "" instead.
		expect(normalizeRoute("")).toBe("/");
	});

	it("returns '/' for a single slash", () => {
		expect(normalizeRoute("/")).toBe("/");
	});

	it("returns '/' for any all-slashes string", () => {
		// Pins the `trimmed === "" ? "/" : trimmed` ternary — without the
		// fallback the function would return "" for these inputs.
		expect(normalizeRoute("//")).toBe("/");
		expect(normalizeRoute("///")).toBe("/");
		expect(normalizeRoute("////")).toBe("/");
	});

	it("strips a single trailing slash", () => {
		expect(normalizeRoute("/about/")).toBe("/about");
	});

	it("strips multiple trailing slashes", () => {
		expect(normalizeRoute("/about///")).toBe("/about");
	});

	it("returns the route unchanged when there is no trailing slash", () => {
		expect(normalizeRoute("/about")).toBe("/about");
		expect(normalizeRoute("/es/sobre")).toBe("/es/sobre");
	});

	it("does not strip non-trailing slashes", () => {
		expect(normalizeRoute("/a/b/c")).toBe("/a/b/c");
		expect(normalizeRoute("/a//b/")).toBe("/a//b");
	});
});

tests/d1-local-integration.test.ts.source:
/**
 * D1 local integration tests — exercises the Cloudflare adapter through a real
 * SQLite-backed D1 shim (SqliteBackedD1Database).
 *
 * These tests use a local SQLite-backed D1 shim. Cloudflare D1 uses SQLite under
 * the hood and the shim is functionally equivalent for integration testing purposes.
 * No Cloudflare account or credentials required.
 */

import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";
import { makeDb, STANDARD_CMS_CONFIG } from "./helpers/make-db.js";
import {
	createSeededCloudflareDatabase,
	SqliteBackedD1Database,
} from "./helpers/provider-test-fixtures.js";

beforeEach(() => {
	registerCms(STANDARD_CMS_CONFIG);
});

describe("D1 adapter: auth round-trip via SQLite shim", () => {
	it("creates a session, retrieves it, and revokes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Sign in
		const session = await adapter.auth.signIn("admin@example.com", "password");
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");
		expect(session?.isAdmin).toBe(true);

		// Retrieve session
		const retrieved = await adapter.auth.getSession(session?.id);
		expect(retrieved?.email).toBe("admin@example.com");

		// Revoke session
		await adapter.auth.signOut(session?.id);
		const revoked = await adapter.auth.getSession(session?.id);
		expect(revoked).toBeNull();
	});
});

describe("D1 adapter: content CRUD via SQLite shim", () => {
	it("creates a content record, reads it back, updates it, and deletes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Create
		const saved = await adapter.content.save({
			id: "d1-test-slug",
			slug: "d1-test-slug",
			kind: "post",
			title: "D1 Test Post",
			status: "draft",
			body: "<p>Initial body</p>",
			metadata: {
				seoTitle: "D1 Test Post",
				metaDescription: "Testing D1",
				legacyUrl: "/d1-test-slug",
				templateKey: "content",
				updatedAt: new Date().toISOString(),
				summary: "",
			},
		});
		expect(saved.slug).toBe("d1-test-slug");

		// Read back
		const fetched = await adapter.content.get("d1-test-slug");
		expect(fetched?.title).toBe("D1 Test Post");
		expect(fetched?.status).toBe("draft");

		// Update
		const updated = await adapter.content.save({
			...saved,
			title: "D1 Updated Post",
			status: "published",
		});
		expect(updated.title).toBe("D1 Updated Post");
		expect(updated.status).toBe("published");

		// Delete (soft delete — archives the record)
		await adapter.content.delete("d1-test-slug");
		const afterDelete = await adapter.content.get("d1-test-slug");
		// The Cloudflare adapter soft-deletes posts by setting status to "archived"
		expect(afterDelete?.status).toBe("archived");
	});
});

describe("D1 adapter: schema bootstrap via SQLite shim", () => {
	it("bootstraps the schema and confirms schema_migrations table exists", () => {
		const db = makeDb();

		const tableRow = db
			.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='schema_migrations'")
			.get() as { name: string } | undefined;

		expect(tableRow?.name).toBe("schema_migrations");
	});

	it("D1 shim executes SQL statements via prepare().all()", async () => {
		const db = await createSeededCloudflareDatabase();
		const d1 = new SqliteBackedD1Database(db);

		const result = await d1
			.prepare("SELECT COUNT(*) as count FROM admin_users")
			.first<{ count: number }>();
		expect(result).not.toBeNull();
		expect(result?.count).toBeGreaterThan(0);
	});
});

tests/content-search.test.ts.source:
/**
 * Content search tests — verifies FTS5 virtual table creation, trigger-based sync,
 * and search query behavior.
 *
 * All tests run in-process using DatabaseSync with the real schema.
 */

import { describe, expect, it, vi } from "vitest";

import { searchContentOverrides } from "../src/sqlite-runtime/search.js";
import { ensureFts5SearchIndex, getTableSql } from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(search?: { enabled?: boolean }) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		search,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = null;
}

describe("FTS5 search index creation", () => {
	it("ensureFts5SearchIndex creates content_fts virtual table", () => {
		const db = makeDb();
		expect(getTableSql(db, "content_fts")).toBeUndefined();

		ensureFts5SearchIndex(db);

		// FTS5 virtual tables appear in sqlite_master as type 'table'
		const row = db.prepare("SELECT name FROM sqlite_master WHERE name = 'content_fts'").get() as
			| { name: string }
			| undefined;
		expect(row?.name).toBe("content_fts");
		db.close();
	});

	it("ensureFts5SearchIndex is idempotent — calling twice does not throw", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);
		expect(() => ensureFts5SearchIndex(db)).not.toThrow();
		db.close();
	});
});

describe("FTS5 search query", () => {
	it("returns a record whose body matches a unique phrase", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-test-post', 'FTS Test Post', 'published', 'admin@example.com', 'uniqueftstestphrase searchable content')`,
		).run();

		const results = searchContentOverrides(db, "uniqueftstestphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-test-post");
		db.close();
	});

	it("returns updated content after an UPDATE trigger fires", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-update-test', 'Update Test', 'draft', 'admin@example.com', 'originalbodycontent')`,
		).run();

		// Update the body — the AFTER UPDATE trigger should sync the FTS index
		db.prepare(
			`UPDATE content_overrides SET body = 'replacedftsbodyphrase' WHERE slug = 'fts-update-test'`,
		).run();

		const results = searchContentOverrides(db, "replacedftsbodyphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-update-test");

		// Original phrase should no longer match
		const oldResults = searchContentOverrides(db, "originalbodycontent");
		expect(oldResults).toHaveLength(0);
		db.close();
	});
});

describe("searchRuntimeContentStates gating", () => {
	it("returns empty array with a warning when search.enabled is false", async () => {
		setCmsConfig({ enabled: false });
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

		// Import after setting config to ensure peekCmsConfig resolves correctly
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("hello");

		expect(results).toEqual([]);
		expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("search.enabled"));
		warnSpy.mockRestore();
		clearCmsConfig();
	});
});

tests/project-adapter.integration.test.t.source:
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import {
	createAstropressProjectAdapter,
	resolveAstropressProjectAdapterMode,
} from "../src/adapters/project.js";

describe("project adapter integration", () => {
	it("selects project adapters from runtime mode and project env", async () => {
		expect(resolveAstropressProjectAdapterMode({})).toBe("local");
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "hosted",
			}),
		).toBe("hosted");

		const workspace = await mkdtemp(join(tmpdir(), "astropress-project-adapter-"));
		const localAdapter = createAstropressProjectAdapter({
			env: {
				ASTROPRESS_RUNTIME_MODE: "local",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "project-adapter.sqlite"),
			},
		});

		expect(localAdapter.capabilities.name).toBe("supabase");

		await rm(workspace, { recursive: true, force: true });
	});

	it("trims surrounding whitespace before matching the 'hosted' mode (kills .trim removal)", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "  hosted  ",
			}),
		).toBe("hosted");
	});

	it("returns 'local' when ASTROPRESS_RUNTIME_MODE is the literal 'local'", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "local",
			}),
		).toBe("local");
	});

	it("returns 'local' when ASTROPRESS_RUNTIME_MODE is undefined (no env)", () => {
		expect(resolveAstropressProjectAdapterMode({})).toBe("local");
	});

	it("returns 'local' for any value other than 'hosted' (e.g. typo)", () => {
		expect(
			resolveAstropressProjectAdapterMode({
				ASTROPRESS_RUNTIME_MODE: "hosting",
			}),
		).toBe("local");
	});

	it("explicit options.mode overrides any env-derived mode (kills ?? to && mutant)", async () => {
		// env says hosted, but options.mode="local" should win.
		const workspace = await mkdtemp(join(tmpdir(), "astropress-mode-override-"));
		const adapter = createAstropressProjectAdapter({
			mode: "local",
			env: {
				ASTROPRESS_RUNTIME_MODE: "hosted",
				ASTROPRESS_LOCAL_PROVIDER: "supabase",
			},
			local: {
				workspaceRoot: workspace,
				dbPath: join(workspace, "mode-override.sqlite"),
			},
		});
		expect(adapter.capabilities.name).toBe("supabase");
		await rm(workspace, { recursive: true, force: true });
	});

	it("creates a hosted adapter when mode='hosted' (kills BlockStatement/ConditionalExpression mutants on the if-branch)", () => {
		const adapter = createAstropressProjectAdapter({
			mode: "hosted",
			env: {
				ASTROPRESS_HOSTED_PROVIDER: "supabase",
				SUPABASE_URL: "https://x.supabase.co",
				SUPABASE_SERVICE_ROLE_KEY: "test-service-key",
			},
		});
		// Hosted adapter advertises hostedAdmin capability.
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("explicit options.local.provider overrides projectEnv.localProvider (kills ?? to && in local branch)", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-local-prov-"));
		// env says sqlite; options.local.provider="supabase" must win and
		// route through the supabase-sqlite adapter (capabilities.name="supabase").
		const adapter = createAstropressProjectAdapter({
			mode: "local",
			env: { ASTROPRESS_LOCAL_PROVIDER: "sqlite" },
			local: {
				provider: "supabase",
				workspaceRoot: workspace,
				dbPath: join(workspace, "local-prov.sqlite"),
			},
		});
		expect(adapter.capabilities.name).toBe("supabase");
		await rm(workspace, { recursive: true, force: true });
	});
});

