// @vitest-environment jsdom
import { beforeEach, describe, expect, it } from "vitest";
import "../../web-components/section-editor";

function mount(initial: object): HTMLElement {
	const host = document.createElement("ap-section-editor");
	host.innerHTML = `
<script type="application/json" data-section-editor-state>${JSON.stringify(initial)}</script>
<input type="hidden" id="payload" data-section-editor-input />
<div data-section-editor-list></div>
<button type="button" data-section-editor-add>Add</button>
<dialog data-section-editor-add-dialog>
  <div data-section-editor-templates></div>
  <div data-section-editor-kinds></div>
</dialog>
`;
	document.body.appendChild(host);
	return host;
}

describe("ap-section-editor", () => {
	beforeEach(() => {
		document.body.innerHTML = "";
	});

	it("seeds the hidden input with the initial sections", () => {
		mount({
			sections: [
				{
					id: "s1",
					kind: "hero",
					headline: "Hi",
					alignment: "center",
				},
			],
			templates: [],
		});
		const input = document.querySelector<HTMLInputElement>("#payload");
		expect(input).not.toBeNull();
		const parsed = JSON.parse(input?.value ?? "{}") as {
			sections: Array<{ kind: string; headline: string }>;
		};
		expect(parsed.sections).toHaveLength(1);
		expect(parsed.sections[0].kind).toBe("hero");
		expect(parsed.sections[0].headline).toBe("Hi");
	});

	it("renders one card per section", () => {
		mount({
			sections: [
				{ id: "a", kind: "hero", headline: "A", alignment: "start" },
				{
					id: "b",
					kind: "rich-text",
					html: "<p>Hello</p>",
				},
			],
			templates: [],
		});
		const cards = document.querySelectorAll(".ap-section-card");
		expect(cards.length).toBe(2);
	});

	it("renders the empty state when no sections", () => {
		mount({ sections: [], templates: [] });
		const empty = document.querySelector(".ap-section-editor__empty");
		expect(empty).not.toBeNull();
	});

	it("updates the hidden input when an input value changes", () => {
		mount({
			sections: [{ id: "x", kind: "hero", headline: "Old", alignment: "start" }],
			templates: [],
		});
		const headlineInput = document.querySelector<HTMLInputElement>('[data-field="headline"]');
		expect(headlineInput).not.toBeNull();
		if (!headlineInput) return;
		headlineInput.value = "New headline";
		headlineInput.dispatchEvent(new Event("input", { bubbles: true }));
		const payload = JSON.parse(
			document.querySelector<HTMLInputElement>("#payload")?.value ?? "{}",
		) as { sections: Array<{ headline: string }> };
		expect(payload.sections[0].headline).toBe("New headline");
	});
});

tests/integration-secret-dump-leak.test..source:
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { readAstropressSqliteSchemaSql } from "../src/sqlite-bootstrap.js";
import { createIntegrationsRepository } from "../src/sqlite-runtime/integrations";

/**
 * Privacy invariant: a sqlite dump of the live database must never
 * contain integration plaintext. Ciphertext is fine; raw API keys
 * are the bug. Mirrors design doc §4.4.
 *
 * Uses an on-disk database (rather than `:memory:`) so we can VACUUM
 * INTO a sibling file and grep its bytes for the canary.
 */

const ROOT = "test-root-current";
const NOW = "2026-05-02T12:00:00.000Z";
const CANARY = "PLAINTEXT-CANARY-DUMP-Q4F7";

let tmp: string;
let dbPath: string;
let db: DatabaseSync;

beforeEach(() => {
	tmp = mkdtempSync(join(tmpdir(), "astropress-secret-dump-"));
	dbPath = join(tmp, "test.db");
	db = new DatabaseSync(dbPath);
	db.exec(readAstropressSqliteSchemaSql());
	db.exec("PRAGMA foreign_keys = ON");
});

afterEach(() => {
	try {
		db.close();
	} catch {
		// already closed
	}
	rmSync(tmp, { recursive: true, force: true });
});

describe("integration_secrets sqlite-dump privacy", () => {
	it("plaintext canary never appears in a VACUUM INTO of the database", async () => {
		const repo = createIntegrationsRepository({
			getDb: () => db as never,
			now: () => NOW,
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: '{"baseUrl":"https://example.test"}',
				secretFields: { apiKey: CANARY },
				now: NOW,
			},
			ROOT,
		);

		const dumpPath = join(tmp, "dump.db");
		db.exec(`VACUUM INTO '${dumpPath.replace(/'/g, "''")}'`);

		const bytes = readFileSync(dumpPath);
		const text = bytes.toString("binary");
		expect(text).not.toContain(CANARY);
	});

	it("plaintext canary stays absent after disconnect", async () => {
		const repo = createIntegrationsRepository({
			getDb: () => db as never,
			now: () => NOW,
		});
		await repo.connect(
			{
				domain: "newsletter",
				provider: "listmonk",
				configJson: "{}",
				secretFields: { apiKey: CANARY },
				now: NOW,
			},
			ROOT,
		);
		expect(repo.disconnect("newsletter", "listmonk")).toBe(true);

		const dumpPath = join(tmp, "dump-after-disconnect.db");
		db.exec(`VACUUM INTO '${dumpPath.replace(/'/g, "''")}'`);
		const bytes = readFileSync(dumpPath);
		expect(bytes.toString("binary")).not.toContain(CANARY);
	});
});

