import { describe, expect, it } from "vitest";

import type { ProviderKind } from "../src/platform-contracts";
import {
	getFirstPartyProviderTarget,
	listFirstPartyProviderTargets,
} from "../src/provider-targets";

describe("provider targets", () => {
	it("includes the required first-party providers for v1", () => {
		const providers = listFirstPartyProviderTargets().map((provider) => provider.id);
		expect(providers).toEqual(expect.arrayContaining(["github-pages", "cloudflare", "supabase"]));
	});

	it("describes github pages as a static publish target without a database", () => {
		const provider = getFirstPartyProviderTarget("github-pages");
		expect(provider.runtime).toBe("static");
		expect(provider.capabilities.staticPublishing).toBe(true);
		expect(provider.capabilities.database).toBe(false);
		expect(provider.capabilities.gitSync).toBe(true);
	});

	it("describes cloudflare and supabase as admin-capable runtimes", () => {
		for (const providerId of ["cloudflare", "supabase"] as const) {
			const provider = getFirstPartyProviderTarget(providerId);
			expect(provider.adminSurface).toBe("astropress");
			expect(provider.capabilities.hostedAdmin).toBe(true);
			expect(provider.capabilities.database).toBe(true);
		}
	});

	it("listFirstPartyProviderTargets returns no duplicates", () => {
		const ids = listFirstPartyProviderTargets().map((t) => t.id);
		expect(new Set(ids).size).toBe(ids.length);
	});

	it("entries carry the FirstPartyProviderTarget shape", () => {
		for (const t of listFirstPartyProviderTargets()) {
			expect(typeof t.id).toBe("string");
			expect(t.id.length).toBeGreaterThan(0);
			expect(typeof t.label).toBe("string");
			expect(typeof t.runtime).toBe("string");
			expect(typeof t.canonicalDeploySurface).toBe("string");
			expect(["astropress", "provider-managed"]).toContain(t.adminSurface);
		}
	});

	const ALL: ProviderKind[] = ["github-pages", "cloudflare", "supabase", "custom"];

	it.each(ALL)("getFirstPartyProviderTarget — id matches for %s", (key) => {
		const t = getFirstPartyProviderTarget(key);
		expect(t).toBeDefined();
		expect(t.id).toBe(key);
	});

	it("returns the same reference across calls for the same key", () => {
		const a = getFirstPartyProviderTarget("cloudflare");
		const b = getFirstPartyProviderTarget("cloudflare");
		expect(a).toBe(b);
	});
});

tests/access-action-registry.test.ts.source:
import { afterEach, describe, expect, test } from "vitest";

import {
	_resetAccessActionRegistryForTests,
	getAccessAction,
	listAccessActions,
	registerAccessAction,
} from "../src/access";

afterEach(() => {
	_resetAccessActionRegistryForTests();
});

describe("access action registry", () => {
	test("built-in actions are registered at module load", () => {
		const all = listAccessActions();
		expect(all.length).toBeGreaterThan(20);
		expect(getAccessAction("posts:edit")?.pluginId).toBe("core");
		expect(getAccessAction("roles:manage")?.pluginId).toBe("core");
	});

	test("plugin can register a new action", () => {
		registerAccessAction({
			id: "myplugin:doThing",
			description: "Do the thing",
			pluginId: "my-plugin",
		});
		expect(getAccessAction("myplugin:doThing")?.pluginId).toBe("my-plugin");
	});

	test("re-registering same id by same plugin is allowed (idempotent setup)", () => {
		registerAccessAction({
			id: "myplugin:thing",
			description: "v1",
			pluginId: "my-plugin",
		});
		expect(() =>
			registerAccessAction({
				id: "myplugin:thing",
				description: "v2 (updated)",
				pluginId: "my-plugin",
			}),
		).not.toThrow();
		expect(getAccessAction("myplugin:thing")?.description).toBe("v2 (updated)");
	});

	test("a different plugin cannot hijack an existing action id", () => {
		registerAccessAction({
			id: "myplugin:thing",
			description: "owned by my-plugin",
			pluginId: "my-plugin",
		});
		expect(() =>
			registerAccessAction({
				id: "myplugin:thing",
				description: "stolen",
				pluginId: "other-plugin",
			}),
		).toThrow(/already registered/);
	});

	test("listAccessActions returns alphabetically sorted IDs", () => {
		const ids = listAccessActions().map((a) => a.id);
		const sorted = [...ids].sort();
		expect(ids).toEqual(sorted);
	});

	test("_resetAccessActionRegistryForTests clears plugin actions and re-seeds built-ins", () => {
		registerAccessAction({
			id: "ephemeral:goAway",
			description: "ephemeral",
			pluginId: "ephemeral-plugin",
		});
		expect(getAccessAction("ephemeral:goAway")).toBeDefined();
		_resetAccessActionRegistryForTests();
		expect(getAccessAction("ephemeral:goAway")).toBeUndefined();
		expect(getAccessAction("posts:edit")?.pluginId).toBe("core");
	});
});

tests/path-helpers.test.ts.source:
import { describe, expect, it } from "vitest";

import { normalizeRoutePath, stripTrailingSlashes } from "../src/path-helpers";

describe("stripTrailingSlashes", () => {
	it("returns the input unchanged when there are no trailing slashes", () => {
		expect(stripTrailingSlashes("https://example.com")).toBe("https://example.com");
		expect(stripTrailingSlashes("/about")).toBe("/about");
		expect(stripTrailingSlashes("")).toBe("");
	});

	it("strips a single trailing slash", () => {
		expect(stripTrailingSlashes("https://example.com/")).toBe("https://example.com");
		expect(stripTrailingSlashes("/about/")).toBe("/about");
	});

	it("strips multiple trailing slashes", () => {
		expect(stripTrailingSlashes("/about///")).toBe("/about");
		expect(stripTrailingSlashes("https://example.com////")).toBe("https://example.com");
	});

	it("collapses an all-slash string to empty", () => {
		expect(stripTrailingSlashes("/")).toBe("");
		expect(stripTrailingSlashes("////")).toBe("");
	});

	it("does not touch slashes that are not at the end", () => {
		expect(stripTrailingSlashes("/a/b/c")).toBe("/a/b/c");
		expect(stripTrailingSlashes("/a//b")).toBe("/a//b");
	});

	it("does not strip a leading slash", () => {
		expect(stripTrailingSlashes("/")).toBe("");
		expect(stripTrailingSlashes("/leading")).toBe("/leading");
	});

	it("handles a single character input", () => {
		expect(stripTrailingSlashes("a")).toBe("a");
		expect(stripTrailingSlashes("/")).toBe("");
	});
});

describe("normalizeRoutePath", () => {
	it("returns '/' for empty input", () => {
		expect(normalizeRoutePath("")).toBe("/");
	});

	it("returns '/' for an all-slash string", () => {
		expect(normalizeRoutePath("/")).toBe("/");
		expect(normalizeRoutePath("//")).toBe("/");
		expect(normalizeRoutePath("////")).toBe("/");
	});

	it("strips trailing slashes from a normal route", () => {
		expect(normalizeRoutePath("/about")).toBe("/about");
		expect(normalizeRoutePath("/about/")).toBe("/about");
		expect(normalizeRoutePath("/about///")).toBe("/about");
	});

	it("preserves interior slashes", () => {
		expect(normalizeRoutePath("/a/b/c/")).toBe("/a/b/c");
		expect(normalizeRoutePath("/a//b/")).toBe("/a//b");
	});
});

